function hexToRGBA(hex, alpha) {
    hex = hex.replace("#", "");
    return [
        parseInt(hex.substr(0, 2), 16) / 255,
        parseInt(hex.substr(2, 2), 16) / 255,
        parseInt(hex.substr(4, 2), 16) / 255,
        alpha
    ];
}

// ================= 自动更新 =================
var TOOLBOX_SCRIPT_VERSION = "1.0.8";
var TOOLBOX_UPDATER_EXE = "toolbox_updater.exe";
var TOOLBOX_UPDATER_PY = "toolbox_updater.py";

function toolboxGetScriptFolder() {
    try {
        return new File($.fileName).parent;
    } catch (e) {
        return null;
    }
}

function toolboxFindUpdater(folder) {
    var exeNames = [TOOLBOX_UPDATER_EXE, "工具箱更新器.exe"];
    var pyNames = [TOOLBOX_UPDATER_PY, "工具箱更新器.py"];
    var i, f;
    for (i = 0; i < exeNames.length; i++) {
        f = new File(folder.fsName + "/" + exeNames[i]);
        if (f.exists) return { kind: "exe", fileName: exeNames[i] };
    }
    for (i = 0; i < pyNames.length; i++) {
        f = new File(folder.fsName + "/" + pyNames[i]);
        if (f.exists) return { kind: "py", fileName: pyNames[i] };
    }
    return null;
}

function toolboxRunUpdater(silent, detach) {
    if (typeof detach === "undefined") detach = true;
    var folder = toolboxGetScriptFolder();
    if (!folder || !folder.exists) {
        if (!silent) alert("无法定位脚本目录");
        return false;
    }
    var updater = toolboxFindUpdater(folder);
    if (!updater) {
        if (!silent) {
            alert(
                "未找到更新器。\n请确保同目录存在：\n" +
                TOOLBOX_UPDATER_EXE + "\n或 " + TOOLBOX_UPDATER_PY
            );
        }
        return false;
    }
    var args = silent ? " --silent" : "";
    var stamp = new Date().getTime();
    var batPath = Folder.temp.fsName + "/toolbox_updater_run_" + stamp + ".bat";
    var batFile = new File(batPath);
    var batLines = ["@echo off", 'cd /d "' + folder.fsName + '"'];
    if (updater.kind === "exe") {
        batLines.push('start "" /MIN "' + updater.fileName + '"' + args);
    } else {
        batLines.push("where py >nul 2>&1");
        batLines.push("if %errorlevel%==0 (");
        batLines.push('  start "" /MIN py -3 "' + updater.fileName + '"' + args);
        batLines.push(") else (");
        batLines.push('  start "" /MIN python "' + updater.fileName + '"' + args);
        batLines.push(")");
    }
    try {
        batFile.open("w");
        batFile.write(batLines.join("\r\n") + "\r\n");
        batFile.close();
        if (detach) {
            var vbsPath = Folder.temp.fsName + "/toolbox_updater_run_" + stamp + ".vbs";
            var vbsFile = new File(vbsPath);
            var batEsc = batPath.replace(/\\/g, "\\\\").replace(/"/g, '""');
            vbsFile.open("w");
            vbsFile.write(
                'Set WshShell = CreateObject("WScript.Shell")\r\n' +
                'WshShell.Run "cmd /c ""' + batEsc + '""", 7, False\r\n'
            );
            vbsFile.close();
            system.callSystem('wscript.exe //B //Nologo "' + vbsPath + '"');
            // 勿立即删除 bat：WshShell.Run 异步执行，删早会导致更新器无法启动
        } else {
            system.callSystem('cmd /c "' + batPath + '"');
            if (batFile.exists) batFile.remove();
        }
        return true;
    } catch (e) {
        if (!silent) alert("启动更新器失败:\n" + e.toString());
        return false;
    }
}

function toolboxCheckUpdateOnStartup() {
    var folder = toolboxGetScriptFolder();
    if (!folder) return;
    var stampFile = new File(folder.fsName + "/.toolbox_update_check");
    var now = new Date().getTime();
    var dayMs = 24 * 60 * 60 * 1000;
    if (stampFile.exists) {
        stampFile.open("r");
        var last = parseInt(stampFile.read(), 10);
        stampFile.close();
        if (!isNaN(last) && (now - last) < dayMs) return;
    }
    stampFile.open("w");
    stampFile.write(String(now));
    stampFile.close();
    toolboxRunUpdater(true, true);
}

