var pathInput = null;


//=========================
// 自动获取路径文件
//=========================
function getPathFile(){
    var scriptFolder = File($.fileName).parent;
    var pathFile = new File(
        scriptFolder.fsName + "/ToolBoxMasterPath.txt"
    );
    // 不存在则自动创建
    if(!pathFile.exists){
        var defaultFolder = new Folder(
            "C:\\选择工具箱大师中转站新路径"
        );
        if(!defaultFolder.exists){
            defaultFolder.create();
        }
        pathFile.encoding = "UTF-8";
        if(pathFile.open("w")){
            pathFile.write(
                defaultFolder.fsName
            );
            pathFile.close();
        }
    }
    return pathFile;
}



//=========================
// 写入路径
//=========================
function writeToolBoxPath(path){

    var pathFile = getPathFile();

    pathFile.encoding = "UTF-8";

    if(pathFile.open("w")){

        pathFile.write(path);

        pathFile.close();

        // 删除默认文件夹
        var defaultFolder = new Folder(
            "C:\\选择工具箱大师中转站新路径"
        );

        if(defaultFolder.exists){

            try{
                defaultFolder.remove();
            }catch(err){}

        }

    }

}



//=========================
// 保存路径文件
//=========================
function getSaveFile(){
    return getPathFile();
}



//=========================
// 读取路径
//=========================
function loadPath(){
    var file = getSaveFile();
    var path = "C:\\选择工具箱大师中转站新路径";
    if(file.exists){
        file.encoding = "UTF-8";
        if(file.open("r")){
            var txt = file.read();
            file.close();
            if(txt !== ""){
                path = txt;
            }
        }
    }
    var folder = new Folder(path);
    if(folder.exists){
        toolboxFolder = folder;
    }else{
        toolboxFolder = new Folder(
            "C:\\选择工具箱大师中转站新路径"
        );
    }
}



//=========================
// 保存路径
//=========================
function savePath(path){


    writeToolBoxPath(path);


}


