        //锚点
        function moveAnchor(row, col, ignoreMasks) {
            // 获取当前时间指示器的位置
            var curTime = app.project.activeItem.time;
            var theLayers = app.project.activeItem.selectedLayers;

            if (theLayers.length == 0) {
                alert("您没有选择任何图层", "提示");
                return;
            }

            for (var num = 0; num < theLayers.length; num++) {
                var theLayer = theLayers[num];
                if (theLayer instanceof CameraLayer) {
                    if (theLayers.length == 1) {
                        alert("不支持摄像机图层", "提示");
                    }
                    continue;
                }

                var noMasks = true;
                if (!ignoreMasks && theLayer.mask.numProperties != 0) {
                    for (var i = 1; i <= theLayer.mask.numProperties; i++) {
                        if (theLayer.mask(i).maskMode != MaskMode.NONE) {
                            noMasks = false;
                        }
                    }
                }

                if (noMasks) {
            var x, y;

            // 根据行和列计算锚点位置
            switch (row) {
                case 0:
                    x = theLayer.scale.value[0] < 0 ? theLayer.sourceRectAtTime(curTime, false).width : 0;
                    break;
                case 1:
                    x = theLayer.sourceRectAtTime(curTime, false).width / 2;
                    break;
                case 2:
                    x = theLayer.scale.value[0] < 0 ? 0 : theLayer.sourceRectAtTime(curTime, false).width;
                    break;
                case 3:
                    x = theLayer.scale.value[0] < 0 ? theLayer.sourceRectAtTime(curTime, false).width - theLayer.sourceRectAtTime(curTime, false).width * cust1 : (theLayer.sourceRectAtTime(curTime, false).width * cust1);
                    break;
            }

            switch (col) {
                case 0:
                    y = theLayer.scale.value[1] < 0 ? theLayer.sourceRectAtTime(curTime, false).height : 0;
                    break;
                case 1:
                    y = theLayer.sourceRectAtTime(curTime, false).height / 2;
                    break;
                case 2:
                    y = theLayer.scale.value[1] < 0 ? 0 : theLayer.sourceRectAtTime(curTime, false).height;
                    break;
                case 3:
                    y = theLayer.scale.value[1] < 0 ? theLayer.sourceRectAtTime(curTime, false).height - theLayer.sourceRectAtTime(curTime, false).height * cust2 : (theLayer.sourceRectAtTime(curTime, false).height * cust2);
                    break;
            }


            // 如果图层是文本或形状图层，调整锚点位置
            if (theLayer instanceof TextLayer || theLayer instanceof ShapeLayer) {
                x += theLayer.sourceRectAtTime(curTime, false).left;
                y += theLayer.sourceRectAtTime(curTime, false).top;
            }

        } else {
            // 处理有遮罩的情况
            var xBounds = [];
            var yBounds = [];
            var numMasks = theLayer.mask.numProperties;

            for (var i = 1; i <= numMasks; i++) {
                var numVerts = theLayer.mask(i).maskShape.value.vertices.length;
                if (theLayer.mask(i).maskMode == MaskMode.NONE) continue;
                for (var j = 0; j < numVerts; j++) {
                    var curVerts = theLayer.mask(i).maskShape.valueAtTime(curTime, false).vertices[j];
                    xBounds.push(curVerts[0]);
                    yBounds.push(curVerts[1]);
                }
            }

            // 排序并获取边界值
            xBounds.sort(function(a, b) { return a - b; });
            yBounds.sort(function(a, b) { return a - b; });

            var xl = xBounds.shift();
            var xh = xBounds.pop();
            var yl = yBounds.shift();
            var yh = yBounds.pop();

            // 如果是文本或形状图层，调整边界
 if (theLayer instanceof TextLayer || theLayer instanceof ShapeLayer) {
               var xl2 = theLayer.sourceRectAtTime(curTime, false).left;
               var xh2 = xl2 + theLayer.sourceRectAtTime(curTime, false).width;
               var yl2 = theLayer.sourceRectAtTime(curTime, false).top;
               var yh2 = yl2 + theLayer.sourceRectAtTime(curTime, false).height;
               
               if (xl < xl2) {xl = xl2;}
               if (xh > xh2) {xh = xh2;}
               if (yl < yl2) {yl = yl2;}
               if (yh > yh2) {yh = yh2;}
            } 

            // 计算新的锚点位置
            switch (row) {
                case 0:
                    if(theLayer.scale.value[0]<0){
                        var x = xh;
                    }else{
                        var x = xl;
                    }
                    break;
                case 1:
                    var x = xl + ((xh-xl)/2);
                    break;
                case 2:
                    if(theLayer.scale.value[0]<0){
                        var x = xl;
                    }else{
                        var x = xh;
                    }
                    break;
                case 3:
                    if(theLayer.scale.value[0]<0){
                        var x = xh - ((xh-xl)*cust1);
                    }else{
                        var x = xl + ((xh-xl)*cust1);
                    }
                    break;
                default:
            }
            
            switch (col) {
                case 0:
                    if (theLayer.scale.value[1]<0){
                        var y = yh;
                    }else{
                        var y = yl;
                    }
                    break;
                case 1:
                    var y = yl + ((yh-yl)/2);
                    break;
                case 2:
                    if (theLayer.scale.value[1]<0){
                        var y = yl;
                    }else{
                        var y = yh;
                    }
                    break;
                case 3:
                    if (theLayer.scale.value[1]<0){
                        var y = yh - ((yh-yl)*cust2);
                    }else{
                        var y = yl + ((yh-yl)*cust2);
                    }
                    break;;
                default:
            }
        }

        // 设置新的锚点位置
        if (theLayer.anchorPoint.isTimeVarying) {

            theComp = app.project.activeItem;
            theLayer.anchorPoint.setValueAtTime(theComp.time, [x,y]);
        } else {

            var curAnchor = theLayer.anchorPoint.value;

            var xMove = (x - curAnchor[0]) * (theLayer.scale.value[0]/100);
            var yMove = (y - curAnchor[1])  * (theLayer.scale.value[1]/100);
            
            var posEx = false;
            if(theLayer.position.expressionEnabled) {
                theLayer.position.expressionEnabled = false;
                posEx = true;
            }

            var dupLayer = theLayer.duplicate(); //复制一个图层
            
            var oldParent = theLayer.parent;

            dupLayer.moveToEnd();
            if (dupLayer.scale.isTimeVarying) {
                dupLayer.scale.setValueAtTime(app.project.activeItem.time, [100,100])
            } else {
                dupLayer.scale.setValue([100,100]);
            }

            theLayer.parent = dupLayer;

            var theA = [theLayer.anchorPoint.value[0]*theLayer.scale.value[0]/100,theLayer.anchorPoint.value[1]*theLayer.scale.value[1]/100];

            theLayer.anchorPoint.setValue([x,y]);

            dupLayer.anchorPoint.setValue(dupLayer.anchorPoint.value-([x*theLayer.scale.value[0]/100,y*theLayer.scale.value[1]/100]-theA));

            theLayer.parent = oldParent;
            if(posEx) {
                theLayer.position.expressionEnabled = true;
            }

            dupLayer.remove();
        }
    }
}

