butoumingdubutton.onClick = function () {
    app.beginUndoGroup("添加不透明度关键帧");

    var keyState = ScriptUI.environment.keyboardState;
    var shiftKey = keyState.shiftKey;
    var ctrlKey = keyState.ctrlKey || keyState.metaKey;

    if (shiftKey) {
        ABoj(true);  // 淡入开始
    } else if (ctrlKey) {
        ABoj(false); // 淡出开始
    } else {
        addKeyframeToSelectedLayers("不透明度", "opacity");
        showkey();
    }

    app.endUndoGroup();
};

function showkey() {
    app.executeCommand(2387);
    app.executeCommand(2387);
    }

// 获取选中图层
function getSelectedLayers() {
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length > 0) {
            return selectedLayers;
        } else {
            alert("请先选择一个图层！");
        }
    } else {
        alert("请先打开一个合成！");
    }
    return null;
}

// 不透明度动画函数（淡入 or 淡出开始）
function ABoj(startWithFadeIn) {
    var comp = app.project.activeItem;
    var layers = getSelectedLayers();
    if (!layers || !comp) return;

    var frame = 1 / comp.frameRate;
    var currentTime = comp.time;

    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var opacity = layer.property("ADBE Transform Group").property("ADBE Opacity");

        if (startWithFadeIn) {
            opacity.setValueAtTime(currentTime, 0);
            opacity.setValueAtTime(currentTime + frame, 100);
            opacity.setValueAtTime(currentTime + 2 * frame, 0);
            opacity.setValueAtTime(currentTime + 3 * frame, 100);
        } else {
            opacity.setValueAtTime(currentTime, 100);
            opacity.setValueAtTime(currentTime + frame, 0);
            opacity.setValueAtTime(currentTime + 2 * frame, 100);
            opacity.setValueAtTime(currentTime + 3 * frame, 0);
        }
    }
}
    
// 为多个图层添加关键帧，并设置相隔X帧
function addKeyframeToSelectedLayers(property, propertyType) {
    var layers = getSelectedLayers();
    if (layers) {
        var time = app.project.activeItem.time;
        var keyframeTime = time + (frameValue / app.project.activeItem.frameRate); // 相隔X帧

        for (var i = 0; i < layers.length; i++) {
            var layer = layers[i];
            if (propertyType === "anchorPoint") {
                layer.transform.anchorPoint.setValueAtTime(time, layer.transform.anchorPoint.value);
                layer.transform.anchorPoint.setValueAtTime(keyframeTime, layer.transform.anchorPoint.value);
            } else if (propertyType === "position") {
                layer.transform.position.setValueAtTime(time, layer.transform.position.value);
                layer.transform.position.setValueAtTime(keyframeTime, layer.transform.position.value);
            } else if (propertyType === "scale") {
                layer.transform.scale.setValueAtTime(time, layer.transform.scale.value);
                layer.transform.scale.setValueAtTime(keyframeTime, layer.transform.scale.value);
            } else if (propertyType === "rotation") {
                layer.transform.rotation.setValueAtTime(time, layer.transform.rotation.value);
                layer.transform.rotation.setValueAtTime(keyframeTime, layer.transform.rotation.value);
            } else if (propertyType === "opacity") {
                layer.transform.opacity.setValueAtTime(time, layer.transform.opacity.value);
                layer.transform.opacity.setValueAtTime(keyframeTime, layer.transform.opacity.value);
            }
        }
    }
}

