// =======================================================
// ================= UI 实时更新（不改关键帧）================
// =======================================================
var isSyncing = false;

// =============================
// UI同步
// =============================

function syncEaseOut(v) {
    if (isSyncing) return;

    isSyncing = true;

    easeOutSlider.value = v;
    easeOutValueText.text = Math.round(v);

    if (EaseCheckbox.value) {
        easeInSlider.value = 101 - v;
        easeInValueText.text = Math.round(101 - v);
    }

    isSyncing = false;
}

function syncEaseIn(v) {
    if (isSyncing) return;

    isSyncing = true;

    easeInSlider.value = 101 - v;
    easeInValueText.text = Math.round(v);

    if (EaseCheckbox.value) {
        easeOutSlider.value = v;
        easeOutValueText.text = Math.round(v);
    }

    isSyncing = false;
}

// =============================
// 应用缓动
// =============================

function executeEase(v, isIn) {

    app.beginUndoGroup(isIn ? "Ease In" : "Ease Out");

    if (isIn) {
        applyEaseIn(v);
        if (EaseCheckbox.value) applyEaseOut(v);
    } else {
        applyEaseOut(v);
        if (EaseCheckbox.value) applyEaseIn(v);
    }

    app.endUndoGroup();
}

// =============================
// 易出
// =============================

easeOutSlider.onChanging = function () {
    syncEaseOut(Math.round(this.value));
};

easeOutSlider.onChange = function () {
    executeEase(Math.round(this.value), false);
};

easeOutValueText.onChange = function () {

    var v = parseInt(this.text, 10);

    if (isNaN(v)) return;

    v = Math.max(1, Math.min(100, v));

    syncEaseOut(v);
    executeEase(v, false);
};

// =============================
// 易入
// =============================

easeInSlider.onChanging = function () {
    syncEaseIn(Math.round(101 - this.value));
};

easeInSlider.onChange = function () {
    executeEase(Math.round(101 - this.value), true);
};

easeInValueText.onChange = function () {

    var v = parseInt(this.text, 10);

    if (isNaN(v)) return;

    v = Math.max(1, Math.min(100, v));

    syncEaseIn(v);
    executeEase(v, true);
};

// ======================================================
// 核心执行
// ======================================================

function applyEaseIn(val) {
    applyEase(val, true);
}

function applyEaseOut(val) {
    applyEase(val, false);
}

function applyEase(val, isIn) {

    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;

    for (var i = 0; i < layers.length; i++) {

        var props = layers[i].selectedProperties;

        for (var j = 0; j < props.length; j++) {

            var prop = props[j];

            if (!prop.canVaryOverTime || prop.selectedKeys.length === 0)
                continue;

            for (var k = 0; k < prop.selectedKeys.length; k++) {

                var key = prop.selectedKeys[k];

                var inEaseOld = prop.keyInTemporalEase(key)[0];
                var outEaseOld = prop.keyOutTemporalEase(key)[0];

                var easeIn = isIn
                    ? new KeyframeEase(0, val)
                    : new KeyframeEase(
                        inEaseOld.speed,
                        inEaseOld.influence
                    );

                var easeOut = isIn
                    ? new KeyframeEase(
                        outEaseOld.speed,
                        outEaseOld.influence
                    )
                    : new KeyframeEase(0, val);

                setEase(prop, key, easeIn, easeOut);
            }
        }
    }
}

// ======================================================
// 设置缓动
// ======================================================

function setEase(prop, key, easeIn, easeOut) {

    var dim = 1;

    switch (prop.propertyValueType) {

        case PropertyValueType.TwoD:
        case PropertyValueType.TwoD_SPATIAL:
            dim = 2;
            break;

        case PropertyValueType.ThreeD:
        case PropertyValueType.ThreeD_SPATIAL:
            dim = 3;
            break;
    }

    var ins = [];
    var outs = [];

    for (var i = 0; i < dim; i++) {
        ins.push(easeIn);
        outs.push(easeOut);
    }

    prop.setTemporalEaseAtKey(key, ins, outs);
}
