function width_height() {
     var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        app.beginUndoGroup("Center Anchor and Layer");
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length > 0) {
            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                var rect;
                if (layer instanceof ShapeLayer || layer instanceof TextLayer) {
                    rect = layer.sourceRectAtTime(comp.time, false);
                } else if (layer.source && layer.source.width && layer.source.height) {
                    rect = { width: layer.source.width, height: layer.source.height, left: 0, top: 0 };
                } else {
                    layer.anchorPoint.setValue([0, 0]);
                    layer.position.setValue([comp.width / 2, comp.height / 2]);
                    continue;
                }
                // 设置锚点
                layer.anchorPoint.setValue([rect.width / 2 + rect.left, rect.height / 2 + rect.top]);
                // 居中位置
                var centerPosition = [comp.width / 2, comp.height / 2];
                // 如果有关键帧，自动在当前时间添加关键帧
                if (layer.position.numKeys > 0) {
                    var keyTime = comp.time; // 使用当前时间
                    layer.position.setValueAtTime(keyTime, centerPosition);
                } else {
                    layer.position.setValue(centerPosition);
                }
            }
        } else {
            alert("请先选择图层。");
        }
        app.endUndoGroup();
    } else {
        alert("请先打开一个合成。");
    }
};

function width() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请先打开一个合成并选中图层");
        return;
    }
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请至少选中一个图层");
        return;
    }
    app.beginUndoGroup("水平居中");
    app.executeCommand(10312);
    var compCenterX = comp.width / 2;
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        if (layer instanceof AVLayer && layer.canSetCollapseTransformation) {
            var layerWidth = layer.source.width * layer.scale.value[0] / 100;
            var anchorX = layer.anchorPoint.value[0];
            layer.position.setValue([compCenterX + anchorX - layerWidth / 2, layer.position.value[1]]);
        } else {
            // 默认方式：仅将 position.x 设为合成中心
            var pos = layer.position.value;
            pos[0] = compCenterX;
            layer.position.setValue(pos);
        }
    }
    app.endUndoGroup();
}

function height() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请先打开一个合成并选中图层");
        return;
    }
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请至少选中一个图层");
        return;
    }
    app.beginUndoGroup("垂直居中");
    app.executeCommand(10312);
    var compCenterY = comp.height / 2;
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        if (layer instanceof AVLayer && layer.canSetCollapseTransformation) {
            var layerHeight = layer.source.height * layer.scale.value[1] / 100;
            var anchorY = layer.anchorPoint.value[1];
            layer.position.setValue([layer.position.value[0], compCenterY + anchorY - layerHeight / 2]);
        } else {
            // 默认方式：仅将 position.y 设为合成中心
            var pos = layer.position.value;
            pos[1] = compCenterY;
            layer.position.setValue(pos);
        }
    }
    app.endUndoGroup();
}

