// 持续时间输入框
var timeGroup = anchorGroup.add("group");
timeGroup.orientation = "row";
var durationGroup = timeGroup.add("Panel");
durationGroup.orientation = "column";
durationGroup.spacing = 1;
durationGroup.margins = 0;

var duration1 = durationGroup.add("group");
duration1.orientation = "row";
duration1.spacing = 2;
duration1.margins = 0;

// 分秒帧三个输入框
var minutesInput = duration1.add("edittext", undefined, "0");
duration1.add("statictext", undefined, "分");
var secondsInput = duration1.add("edittext", undefined, "30");
duration1.add("statictext", undefined, "秒");
var framesInput = duration1.add("edittext", undefined, "0");
duration1.add("statictext", undefined, "帧");

minutesInput.characters = 2;
secondsInput.characters = 2;
framesInput.characters = 2;

var duration2 = durationGroup.add("group");
duration2.orientation = "row";
duration2.spacing = 2;
duration2.margins = 0;
var getLayerDurationButton = duration2.add("button", [0, 0, 90, 30], "选定图层时间");
var confirmButton = duration2.add("button", [0, 0, 40, 30], "time");

// 解析三个输入框的值
function parseDurationInputs() {
    var minutes = parseInt(minutesInput.text) || 0;
    var seconds = parseInt(secondsInput.text) || 0;
    var frames = parseInt(framesInput.text) || 0;

    return { minutes: minutes, seconds: seconds, frames: frames };
}

// 自动处理进位
function normalizeDuration(parsed, frameRate) {
    if (parsed.frames >= frameRate) {
        parsed.seconds += Math.floor(parsed.frames / frameRate);
        parsed.frames = parsed.frames % frameRate;
    }
    if (parsed.seconds >= 60) {
        parsed.minutes += Math.floor(parsed.seconds / 60);
        parsed.seconds = parsed.seconds % 60;
    }
    return parsed;
}

// 当任意输入框变化时自动规范化
function onDurationInputChange() {
    var parsed = parseDurationInputs();
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        parsed = normalizeDuration(parsed, comp.frameRate);
    }
    minutesInput.text = parsed.minutes;
    secondsInput.text = parsed.seconds;
    framesInput.text = parsed.frames;
}

minutesInput.onChange = onDurationInputChange;
secondsInput.onChange = onDurationInputChange;
framesInput.onChange = onDurationInputChange;

// 获取选定图层的持续时间
getLayerDurationButton.onClick = function () {
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length > 0) {
            var earliestInPoint = selectedLayers[0].inPoint;
            var latestOutPoint = selectedLayers[0].outPoint;
            for (var i = 1; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                earliestInPoint = Math.min(earliestInPoint, layer.inPoint);
                latestOutPoint = Math.max(latestOutPoint, layer.outPoint);
            }
            var layerDuration = latestOutPoint - earliestInPoint;
            var minutes = Math.floor(layerDuration / 60);
            var seconds = Math.floor(layerDuration % 60);
            var frames = Math.round((layerDuration % 1) * comp.frameRate);

            minutesInput.text = minutes;
            secondsInput.text = seconds;
            framesInput.text = frames;
        } else {
            alert("没有选中的图层。");
        }
    } else {
        alert("当前没有选中的合成或选中的项目不是合成。");
    }
};

confirmButton.onClick = function () {
    var parsed = parseDurationInputs();
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        alert("当前没有选中的合成或选中的项目不是合成。");
        return;
    }
    parsed = normalizeDuration(parsed, comp.frameRate);
    var totalSeconds = parsed.minutes * 60 + parsed.seconds + parsed.frames / comp.frameRate;

    app.beginUndoGroup("调整持续时间");
    comp.duration = totalSeconds;
    app.endUndoGroup();

    // 更新输入框显示
    minutesInput.text = parsed.minutes;
    secondsInput.text = parsed.seconds;
    framesInput.text = parsed.frames;
};

