function Smooth() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    app.beginUndoGroup("开始");
    for (var i = 0; i < comp.selectedLayers.length; i++) {
        var layer = comp.selectedLayers[i];
        for (var j = 0; j < layer.selectedProperties.length; j++) {
            var prop = layer.selectedProperties[j];
            if (!prop.canVaryOverTime) continue;

            for (var k = 0; k < prop.selectedKeys.length; k++) {
                var key = prop.selectedKeys[k];
                // 设置 BEZIER 缓动
                if (prop.isInterpolationTypeValid(KeyframeInterpolationType.BEZIER)) {
                    prop.setInterpolationTypeAtKey(key, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
                    prop.setTemporalContinuousAtKey(key, true);
                    prop.setTemporalAutoBezierAtKey(key, true);
                }
            }
        }
    }
    app.endUndoGroup();
};

// 函数：获取当前选中的关键帧
function getSelectedKeyframes() {
    var selectedKeyframes = [];
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        for (var i = 0; i < selectedLayers.length; i++) {
            var layer = selectedLayers[i];
            var selectedPropertiesList = layer.selectedProperties;
            for (var j = 0; j < selectedPropertiesList.length; j++) {
                var property = selectedPropertiesList[j];
                if (property.isTimeVarying && property.numKeys > 0) {
                    // 获取选中的关键帧索引
                    var selectedKeys = property.selectedKeys;
                    for (var k = 0; k < selectedKeys.length; k++) {
                        selectedKeyframes.push({
                            property: property,
                            keyIndex: selectedKeys[k]
                        });
                    }
                }
            }
        }
    }
    return selectedKeyframes;
}

// 函数：改变选中关键帧的插值类型
function changeSelectedKeyframeInterpolation(interpolationType) {
    var selectedKeyframes = getSelectedKeyframes();
    if (selectedKeyframes.length === 0) {
        alert("请先选中至少一个关键帧！");
        return;
    }

    for (var i = 0; i < selectedKeyframes.length; i++) {
        var keyframe = selectedKeyframes[i];
        var property = keyframe.property;
        var keyIndex = keyframe.keyIndex;

        // 获取当前关键帧的入点和出点插值类型
        app.executeCommand(2509);
        var currentInInterpolation = property.keyInInterpolationType(keyIndex);
        var currentOutInterpolation = property.keyOutInterpolationType(keyIndex);

        switch (interpolationType) {
            case "inLinear":
                // 入点设置为线性，出点保留当前插值类型
                property.setInterpolationTypeAtKey(keyIndex, KeyframeInterpolationType.LINEAR, currentOutInterpolation);
                break;
            case "outLinear":
                // 出点设置为线性，入点保留当前插值类型
                property.setInterpolationTypeAtKey(keyIndex, currentInInterpolation, KeyframeInterpolationType.LINEAR);
                break;
            case "inHold":
                // 入点设置为定格，出点保留当前插值类型
                property.setInterpolationTypeAtKey(keyIndex, KeyframeInterpolationType.HOLD, currentOutInterpolation);
                break;
            case "outHold":
                // 出点设置为定格，入点保留当前插值类型
                property.setInterpolationTypeAtKey(keyIndex, currentInInterpolation, KeyframeInterpolationType.HOLD);
                break;
        }
    }
}

// 【全新函数】无 app.executeCommand 版本
function changeSelectedKeyframeInterpolation_NoCmd(interpolationType) {
    var selectedKeyframes = getSelectedKeyframes();
    if (selectedKeyframes.length === 0) {
        alert("请先选中至少一个关键帧！");
        return;
    }

    for (var i = 0; i < selectedKeyframes.length; i++) {
        var keyframe = selectedKeyframes[i];
        var property = keyframe.property;
        var keyIndex = keyframe.keyIndex;

        // 直接原生API获取，不执行任何命令
        var currentInInterp = property.keyInInterpolationType(keyIndex);
        var currentOutInterp = property.keyOutInterpolationType(keyIndex);

        switch (interpolationType) {
            case "inHold2":
                property.setInterpolationTypeAtKey(keyIndex, KeyframeInterpolationType.HOLD, currentOutInterp);
                break;
            case "outHold2":
                property.setInterpolationTypeAtKey(keyIndex, currentInInterp, KeyframeInterpolationType.HOLD);
                break;
        }
    }
}

// 函数：改变选中关键帧的插值类型
function CHANGESelectedKeyframeInterpolation(interpolationType) {
    var selectedKeyframes = getSelectedKeyframes();
    if (selectedKeyframes.length === 0) {
        alert("请先选中至少一个关键帧！");
        return;
    }

    for (var i = 0; i < selectedKeyframes.length; i++) {
        var keyframe = selectedKeyframes[i];
        var property = keyframe.property;
        var keyIndex = keyframe.keyIndex;

        switch (interpolationType) {
            case "linear":
                property.setInterpolationTypeAtKey(keyIndex, KeyframeInterpolationType.LINEAR, KeyframeInterpolationType.LINEAR);
                break;
            case "hold":
                property.setInterpolationTypeAtKey(keyIndex, KeyframeInterpolationType.HOLD, KeyframeInterpolationType.HOLD);
                break;
        }
    }
}

