// ==================================================
// 颜色记忆设置
// ==================================================
var SETTINGS_SECTION = "My_Color_Picker";
var SETTINGS_KEY = "LastColorHex";
// 默认颜色（白色）
var currentHex = 0xFFFFFF;
var currentSolidColor = [1, 1, 1]; // AE RGB 0~1
// 读取记忆颜色
if (app.settings.haveSetting(SETTINGS_SECTION, SETTINGS_KEY)) {
    try {
        currentHex = parseInt(
            app.settings.getSetting(SETTINGS_SECTION, SETTINGS_KEY),
            10
        );
    } catch (e) {
        currentHex = 0xFFFFFF;
    }
}
// Hex → AE RGB
function hexToAERgb(hex) {
    var r = (hex >> 16) & 0xFF;
    var g = (hex >> 8) & 0xFF;
    var b = hex & 0xFF;
    return [r / 255, g / 255, b / 255];
}
// 初始化当前颜色
currentSolidColor = hexToAERgb(currentHex);
// ==================================================
// 右键颜色选择（带永久记忆）
// ==================================================
function addRightClickColorPicker(button, callback) {
    button.addEventListener("mousedown", function (event) {
        if (event.button === 2) { // 右键
            event.preventDefault();
            var res = $.colorPicker(currentHex);
            if (res !== -1) {
                currentHex = res;
                // 保存到 AE 设置（永久记忆）
                app.settings.saveSetting(
                    SETTINGS_SECTION,
                    SETTINGS_KEY,
                    String(currentHex)
                );
                var color = hexToAERgb(currentHex);
                currentSolidColor = color;
                callback(color);
            }
        }
    });
}

