var applyButton = buttonRow5.add("button", undefined, "模糊开关");
    applyButton.preferredSize = [60, 28];
applyButton.helpTip = "运动模糊按钮切换开关";


var GO = buttonRow5.add("button", [0, 0, 75, 28], "进进＆出出");
GO.helpTip = "[入模式]:\n单击——确保选定图层在预合成上方将其打入预合成\n[出模式]:\nShift+单击——将预合成内部选定图层打出预合成";
var addTimeRemapButton = buttonRow6.add("button", [0, 0, 75, 28], "时间重映射");
addTimeRemapButton.helpTip = "单击：应用时间重映射\n按Shift+单击：正倒放！";
var DeframeButton = buttonRow6.add("button", [0, 0, 35, 28], "拆帧");
DeframeButton.helpTip = "选定图层拆解单帧序列图层";

DeframeButton.onClick = function() {
Deframe();
}

function Deframe() { 
    // 确保有选中合成
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请先选择一个合成！");
        return;
    }
    // 确保选中图层
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请先选择一个图层！");
        return;
    }
    app.beginUndoGroup("按帧拆分图层");
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        // 获取图层的起始和结束时间
        var startTime = layer.inPoint;
        var endTime = layer.outPoint;
        // 图层持续时间
        var duration = endTime - startTime;
        // 当前合成帧率
        var fps = comp.frameRate;
        // 计算总帧数
        var totalFrames = Math.round(duration * fps);
        // 从最后一帧往前拆分，避免覆盖原图层
        for (var f = totalFrames - 1; f >= 0; f--) {
            var frameTime = startTime + f / fps;
            // 复制图层
            var newLayer = layer.duplicate();
            // 设置每个图层只显示1帧
            newLayer.inPoint = frameTime;
            newLayer.outPoint = frameTime + 1 / fps;
        }
        // 删除原始图层
        layer.remove();
    }
    app.endUndoGroup();
}

