var Swapbutton = buttonRow6.add("button", undefined, "调换");
    Swapbutton.preferredSize = [40, 28];
Swapbutton.helpTip = "调换层级";
Swapbutton.onClick = function() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    app.beginUndoGroup("反转选中图层顺序");

    // 记录当前选中的图层
    var selectedLayers = [];
    for (var i = 1; i <= comp.selectedLayers.length; i++) {
        selectedLayers.push(comp.selectedLayers[i-1]);
    }

    // 执行你的函数
    reverseSelectedLayersOrderVisibleDown();

    // 恢复选中状态
    for (var i = 1; i <= comp.layers.length; i++) {
        comp.layers[i].selected = false; // 先取消所有选中
    }
    for (var j = 0; j < selectedLayers.length; j++) {
        selectedLayers[j].selected = true;
    }

    app.endUndoGroup();
}

function reverseSelectedLayersOrderVisibleDown() {
    Swap();
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length > 0) {
            // 复制选中图层数组，避免修改过程中影响原数组
            var layersToProcess = selectedLayers.slice();
            while (layersToProcess.length > 0) {
                // 取消第一个选中图层
                layersToProcess[0].selected = false;
                // 获取剩下的选中图层
                var remainingLayers = [];
                for (var i = 0; i < layersToProcess.length; i++) {
                    if (layersToProcess[i].selected) {
                        remainingLayers.push(layersToProcess[i]);
                    }
                }
                if (remainingLayers.length > 0) {
                    // 按索引从大到小排序，避免向下移动时索引冲突
                    remainingLayers.sort(function(a, b) {
                        return b.index - a.index;
                    });
                    // 向下移动每个剩余选中图层
                    for (var j = 0; j < remainingLayers.length; j++) {
                        var layer = remainingLayers[j];
                        var currentIndex = layer.index;

                        if (currentIndex < comp.numLayers) {
                            var nextLayer = comp.layer(currentIndex + 1);
                            layer.moveAfter(nextLayer);
                        }
                    }
                }
                layersToProcess = remainingLayers;
            }
        }
    }
}

function Swap(){
// 获取当前合成
var comp = app.project.activeItem;
if (comp && comp instanceof CompItem) {
    // 记录原选定图层
    var selectedLayers = comp.selectedLayers.slice();
    // 取消原有选择
    for (var j = 0; j < comp.numLayers; j++) {
        comp.layer(j + 1).selected = false;
    }
    // 按照 index 从大到小排序（从底部图层开始）
    selectedLayers.sort(function (a, b) {
        return b.index - a.index;
    });
    // 重新选择原选定图层（从下到上）
    for (var i = 0; i < selectedLayers.length; i++) {
        selectedLayers[i].selected = true;
    }
}
}
