// 函数定义：将图层按参考图层排序
function sortLayers() {
    var comp = app.project.activeItem;
    if (comp == undefined || comp == null || !(comp instanceof CompItem)) {
        alert("Error: You must be in an active comp!");
        return;
    }
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length < 2) {
        alert("Error: You must select at least 2 layers!");
        return;
    }
    // 最后选中的图层作为参考图层
    var referenceLayer = selectedLayers[selectedLayers.length - 1];
    var referenceInPoint = referenceLayer.inPoint; // 获取参考图层的入点位置
    // 其他所有选中的图层都作为要移动的目标图层
    var targetLayers = selectedLayers.slice(0, selectedLayers.length - 1);
    // 确保目标图层和参考图层不同
    for (var i = 0; i < targetLayers.length; i++) {
        var targetLayer = targetLayers[i];
        if (targetLayer.index == referenceLayer.index) {
            alert("Error: The selected layers must be different from the reference layer!");
            return;
        }
    }
    // 找到目标图层中最靠前的图层
    var earliestInPoint = Number.MAX_VALUE;
    var earliestLayer = null;
    for (var i = 0; i < targetLayers.length; i++) {
        var targetLayer = targetLayers[i];
        if (targetLayer.inPoint < earliestInPoint) {
            earliestInPoint = targetLayer.inPoint;
            earliestLayer = targetLayer;
        }
    }
    // 计算最靠前图层与参考图层之间的偏移量
    var offset = referenceInPoint - earliestInPoint;
    // 将目标图层按偏移量进行移动
    for (var i = 0; i < targetLayers.length; i++) {
        var targetLayer = targetLayers[i];
        targetLayer.startTime += offset;  // 偏移图层的入点
    }
    // 将目标图层反向排序，以便从底层开始移动
    for (var i = targetLayers.length - 1; i >= 0; i--) {
        var targetLayer = targetLayers[i];
        targetLayer.moveBefore(referenceLayer);
    }
    // 选中状态
    for (var i = 0; i < selectedLayers.length; i++) {
        if (selectedLayers[i] !== referenceLayer) {
            selectedLayers[i].selected = true;  // 目标图层选中
        } else {
            selectedLayers[i].selected = false; // 参考图层选中
        }
    }
}

