motiontilebutton.onClick = function () {
    app.beginUndoGroup("撤销组");
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        app.endUndoGroup();
        return;
    }
    // 记录当前选中的图层
    var selectedLayers = [];
    for (var i = 0; i < comp.selectedLayers.length; i++) {
        selectedLayers.push(comp.selectedLayers[i]);
    }
    // 执行原逻辑
    if (ScriptUI.environment.keyboardState.shiftKey) {
        sublayer();
        motiontilebutton_B();
    } else {
        sublayer();
        motiontilebutton_A();
    }
    // 先取消所有图层选中状态
    for (var i = 1; i <= comp.numLayers; i++) {
        comp.layer(i).selected = false;
    }
    // 再恢复原本选中状态
    for (var j = 0; j < selectedLayers.length; j++) {
        try {
            selectedLayers[j].selected = true;
        } catch (e) {}
    }
    app.endUndoGroup();
};

function motiontilebutton_A() {
    var value = getMotionTileValue();
    addRepeTileEffect(value);
}

function motiontilebutton_B() {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        alert("请选中当前合成，宝宝！");
        return;
    }

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请先选择一个要添加拼贴效果的图层，宝宝！");
        return;
    }

    var value = getMotionTileValue();
    addDynamicTileEffect(selectedLayers, value);
}

// 获取最终使用的 motiontile 数值（已移除+50逻辑）
function getMotionTileValue() {
    return parseInt(motiontileDropdown.selection.text);
}

// 添加 CC RepeTile 效果
function addRepeTileEffect(value) {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        alert("请选中当前合成，宝宝！");
        return;
    }

    var layers = comp.selectedLayers;
    if (layers.length === 0) {
        alert("请先选择一个要添加拼贴效果的图层，宝宝！");
        return;
    }

    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        if (!layer.property("Effects")) continue;

        var effect = layer.property("Effects").addProperty("CC RepeTile");
        if (effect) {
            var tileValue = (value / 50) - 1;
            var baseTile = 480 * tileValue;

            effect.property(1).setValue(baseTile); // TileRight
            effect.property(2).setValue(baseTile); // TileLeft
            effect.property(3).setValue(baseTile * 0.5625); // TileTop
            effect.property(4).setValue(baseTile * 0.5625); // TileBottom
            effect.property(5).setValue(4); // Output Width 设置为展开或镜像
        }
    }
}

// 添加“动态拼贴”伪效果（Pseudo Effect）
function addDynamicTileEffect(selectedLayers, value) {
    if (isNaN(value) || value < 100 || value > 500) {
        alert("您选择的数值无效！请选择范围为 100 到 500 的有效选项。");
        return;
    }

    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        var effect = layer.property("ADBE Effect Parade").addProperty("ADBE Tile");
        if (effect) {
            effect.property("ADBE Tile-0004").setValue(value);//输出宽度
            effect.property("ADBE Tile-0005").setValue(value);//输出高度
            effect.property("ADBE Tile-0006").setValue(1);//镜像边缘
        }
    }
}
