var JAWSButton = buttonRow8.add("button", undefined, "JAWS");
JAWSButton.preferredSize = [40, 28];
JAWSButton.helpTip = "单击:普通\nShift+单击:JAWS 动画[中文版]\nCtrl+单击:JAWS 动画[英文版]";
JAWSButton.onClick = function() { 
    var keys = ScriptUI.environment.keyboardState;

    if (keys.ctrlKey) {
        JAWSrunC(); // 按下 Ctrl 时执行
    } else if (keys.shiftKey) {
        JAWSrunB(); // 按下 Shift 时执行
    } else {
        JAWSrunA(); // 默认执行
    }
};

function JAWSrunA() {
            app.beginUndoGroup("jaws");
            var comp = app.project.activeItem;  // 获取当前合成
            var selectedLayers = comp.selectedLayers; // 获取选中的图层
            // 初始化 layerStart 和 layerEnd
            var layerStart = Infinity;
            var layerEnd = -Infinity;
            // 计算选定图层的时间范围
            if (selectedLayers.length > 0) {
                for (var i = 0; i < selectedLayers.length; i++) {
                    layerStart = Math.min(layerStart, selectedLayers[i].inPoint);
                    layerEnd = Math.max(layerEnd, selectedLayers[i].outPoint);
                }
            } else {
                // 如果没有选择图层，使用合成的工作区时间范围
                layerStart = comp.workAreaStart;
                layerEnd = comp.workAreaStart + comp.workAreaDuration;
            }
            // 创建黑色固态图层，持续时间为 layerEnd - layerStart
            var solid = comp.layers.addSolid([0, 0, 0], "Solid", comp.width, comp.height, 1, layerEnd - layerStart);
            // 设置固态图层的入点和出点
            solid.inPoint = layerStart;
            solid.outPoint = layerEnd;
            // 添加 CC Jaws 效果
            var ccJawsEffect = solid.property("Effects").addProperty("CC Jaws");
            var completionIndex = 1;  // Completion 属性的编号通常是 1
            var heightIndex = 4;      // Height 属性的编号通常是 4
            ccJawsEffect.property(completionIndex).setValue(0.8);  // 设置完成度
            ccJawsEffect.property(heightIndex).setValue(0);        // 设置高度
            solid.position.setValue([comp.width / 2, comp.height / 2]);  // 居中放置固态图层
            // 将固态图层移到最上面
            if (selectedLayers.length > 0) {
                var topLayer = selectedLayers[0];
                for (var i = 1; i < selectedLayers.length; i++) {
                    if (selectedLayers[i].index < topLayer.index) {
                        topLayer = selectedLayers[i];
                    }
                }
                solid.moveBefore(topLayer);
            }
            app.endUndoGroup();
        }
    
function JAWSrunB() {
    app.beginUndoGroup("Add Black Bars");
    JawsADD();
    huakuaikey();
    app.endUndoGroup();
}

function JawsADD() {
    var comp = app.project.activeItem;
    var frameRate = comp.frameRate;  // 获取合成的帧率
    var timeIndicator = comp.time; // 当前时间指示器位置
    var selectedLayers = comp.selectedLayers;
    var layerStart = Infinity;
    var layerEnd = -Infinity;

    if (selectedLayers.length > 0) {
        for (var i = 0; i < selectedLayers.length; i++) {
            layerStart = Math.min(layerStart, selectedLayers[i].inPoint);
            layerEnd = Math.max(layerEnd, selectedLayers[i].outPoint);
        }
    } else {
        layerStart = comp.workAreaStart;
        layerEnd = comp.workAreaStart + comp.workAreaDuration;
    }

    // 创建固态图层
    var solid = comp.layers.addSolid([1, 1, 1], "Solid", comp.width, comp.height, 1, layerEnd - layerStart);
    
    // 设置固态图层的入点与时间指示器对齐
    solid.inPoint = timeIndicator;
    solid.outPoint = timeIndicator + 15/frameRate; // 15帧长度

    // 设置不透明度并添加关键帧
    var opacityProperty = solid.property("Transform").property("Opacity");
    opacityProperty.setValueAtTime(timeIndicator + comp.frameDuration * 5, 100);  // 第5帧不透明度为100
    opacityProperty.setValueAtTime(timeIndicator + comp.frameDuration * 15, 0);   // 第15帧不透明度为0

    // 添加滑块控制器效果
    var sliderEffect = solid.property("Effects").addProperty("ADBE Slider Control");
    sliderEffect.name = "滑块控制";
    var sliderProperty = sliderEffect.property("Slider");

    // 将表达式应用于固态图层的缩放属性
    var scaleProperty = solid.property("Transform").property("Scale");
    scaleProperty.expression = 'temp = effect("滑块控制")("滑块");\n[temp, 100]';

    // 添加 CC Jaws 效果
    var ccJawsEffect = solid.property("Effects").addProperty("CC Jaws");
    var completionIndex = 1;
    var heightIndex = 4;
    ccJawsEffect.property(completionIndex).setValue(0.99);
    ccJawsEffect.property(heightIndex).setValue(0);

    solid.position.setValue([comp.width / 2, comp.height / 2]);

    // 添加光学补偿效果
    var opticalCompensationEffect = solid.property("Effects").addProperty("ADBE Optics Compensation");
    opticalCompensationEffect.property(1).setValue(15);  // 设置视场角 (Field of View)
    opticalCompensationEffect.property(2).setValue(1);   //反转镜头失真 (Reverse Lens Distortion)

    // 放在选中图层之前
    if (selectedLayers.length > 0) {
        var topLayer = selectedLayers[0];
        for (var i = 1; i < selectedLayers.length; i++) {
            if (selectedLayers[i].index < topLayer.index) {
                topLayer = selectedLayers[i];
            }
        }
        solid.moveBefore(topLayer);
    }
}

function huakuaikey() {
    var comp = app.project.activeItem;
    if (comp && comp.selectedLayers.length > 0) {
        var layer = comp.selectedLayers[0]; // 获取第一个选中的图层
        // 查找名为“滑块控制”的效果
        var effect = null;
        for (var i = 1; i <= layer.Effects.numProperties; i++) {
            var currentEffect = layer.Effects.property(i);
            if (currentEffect.name === "滑块控制") {
                effect = currentEffect;
                break;
            }
        }
        // 如果找到了效果，打关键帧
        if (effect) {
            var sliderProperty = effect.property("ADBE Slider Control-0001");

            // 获取当前时间指示器的位置
            var currentTime = comp.time;

            // 确保属性是可以设置关键帧的
            if (sliderProperty.isTimeVarying === false) {
                // 在当前时间指示器位置设置第一个关键帧，值为0
                sliderProperty.setValueAtTime(currentTime, 0);
                // 在当前时间后10帧设置第二个关键帧，值为150
                sliderProperty.setValueAtTime(currentTime + 10 * comp.frameDuration, 150);
            }

            // 🔽 关键：选中不透明度和滑块属性
            layer.property("Transform").property("Opacity").selected = true;
            sliderProperty.selected = true;
            app.executeCommand(2509);
        }
    } else {
        alert("请选择一个图层！");
    }
}



        
