// 分段模式：每个图层一个对应调整层
function AdjustmentBOJ() {
    if (app.project.activeItem && app.project.activeItem instanceof CompItem) {
        var comp = app.project.activeItem;
        var selectedLayers = comp.selectedLayers;

        if (selectedLayers.length === 0) {
            var adjustmentLayer = comp.layers.addSolid([1, 1, 1], "调整图层", comp.width, comp.height, 1);
            adjustmentLayer.adjustmentLayer = true;
            adjustmentLayer.label = 5;
        } else {
            var lastAdjustmentLayer = null;
            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                var adjustmentLayer = comp.layers.addSolid([1, 1, 1], "调整图层", comp.width, comp.height, 1);
                adjustmentLayer.adjustmentLayer = true;
                adjustmentLayer.inPoint = layer.inPoint;
                adjustmentLayer.outPoint = layer.outPoint;
                adjustmentLayer.label = 5;

                var parentLayer = layer;
                while (parentLayer.parent !== null) {
                    parentLayer = parentLayer.parent;
                }
                adjustmentLayer.moveBefore(parentLayer);
                lastAdjustmentLayer = adjustmentLayer;
            }

            for (var k = 0; k < selectedLayers.length; k++) {
                selectedLayers[k].selected = false;
            }
            if (lastAdjustmentLayer) {
                lastAdjustmentLayer.selected = true;
            }
        }
    } else {
        alert("请先选中一个合成");
    }
}

// 统一模式：一个调整层包住所有选中层的时间段
function WHLAdjustmentBOJ() {
    if (app.project.activeItem && app.project.activeItem instanceof CompItem) {
        var comp = app.project.activeItem;
        var selectedLayers = comp.selectedLayers;

        if (selectedLayers.length === 0) {
            var solidLayer = comp.layers.addSolid([1, 1, 1], "调整图层", comp.width, comp.height, 1);
            solidLayer.adjustmentLayer = true;
            solidLayer.label = 5;
        } else {
            var minInPoint = Number.MAX_VALUE;
            var maxOutPoint = Number.MIN_VALUE;
            var topmostLayer = null;
            var topmostLayerIndex = Number.MAX_VALUE;

            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                minInPoint = Math.min(minInPoint, layer.inPoint);
                maxOutPoint = Math.max(maxOutPoint, layer.outPoint);

                var current = layer;
                while (current) {
                    if (current.index < topmostLayerIndex) {
                        topmostLayer = current;
                        topmostLayerIndex = current.index;
                    }
                    current = current.parent;
                }
            }

            var solidLayer = comp.layers.addSolid([1, 1, 1], "调整图层", comp.width, comp.height, 1);
            solidLayer.adjustmentLayer = true;
            solidLayer.inPoint = minInPoint;
            solidLayer.outPoint = maxOutPoint;
            solidLayer.label = 5;

            if (topmostLayer) {
                solidLayer.moveBefore(topmostLayer);
            }

            for (var k = 0; k < selectedLayers.length; k++) {
                selectedLayers[k].selected = false;
            }
            solidLayer.selected = true;
        }
    } else {
        alert("请先选中一个合成");
    }
}

// Shift 模式：插入单帧调整图层
function createOneFrameAdjustmentLayer() {
    // 获取当前合成
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先选中一个合成");
        return;
    }

    // 获取选中的图层
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请选中一个图层");
        return;
    }

    var selectedLayer = selectedLayers[0];

    // 当前合成帧率
    var fps = comp.frameRate; // 帧率，例如 24 fps
    var frameDuration = 1 / fps; // 单帧的持续时间（秒）

    // 添加纯色图层作为单帧调整层
    var solidLayer = comp.layers.addSolid([1, 1, 1], "单帧调整层", comp.width, comp.height, 1, comp.pixelAspect);
    solidLayer.adjustmentLayer = true; // 设置为调整图层
    solidLayer.inPoint = comp.time; // 入点为当前时间
    solidLayer.outPoint = comp.time + frameDuration; // 出点为下一帧
    solidLayer.label = 5; // 设置图层标签颜色（可选）

    // 将新图层移动到选中图层上方
    solidLayer.moveBefore(selectedLayer);

    // 将时间线前进一帧
    comp.time += frameDuration;
}


