        function WHLparentTextOBJ() {
    if (app.project.activeItem && app.project.activeItem instanceof CompItem) {
        var comp = app.project.activeItem;
        var selectedLayers = comp.selectedLayers;

        function centerTextLayer(textLayer) {
            var textRect = textLayer.sourceRectAtTime(0, false);
            var anchorX = textRect.left + textRect.width / 2;
            var anchorY = textRect.top + textRect.height / 2;
            textLayer.transform.anchorPoint.setValue([anchorX, anchorY]);

            var textX = comp.width / 2;
            var textY = comp.height / 2;
            textLayer.transform.position.setValue([textX, textY]);
        }

        if (selectedLayers.length === 0) {
            var textLayer = comp.layers.addText("Create text");
            textLayer.name = "Text";
            textLayer.inPoint = 0;
            textLayer.outPoint = comp.duration;
            centerTextLayer(textLayer); // 居中
        } else {
            var minInPoint = Number.MAX_VALUE;
            var maxOutPoint = Number.MIN_VALUE;
            var topmostLayer = null;
            var topmostLayerIndex = Number.MAX_VALUE;

            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                minInPoint = Math.min(minInPoint, layer.inPoint);
                maxOutPoint = Math.max(maxOutPoint, layer.outPoint);

                if (layer.index < topmostLayerIndex) {
                    topmostLayer = layer;
                    topmostLayerIndex = layer.index;
                }
            }

            var textLayer = comp.layers.addText("Create text");
            textLayer.name = "Text";
            textLayer.inPoint = minInPoint;
            textLayer.outPoint = maxOutPoint;
            centerTextLayer(textLayer); // 居中

            if (topmostLayer) {
                textLayer.moveBefore(topmostLayer);
            }

            for (var k = 0; k < selectedLayers.length; k++) {
                selectedLayers[k].selected = false;
            }

            if (textLayer) {
                textLayer.selected = true;
            }
        }
    } else {
        alert("请先选择一个合成。");
    }
}

 function TextOBJ() {
    if (app.project.activeItem && app.project.activeItem instanceof CompItem) {
        var comp = app.project.activeItem;
        var selectedLayers = comp.selectedLayers;

        // 创建居中函数
        function centerTextLayer(textLayer) {
            var textRect = textLayer.sourceRectAtTime(0, false);
            var anchorX = textRect.left + textRect.width / 2;
            var anchorY = textRect.top + textRect.height / 2;
            textLayer.transform.anchorPoint.setValue([anchorX, anchorY]);

            var textX = comp.width / 2;
            var textY = comp.height / 2;
            textLayer.transform.position.setValue([textX, textY]);
        }

        if (selectedLayers.length === 0) {
            var textLayer = comp.layers.addText("Create text");
            textLayer.inPoint = 0;
            textLayer.outPoint = comp.duration;

            // 居中文本
            centerTextLayer(textLayer);

        } else {
            var lastTextLayer = null;
            for (var i = 0; i < selectedLayers.length; i += 1) {
                var layer = selectedLayers[i];
                var totalCount = 1;

                function countAllLayers(layer) {
                    var currentLayer = layer;
                    while (currentLayer.parent !== null) {
                        totalCount++;
                        currentLayer = currentLayer.parent;
                    }

                    function countChildren(layer) {
                        var childrenCount = 0;
                        for (var j = 1; j <= comp.layers.length; j += 1) {
                            var l = comp.layers[j];
                            if (l.parent === layer) {
                                childrenCount++;
                                childrenCount += countChildren(l);
                            }
                        }
                        return childrenCount;
                    }
                    totalCount += countChildren(layer);
                }
                countAllLayers(layer);
                var textLayer = comp.layers.addText("Create text");
                textLayer.inPoint = layer.inPoint;
                textLayer.outPoint = layer.outPoint;

                // 居中文本
                centerTextLayer(textLayer);

                function findDeepestChild(layer) {
                    var deepestLayer = layer;
                    for (var j = 1; j <= comp.layers.length; j += 1) {
                        var l = comp.layers[j];
                        if (l.parent === layer) {
                            var childLayer = findDeepestChild(l);
                            if (childLayer.index > deepestLayer.index) {
                                deepestLayer = childLayer;
                            }
                        }
                    }
                    return deepestLayer;
                }
                var deepestChildLayer = findDeepestChild(layer);
                textLayer.moveBefore(deepestChildLayer);
                lastTextLayer = textLayer;
            }

            // 重新选择之前选中的图层
            for (var k = 0; k < selectedLayers.length; k += 1) {
                selectedLayers[k].selected = false;
            }

            if (lastTextLayer) {
                lastTextLayer.selected = true;
            }
        }
    } else {
        alert("Please select a composition first.");
    }
}

//时间重映射
addTimeRemapButton.onClick = function () {
    app.beginUndoGroup("撤销组");
    var keyState = ScriptUI.environment.keyboardState;
    if (keyState.shiftKey) {
        runTimeB();
    } else {
        TimerunA();
        Keybtn();
    }
    app.endUndoGroup();
};

function runTimeB() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    var layers = comp.selectedLayers;
    if (layers.length === 0) return;
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        // 开启时间重映射
        if (!layer.timeRemapEnabled) {
            layer.timeRemapEnabled = true;
        }
        var prop = layer.property("ADBE Time Remapping");
        if (!prop || prop.numKeys < 2) continue;
        var firstIndex = 1;
        var lastIndex = prop.numKeys;
        var firstValue = prop.keyValue(firstIndex);
        var lastValue = prop.keyValue(lastIndex);
        var midTime = (layer.inPoint + layer.outPoint) / 2;
        var outTime = layer.outPoint;
        // =========================
        // ❗关键：先删除最后关键帧
        // =========================
        prop.removeKey(lastIndex);
        // =========================
        // ✔ 在中间创建“原最后关键帧”
        // =========================
        var midIndex = prop.addKey(midTime);
        prop.setValueAtKey(midIndex, lastValue);
        // =========================
        // ❗删除出点自动生成的关键帧（很关键）
        // =========================
        if (prop.numKeys >= 2) {
            var lastKeyTime = prop.keyTime(prop.numKeys);
            if (Math.abs(lastKeyTime - outTime) < 0.0001) {
                prop.removeKey(prop.numKeys);
            }
        }
        // =========================
        // ✔ 在出点复制第一个关键帧
        // =========================
        var outIndex = prop.addKey(outTime);
        prop.setValueAtKey(outIndex, firstValue);
    }
};

