// 创建形状
xingzhuangButton.onClick = function() {
    var selectedShape = shapeDropdown.selection.index;  // 获取选择的形状类型
    var fillOption = false, strokeOption = false;

    // 根据单选按钮的选择设置填充和描边的选项
    if (fillRadio.value) {
        fillOption = true;  // 选中填充
    } else if (strokeRadio.value) {
        strokeOption = true;  // 选中描边
    } else if (bothRadio.value) {
        fillOption = true;  // 填充
        strokeOption = true;  // 描边
    }

    // 获取合成
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先选择一个合成!");
        return;
    }

    // 获取选中的图层的最早入点和最晚出点
    var selectedLayers = comp.selectedLayers;
    var layerStart = Infinity;
    var layerEnd = -Infinity;

    if (selectedLayers.length > 0) {
        // 遍历选中的图层，计算最早的入点和最晚的出点
        for (var i = 0; i < selectedLayers.length; i++) {
            layerStart = Math.min(layerStart, selectedLayers[i].inPoint);
            layerEnd = Math.max(layerEnd, selectedLayers[i].outPoint);
        }
    } else {
        // 如果没有选中图层，使用工作区的开始和结束时间
        layerStart = comp.workAreaStart;
        layerEnd = comp.workAreaStart + comp.workAreaDuration;
    }

    // 创建一个新的形状图层
    app.beginUndoGroup("Create Shape Layer");

    var shapeLayer = comp.layers.addShape();  // 创建形状图层

// 创建选择的形状
var shapeGroup;
switch (selectedShape) {
    case 0:  // 矩形
        shapeGroup = shapeLayer.content.addProperty("ADBE Vector Shape - Rect");
        var rectSize = shapeGroup.property("Size");
        rectSize.setValue([500, 250]);  // 默认大小
        break;
    case 1:  // 椭圆
        shapeGroup = shapeLayer.content.addProperty("ADBE Vector Shape - Ellipse");
        var ellipseSize = shapeGroup.property("Size");
        ellipseSize.setValue([500, 500]);  // 默认大小
        break;
    case 2:  // 多边星形
        shapeGroup = shapeLayer.content.addProperty("ADBE Vector Shape - Star");
        var starPoints = shapeGroup.property("Points");
        var starRadius = shapeGroup.property("Outer Radius");
        var starInnerRadius = shapeGroup.property("Inner Radius"); // 内径

        starPoints.setValue(5);  // 5点星形
        starRadius.setValue(200);  // 外半径
        starInnerRadius.setValue(100);  // 内半径，调整这个值来控制星形的内径
        break;
}

    // 如果选择了填充
    if (fillOption) {
        var fill = shapeLayer.content.addProperty("ADBE Vector Graphic - Fill");
        var fillColor = fill.property("Color");
        fillColor.setValue([1, 1, 1]);  // 默认填充为白色
    }

    // 如果选择了描边
    if (strokeOption) {
        var stroke = shapeLayer.content.addProperty("ADBE Vector Graphic - Stroke");
        var strokeColor = stroke.property("Color");
        strokeColor.setValue([0, 0, 0]);  // 默认描边为黑色
        var strokeWidth = stroke.property("Stroke Width");
        strokeWidth.setValue(10);  // 设置默认描边宽度
    }

    // 设置新图层的入点和出点
    shapeLayer.inPoint = layerStart;  // 新图层的入点为最早的入点
    shapeLayer.outPoint = layerEnd;  // 新图层的出点为最晚的出点

    // 获取最高选定图层并将形状图层移动到其上方
    if (selectedLayers.length > 0) {
        var topLayer = selectedLayers[0];
        for (var i = 1; i < selectedLayers.length; i++) {
            if (selectedLayers[i].index < topLayer.index) {
                topLayer = selectedLayers[i];
            }
        }
        shapeLayer.moveBefore(topLayer); // 将形状图层移动到最高选定图层上方
    }

    app.endUndoGroup();
};

