function markA() {
    var comp = app.project.activeItem;
    if (comp == null || !(comp instanceof CompItem)) {
        alert("请选择一个合成。");
        return;
    }

    var selectedLayers = comp.selectedLayers;
    var newMarker = new MarkerValue(""); // 可以改成让用户输入

    if (selectedLayers.length === 0) {
        comp.markerProperty.setValueAtTime(comp.time, newMarker);
        $.writeln("在合成 " + comp.name + " 的当前时间线添加了标记");
    } else {
        for (var i = 0; i < selectedLayers.length; i++) {
            selectedLayers[i].property("Marker").setValueAtTime(comp.time, newMarker);
            $.writeln("为图层 " + selectedLayers[i].name + " 添加了标记");
        }
    }
    markerAdded = true; // 标记已添加
};


// 删除标记
function markB() {
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        // 如果有选定图层
        if (comp.selectedLayers.length > 0) {
            for (var i = 0; i < comp.selectedLayers.length; i++) {
                var layer = comp.selectedLayers[i];

                if (layer.marker) {
                    if (layer.marker.numKeys > 0) {
                        for (var k = layer.marker.numKeys; k >= 1; k--) {
                            layer.marker.removeKey(k);
                        }
                        $.writeln("已删除图层 " + layer.name + " 上的所有标记");
                    } else {
                        $.writeln("图层 " + layer.name + " 没有标记");
                    }
                }
            }
        } else {
            // 如果没有选定图层，删除当前合成的所有标记
            if (comp.markerProperty) {
                for (var i = comp.markerProperty.numKeys; i > 0; i--) {
                    comp.markerProperty.removeKey(i);
                }
                $.writeln("已删除合成 " + comp.name + " 上的所有标记");
            } else {
                alert("当前合成没有标记属性 (markerProperty)。");
            }
        }
    } else {
        alert("请确保当前有一个合成处于活动状态，并且选择了图层。");
    }
}

