// ================= 保留形状图层中与图层名称匹配的连续内容 =================
function keepShapesMatchingLayerName() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先选择一个合成！");
    } else {
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length === 0) {
            alert("请先选择一个图层！");
        } else {

            var startIndex = 1; // 累计起始索引，从1开始
            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                if (layer instanceof ShapeLayer) {
                    var nameLength = layer.name.length; // 当前图层名称长度
                    var contents = layer.property("ADBE Root Vectors Group");
                    var totalGroups = contents.numProperties;

                    var endIndex = startIndex + nameLength - 1; // 当前图层要保留的结束索引

                    // 删除不在保留范围内的内容
                    for (var j = totalGroups; j >= 1; j--) {
                        if (j < startIndex || j > endIndex) {
                            contents.property(j).remove();
                        }
                    }

                    // 更新起始索引给下一个图层
                    startIndex = endIndex + 1;
                }
            }
        }
    }
}

