zibtnConvert.addEventListener("mousedown", function (event) {
    // 检查是否按下了shift键
    if (event.shiftKey) {
    app.beginUndoGroup("文本转形状"); // 开始撤销组
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem) || comp.selectedLayers.length === 0) {
        alert("请先选择一个文本图层！");
        return;
    }

    var layer = comp.selectedLayers[0]; // 获取选中的图层
    if (!(layer instanceof TextLayer)) {
        alert("请选择一个文本图层！");
        return;
    }

    var oldLayerIndex = layer.index; // 记录文本图层的索引
    var textPosition = layer.position.value; // 记录文本图层的位置
    var textAnchor = layer.anchorPoint.value; // 记录文本图层的锚点位置
    var textScale = layer.transform.scale.value; // 记录文本图层的缩放

    app.executeCommand(3781); // 执行创建形状图层命令

    var newLayer = comp.layer(oldLayerIndex);
    if (newLayer instanceof ShapeLayer) {
        separateCharacters(newLayer, textPosition, textAnchor, textScale); // 处理形状图层
    } else {
        alert("转换失败，请手动检查图层");
    }

    app.endUndoGroup(); // 结束撤销组
};

// **处理形状图层**
function separateCharacters(shapeLayer, textPosition, textAnchor, textScale) {
    var rootGroup = shapeLayer.property("ADBE Root Vectors Group");
    if (!rootGroup) {
        alert("未找到形状组");
        return;
    }

    var shapeCount = rootGroup.numProperties;
    if (shapeCount <= 1) {
        alert("没有可分离的形状！");
        return;
    }

    for (var i = shapeCount; i >= 1; i--) {
        var shapeName = rootGroup.property(i).name;

        if (i === 1) {
            // 原始图层仅保留第一个字符
            removeOtherShapes(rootGroup, 1);
            shapeLayer.name = shapeName;
            adjustAnchorAndPosition(shapeLayer, textPosition, textAnchor, textScale);
        } else {
            // 复制图层，并保留对应字符
            var duplicatedLayer = shapeLayer.duplicate();
            duplicatedLayer.name = shapeName;

            var dupRootGroup = duplicatedLayer.property("ADBE Root Vectors Group");
            removeOtherShapes(dupRootGroup, i);

            adjustAnchorAndPosition(duplicatedLayer, textPosition, textAnchor, textScale);
        }
    }
}

// **删除非目标字符的形状**
function removeOtherShapes(rootGroup, keepIndex) {
    for (var j = rootGroup.numProperties; j >= 1; j--) {
        if (j !== keepIndex) {
            rootGroup.property(j).remove();
        }
    }
}

// **调整锚点和位置**
function adjustAnchorAndPosition(layer, textPosition, textAnchor, textScale) {
    var rect = layer.sourceRectAtTime(0, false);
    var anchorX = rect.left + rect.width / 2;
    var anchorY = rect.top + rect.height / 2;

    // 应用原文本缩放
    var scaleX = textScale[0] / 100;
    var scaleY = textScale[1] / 100;

    var offsetX = (anchorX - textAnchor[0]) * scaleX;
    var offsetY = (anchorY - textAnchor[1]) * scaleY;

    layer.transform.anchorPoint.setValue([anchorX, anchorY]);
    layer.transform.position.setValue([textPosition[0] + offsetX, textPosition[1] + offsetY]);
    }
});

//按词拆
cibtnConvert.onClick = function() {
    app.beginUndoGroup("撤销组");
    if (ScriptUI.environment.keyboardState.shiftKey) {
        splitTextAndDuplicateShapeOrderedB();
    } else {
    splitTextAndDuplicateShapeOrdered();
    selectLayerBelow();//选中下方图层
    selectLayerBelowA();//由上都下重新选中
    selectLayerBelowB();//获取源文字图层的字体、缩放、旋转、颜色
    matchTextToShapePosition();// 将文本图层位置设置为形状图层位置
    deleteSelectedShapeLayers();//删除形状图层
    }
    app.endUndoGroup(); // 撤销组结束
};    

function splitTextAndDuplicateShapeOrderedB() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) return;

    var newShapes = []; // 存放新生成的图层

    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        if (!(layer instanceof TextLayer)) continue;
        var textValue = layer.property("Source Text").value.text;
        var words = textValue.split(/[\s\r\n]+/);
        // 创建形状图层作为模板
        app.executeCommand(3781); // 创建形状图层
        var templateShape = comp.selectedLayers[0]; 
        // 先隐藏原文本图层
        layer.enabled = false;
        // 遍历每个词，按顺序生成图层
        for (var j = 0; j < words.length; j++) {
            var word = words[j];
            var newShape = (j === 0) ? templateShape : templateShape.duplicate();
            newShape.name = word;
            newShape.position.setValue(templateShape.position.value);
            // 将图层移动到原文本图层的上方
            newShape.moveBefore(layer);
            newShapes.push(newShape);
        }
    }
    // 取消原本选中状态
    for (var i = 0; i < comp.selectedLayers.length; i++) {
        comp.selectedLayers[i].selected = false;
    }
    // 全选新生成图层
    for (var i = 0; i < newShapes.length; i++) {
        newShapes[i].selected = true;
    }
keepShapesMatchingLayerName();
app.executeCommand(10312);//居中
// 完成后取消选中所有图层
    for (var i = 1; i <= comp.numLayers; i++) {
        comp.layer(i).selected = false;
    }
}

function splitTextAndDuplicateShapeOrdered() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) return;

    var newShapes = []; // 存放新生成的图层

    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        if (!(layer instanceof TextLayer)) continue;

        var textValue = layer.property("Source Text").value.text;
        var words = textValue.split(/[\s\r\n]+/);

        // 创建形状图层作为模板
        app.executeCommand(3781); // 创建形状图层
        var templateShape = comp.selectedLayers[0];

        // 隐藏原文本图层
        layer.enabled = false;

        // 按顺序生成形状图层
        for (var j = 0; j < words.length; j++) {
            var word = words[j];
            var newShape = (j === 0) ? templateShape : templateShape.duplicate();

            newShape.name = word;
            newShape.position.setValue(templateShape.position.value);
            newShape.moveBefore(layer);

            newShapes.push(newShape);
        }
    }

    // 清空原选择
    for (var i = 0; i < comp.selectedLayers.length; i++) {
        comp.selectedLayers[i].selected = false;
    }

    // 选中新生成图层
    for (var i = 0; i < newShapes.length; i++) {
        newShapes[i].selected = true;
    }

    keepShapesMatchingLayerName();
    app.executeCommand(10312); // 居中
    createTextFromLayerName();
}


// ================= 保留形状图层中与图层名称匹配的连续内容 =================
function keepShapesMatchingLayerName() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) return;

    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        if (!(layer instanceof ShapeLayer)) continue;

        var layerName = layer.name;
        var contents = layer.property("Contents");
        if (!contents) continue;

        var keepIndices = [];
        var shapeNames = [];

        for (var j = 1; j <= contents.numProperties; j++) {
            shapeNames.push(contents.property(j).name);
        }

        var combined = shapeNames.join("");
        var startIndex = combined.indexOf(layerName);
        if (startIndex === -1) continue;

        var charCount = 0;
        var matchedLength = 0;

        for (var k = 0; k < shapeNames.length; k++) {
            charCount += shapeNames[k].length;

            if (charCount > startIndex && matchedLength < layerName.length) {
                keepIndices.push(k + 1);
                matchedLength += shapeNames[k].length;
            }
        }

        // 删除未匹配形状
        for (var j = contents.numProperties; j >= 1; j--) {
            if (!arrayContains(keepIndices, j)) {
                contents.property(j).remove();
            }
        }
    }
}


// ================= 根据图层名称创建文本图层 =================
function createTextFromLayerName() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) return;

    var layersToSelect = [];

    for (var i = selectedLayers.length - 1; i >= 0; i--) {
        var layer = selectedLayers[i];
        var name = layer.name;

        var textLayer = comp.layers.addText(name);
        app.executeCommand(10312);

        textLayer.position.setValue(layer.position.value);
        textLayer.inPoint = layer.inPoint;
        textLayer.outPoint = layer.outPoint;
        textLayer.name = name;
        textLayer.moveBefore(layer);

        layersToSelect.push(layer);
        layersToSelect.push(textLayer);
    }

    // 清空选择
    for (var i = 1; i <= comp.layers.length; i++) {
        comp.layers[i].selected = false;
    }

    // 重新选中
    for (var j = 0; j < layersToSelect.length; j++) {
        layersToSelect[j].selected = true;
    }
}


// ================= 工具函数：判断数组是否包含值 =================
function arrayContains(arr, value) {
    for (var i = 0; i < arr.length; i++) {
        if (arr[i] === value) return true;
    }
    return false;
}

function selectLayerBelow() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    var sel = comp.selectedLayers;
    if (sel.length === 0) return;
    var targetIndexMap = {};
    for (var i = 0; i < sel.length; i++) {
        var idx = sel[i].index + 1; // 下方 = index + 1
        if (idx <= comp.numLayers) {
            targetIndexMap[idx] = true;
        }
    }
    // 直接选中下方图层
    for (var k in targetIndexMap) {
        if (targetIndexMap.hasOwnProperty(k)) {
            comp.layer(parseInt(k, 10)).selected = true;
        }
    }
}

    function selectLayerBelowA() {
// 获取当前合成
var comp = app.project.activeItem;
if (comp && comp instanceof CompItem) {
    // 记录原选定图层
    var selectedLayers = comp.selectedLayers.slice();
    // 取消原有选择
    for (var j = 0; j < comp.numLayers; j++) {
        comp.layer(j + 1).selected = false;
    }
    // 按照 index 从小到大排序（从顶部图层开始）
    selectedLayers.sort(function (a, b) {
        return a.index - b.index;
    });
    // 重新选择原选定图层（从上到下）
    for (var i = 0; i < selectedLayers.length; i++) {
        selectedLayers[i].selected = true;
    }
  }
}

function selectLayerBelowB() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先选中一个合成！");
        return;
    }
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length < 2) {
        alert("请至少选中一个源文字图层和一个目标文字图层！");
        return;
    }
    // 最后一个选中的文字图层作为源
    var sourceLayer = selectedLayers[selectedLayers.length - 1];
    if (!sourceLayer.property("Source Text")) {
        alert("最后一个选中的图层不是文字图层！");
        return;
    }
    // 获取源文字图层的字体、缩放、旋转、颜色
    var sourceTextProp = sourceLayer.property("Source Text");
    var sourceValue = sourceTextProp.value;
    var sourceFont = sourceValue.font;
    var sourceColor = sourceValue.fillColor; // 文字颜色
    var sourceScale = sourceLayer.property("Transform").property("Scale").value;
    var sourceRotation = sourceLayer.property("Transform").property("Rotation").value;
    // 应用到其它文字图层
    for (var i = 0; i < selectedLayers.length; i++) {
        var targetLayer = selectedLayers[i];
        // 跳过源图层本身
        if (targetLayer === sourceLayer) continue;
        if (targetLayer.property("Source Text")) {
            // 复制字体和颜色
            var targetValue = targetLayer.property("Source Text").value;
            targetValue.font = sourceFont;
            targetValue.fillColor = sourceColor;
            targetLayer.property("Source Text").setValue(targetValue);
            // 复制缩放
            targetLayer.property("Transform").property("Scale").setValue(sourceScale);
            // 复制旋转
            targetLayer.property("Transform").property("Rotation").setValue(sourceRotation);
        }
    }
    // 源图层取消选中
    sourceLayer.selected = false;
    app.executeCommand(10312); // 锚点居中
}

function matchTextToShapePosition() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length < 2) return;
    // 遍历所有选中的图层
    for (var i = 0; i < selectedLayers.length; i++) {
        var layerA = selectedLayers[i];
        if (!(layerA instanceof ShapeLayer)) continue; // 只处理形状图层
        var shapeName = layerA.name;
        // 在选中图层中找到同名文本图层
        for (var j = 0; j < selectedLayers.length; j++) {
            var layerB = selectedLayers[j];
            if (!(layerB instanceof TextLayer)) continue; // 只处理文本图层
            if (layerB.name === shapeName) {
                // 将文本图层位置设置为形状图层位置
                layerB.property("Transform").property("Position").setValue(
                    layerA.property("Transform").property("Position").value
                );
            }
        }
    }
}

function deleteSelectedShapeLayers() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) return;
    for (var i = selectedLayers.length - 1; i >= 0; i--) {
        var layer = selectedLayers[i];
        if (layer instanceof ShapeLayer) {
            layer.remove();
        }
    }
    for (var j = 1; j <= comp.numLayers; j++) {
        comp.layer(j).selected = false;
    }
}



