function removeSpecificKeyframes(property, mode) {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var prop = layer[property];

        if (prop && prop.numKeys > 0) {
            if (mode === "start" && prop.numKeys >= 1) {
                prop.removeKey(1); // **删除第一个关键帧**
            } else if (mode === "end" && prop.numKeys >= 2) {
                prop.removeKey(2); // **删除第二个关键帧**
            }
        }
    }
}

// **生成关键帧**
function applyKeyframes(property) {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请选中一个合成");
        return;
    }

    var layers = comp.selectedLayers;
    if (layers.length === 0) {
        alert("请选择至少一个图层");
        return;
    }

    app.beginUndoGroup("更新关键帧");

    var spread = parseFloat(positionedittext.text) || 1000; // **位置偏移范围（输入框值）**
    var scaleVariation = parseFloat(scaleedittext.text) || 500; // **缩放变化范围（输入框值）**
    var rotationVariation = 360; // 旋转角度范围（默认）
    var mode = Dropdown1.selection.index === 0 ? "start" : "end"; // **只有“开始随机”和“结束随机”**

    removeSpecificKeyframes(property, mode); // **删除指定关键帧**

    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var prop = layer[property];

        if (prop && prop.canSetExpression !== undefined) {
            var startTime = comp.time;
            var endTime = startTime + 1; // 1秒后
            var startValue = prop.value;
            var endValue = startValue;

            if (property === "position") {
                var randomPos = [
                    startValue[0] + (Math.random() - 0.5) * spread,
                    startValue[1] + (Math.random() - 0.5) * spread
                ];

                if (mode === "start") {
                    startValue = randomPos;
                    endValue = prop.value;
                } else if (mode === "end") {
                    startValue = prop.value;
                    endValue = randomPos;
                }
            } else if (property === "scale") {
                var randomScale = startValue[0] + (Math.random() * scaleVariation);
                if (mode === "start") {
                    startValue = [randomScale, randomScale];
                } else if (mode === "end") {
                    endValue = [randomScale, randomScale];
                }
            } else if (property === "rotation") {
                var randomRotation = startValue + (Math.random() - 0.5) * rotationVariation;
                if (mode === "start") {
                    startValue = randomRotation;
                } else if (mode === "end") {
                    endValue = randomRotation;
                }
            }

            prop.setValueAtTime(startTime, startValue);
            prop.setValueAtTime(endTime, endValue);
        }
    }

    app.endUndoGroup();
}

