function ZHobj() {
    var comp = app.project.activeItem;
    // 检查是否选中合成
    if (comp == null) {
        alert("没有选中合成");
        app.endUndoGroup();
        return; // 如果没有选中合成则退出
    }

    var selectedLayers = comp.selectedLayers;

    // 如果有选中的图层，给每个图层添加 CC RepeTile 效果（如果该效果不存在）
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        if (!layer.property("Effects")) continue;  // 确保图层有效果属性

        var hasRepeTile = false;
        var effects = layer.property("Effects");

        // 检查图层的所有效果，看看是否已经有 CC RepeTile（中文名 CC 重复拼贴）效果
        for (var j = 1; j <= effects.numProperties; j++) {
            var effect = effects.property(j);
            if (effect.name === "CC RepeTile" || effect.name === "CC 重复拼贴") {
                hasRepeTile = true;  // 找到后标记为 true
                break;  // 不再检查其他效果
            }
        }

        // 如果没有 CC RepeTile 效果，则添加
        if (!hasRepeTile) {
            var effect = effects.addProperty("CC RepeTile");
            effect.property(1).setValue(1920); // TileRight
            effect.property(2).setValue(1920); // TileLeft
            effect.property(3).setValue(1080); // TileTop
            effect.property(4).setValue(1080); // TileBottom
            effect.property(5).setValue(4);    // Output Width 设置为 "展开或镜像"
        }
    }

    // 固定调整图层持续时间为30帧
    var duration = 30 / comp.frameRate;

    // 创建调整图层
    var solidLayer = comp.layers.addSolid([1, 1, 1], "抖动·调整图层", comp.width, comp.height, 1, duration);
    solidLayer.adjustmentLayer = true;
    solidLayer.inPoint = comp.time; // 设置为当前时间
    solidLayer.label = 5;

    // 根据复选框的状态开启或关闭运动模糊
    if (motionBlur.value) {
        comp.motionBlur = true; // 开启合成的动态模糊
        solidLayer.motionBlur = true; // 开启图层的动态模糊
    } else {
        solidLayer.motionBlur = false; // 关闭图层的动态模糊
    }
    // 添加滑块控制并命名
    var amplitudeControl = solidLayer.property("ADBE Effect Parade").addProperty("ADBE Slider Control");
    amplitudeControl.name = "振幅";
    amplitudeControl.property("ADBE Slider Control-0001").setValue(200);

    var frequencyControl = solidLayer.property("ADBE Effect Parade").addProperty("ADBE Slider Control");
    frequencyControl.name = "频率";
    frequencyControl.property("ADBE Slider Control-0001").setValue(5);

    var resistanceControl = solidLayer.property("ADBE Effect Parade").addProperty("ADBE Slider Control");
    resistanceControl.name = "阻力";
    resistanceControl.property("ADBE Slider Control-0001").setValue(10);
    var transformEffect = solidLayer.property("ADBE Effect Parade").addProperty("变换");
    // 设置位置表达式
    var positionProperty = transformEffect.property("位置");
    var selectedOption = dropdownMenu.selection.text; // 获取当前选择的菜单项

    // 根据选择设置位置表达式和标记
    if (selectedOption === "↕") {
        positionProperty.expression = 
            "amp = effect(\"振幅\")(\"滑块\");\n" +
            "freq = effect(\"频率\")(\"滑块\");\n" +
            "decay = effect(\"阻力\")(\"滑块\");\n" +
            "t = time - inPoint;\n" +
            "v = amp * Math.sin(freq * t * 2 * Math.PI) / Math.exp(decay * t);\n" +
            "value + [0, v];";
        solidLayer.property("ADBE Marker").setValueAtTime(solidLayer.inPoint, new MarkerValue(" ↕ 抖动"));
    } else if (selectedOption === "↔") {
        positionProperty.expression = 
            "amp = effect(\"振幅\")(\"滑块\");\n" +
            "freq = effect(\"频率\")(\"滑块\");\n" +
            "decay = effect(\"阻力\")(\"滑块\");\n" +
            "t = time - inPoint;\n" +
            "v = amp * Math.sin(freq * t * 2 * Math.PI) / Math.exp(decay * t);\n" +
            "value + [v, 0];";
        solidLayer.property("ADBE Marker").setValueAtTime(solidLayer.inPoint, new MarkerValue(" ↔ 抖动"));
    } else if (selectedOption === "↘") {
        positionProperty.expression = 
            "amp = effect(\"振幅\")(\"滑块\");\n" +
            "freq = effect(\"频率\")(\"滑块\");\n" +
            "decay = effect(\"阻力\")(\"滑块\");\n" +
            "t = time - inPoint;\n" +
            "v = amp * Math.sin(freq * t * 2 * Math.PI) / Math.exp(decay * t);\n" +
            "value + [v, v];";
        solidLayer.property("ADBE Marker").setValueAtTime(solidLayer.inPoint, new MarkerValue(" ↘ 抖动"));
    } else if (selectedOption === "↙") {
        positionProperty.expression = 
            "amp = effect(\"振幅\")(\"滑块\");\n" +
            "freq = effect(\"频率\")(\"滑块\");\n" +
            "decay = effect(\"阻力\")(\"滑块\");\n" +
            "t = time - inPoint;\n" +
            "v = amp * Math.sin(freq * t * 2 * Math.PI) / Math.exp(decay * t);\n" +
            "value + [v, -v];";
        solidLayer.property("ADBE Marker").setValueAtTime(solidLayer.inPoint, new MarkerValue(" ↙ 抖动"));
    }

    // 如果有选中的图层，将调整图层移动到第一个选中图层的上方
    if (selectedLayers.length > 0) {
        solidLayer.moveBefore(selectedLayers[0]);
    }
}


