var offsetButton = buttonRow3.add("button", [0, 0, 45, 20], "排序");
offsetButton.helpTip = "取决选定图层顺序进行排序的";
var offsetTypeDropdown = buttonRow3.add("dropdownlist", [0,0, 60, 20], ["序列","对齐", "偏移", "随机"]);
offsetTypeDropdown.selection = 0; 
var offsetAmountInput = buttonRow3.add("edittext", [0, 0, 40, 20], "0");
buttonRow3.add("statictext", [0, 0, 22, 20], "帧");
//序列排序
offsetButton.onClick = function() {
    var offsetTypeIndex = offsetTypeDropdown.selection.index;
    var offsetAmountValue = offsetAmountInput.text;
    offsetAmountValue = convertToFrames(offsetAmountValue);
    doOffsetLayers(offsetTypeIndex, offsetAmountValue);
};

// 将用户输入的值转换为帧数
function convertToFrames(value) {
    value = Number(value.replace(new RegExp(",", "g"), ".")); // 处理小数点格式
    return Math.floor(value);
}

// 激活合成查看器
function activateCompViewer() {
    var A = app.activeViewer && app.activeViewer.type === ViewerType.VIEWER_COMPOSITION;
    if (A) {
        app.activeViewer.setActive();
    }
    return A;
}

// 随机打乱图层顺序
function shuffleLayers(array) {
    var currentIndex = array.length;
    while (0 !== currentIndex) {
        var randomIndex = Math.floor(Math.random() * currentIndex);
        currentIndex--;
        var temporaryValue = array[currentIndex];
        array[currentIndex] = array[randomIndex];
        array[randomIndex] = temporaryValue;
    }
    return array;
}

// 执行图层偏移操作
function doOffsetLayers(offsetType, offsetAmount) {
    try {
        var comp = activateCompViewer() ? app.project.activeItem : null;
        offsetAmount = offsetAmount || 0;
        if (!comp || !(comp instanceof CompItem)) {
            alert("请确保选择了一个有效的合成。");
            return;
        }
        var initialSelectedLayers = comp.selectedLayers;
        if (initialSelectedLayers.length < 1) {
            alert("请选择一些图层，然后重试");
            return;
        }

        // 使用当前选定图层的顺序
        var sortedLayers = initialSelectedLayers;

        offsetAmount = offsetAmount * comp.frameDuration;

        // 根据选择的偏移类型执行不同的操作
        if (offsetType === 2) { // 偏移
            app.beginUndoGroup("图层偏移");
            for (var i = 0; i < sortedLayers.length; i++) {
                sortedLayers[i].startTime += offsetAmount * i;
            }
            app.endUndoGroup();
        } else if (offsetType === 0) { // 序列
            app.beginUndoGroup("序列");
            var prevOut = sortedLayers[0].outPoint;
            for (var i = 1; i < sortedLayers.length; i++) {
                var sub = (sortedLayers[i].inPoint - sortedLayers[i].startTime) - offsetAmount;
                sortedLayers[i].startTime = prevOut - sub;
                prevOut = sortedLayers[i].outPoint;
            }
            app.endUndoGroup();
        } else if (offsetType === 3) { // 随机
            app.beginUndoGroup("随机偏移");
            sortedLayers = shuffleLayers(sortedLayers);
            for (var i = 0; i < sortedLayers.length; i++) {
                sortedLayers[i].startTime += Math.random() * offsetAmount; // 随机偏移
            }
            app.endUndoGroup();
        } else if (offsetType === 1) { // 对齐
            app.beginUndoGroup("图层对齐到时间指示器");
            var timeIndicator = comp.time; // 获取时间指示器的位置
            for (var i = 0; i < sortedLayers.length; i++) {
                var layer = sortedLayers[i];
                var offsetAmount = timeIndicator - layer.inPoint;
                layer.startTime += offsetAmount; // 将图层对齐到时间指示器
            }
            app.endUndoGroup();
        }
    } catch (e) {
        alert("代码行错误: " + e.line + "\n" + e.toString());
    }
}



