var Picturesettings = buttonRow4.add("button", undefined, "PNG ≡")
Picturesettings.preferredSize = [40, 25];
Picturesettings.helpTip = "截图设置";
// 默认文件夹设置
var folderExport = getSavedPath();  // 获取上次保存的路径
PNGScreenshotButton.onClick = function() {
    takeScreenshot();  // 保存截图，使用最新的folderExport路径
};

// 保存当前帧为PNG的函数
var takeScreenshot = function() {
    try {
        // 选择保存文件夹
        if (!folderExport) {
            folderExport = Folder.selectDialog("请选择保存屏幕截图的位置");
            if (folderExport == null) {
                alert("未选择文件夹。屏幕截图未保存。");
                return false;
            }
        }

        // 弹出对话框让用户输入文件名
        var fileName = prompt("保存图片名称:", "");

        if (fileName === null || typeof fileName !== 'string' || fileName.replace(/^\s+|\s+$/g, "") === "") {
            alert("保存取消！");
            return false;
        }

        fileName = fileName.replace(/^\s+|\s+$/g, "");

        var compItem = getActiveComp();
        if (compItem) {
            var compItemFrame = Math.floor(compItem.time / compItem.frameDuration);
            var filePng = new File(folderExport.fsName + "/" + fileName + ".png");

            // 检查文件名冲突并调整文件名
            var fileIndex = 1;
            while (filePng.exists) {
                filePng = new File(folderExport.fsName + "/" + fileName + " (" + fileIndex + ").png");
                fileIndex++;
            }

            try {
                // 保存当前帧为PNG
                compItem.saveFrameToPng(compItem.time, filePng);
                alert("保存路径: " + filePng.fsName);
                savePath(folderExport);  // 保存新的路径

                // 如果勾选了“截图后导入项目”复选框，则导入PNG
                if (getImportOption()) {
                    app.project.importFile(new ImportOptions(filePng));
                }

                return true;
            } catch ($e) {
                alert("无法保存屏幕截图。错误： " + $e.toString());
                return false;
            }
        } else {
            alert("先点合成，再重试！");
            return false;
        }
    } catch ($e) {
        alert("出现错误： " + $e.toString());
        return false;
    }
};

// 获取当前活动合成的函数
function getActiveComp() {
    if (app.project.activeItem instanceof CompItem) {
        return app.project.activeItem;
    }
    return null;
}

// 创建弹窗按钮
Picturesettings.onClick = function() {
    var popUpWindow = new Window("dialog", "设置");

    var Group1 = popUpWindow.add("group");
    Group1.orientation = "row";
    Group1.spacing = 2;
    Group1.margins = 0;
    Group1.add("statictext", undefined, "保存路径");

    var folderPathText = Group1.add("edittext", [0, 0, 300, 25], folderExport.fsName);

    var browseButton = Group1.add("button", [0, 0, 80, 25], "浏览");

    // 选择文件夹按钮事件
    browseButton.onClick = function() {
        var selectedFolder = Folder.selectDialog("选择保存路径");
        if (selectedFolder != null) {
            folderPathText.text = selectedFolder.fsName;
            folderExport = selectedFolder;  // 更新全局保存路径
        }
    };

    // 添加复选框：截图后导入项目
    var importCheckbox = popUpWindow.add("checkbox", undefined, "截图后导入项目");
    importCheckbox.value = getImportOption();  // 从文件中获取上次的设置

    var POPUpButton = popUpWindow.add("button", [0, 0, 50, 25], "确定");
    POPUpButton.onClick = function() {
        savePath(folderExport);
        saveImportOption(importCheckbox.value);  // 保存复选框设置
        popUpWindow.close();
    };

    // 显示弹窗窗口
    popUpWindow.show();
};

// 获取上次保存的路径
function getSavedPath() {
    var pathFile = new File(Folder.userData.fsName + "/savedPath.txt");
    if (pathFile.exists) {
        pathFile.open("r");
        var savedPath = pathFile.read();
        pathFile.close();
        var folder = new Folder(savedPath);
        if (folder.exists) {
            return folder;
        }
    }
    return Folder.desktop;  // 如果没有找到保存的路径，则返回桌面
}

// 保存当前路径
function savePath(path) {
    var pathFile = new File(Folder.userData.fsName + "/savedPath.txt");
    pathFile.open("w");
    pathFile.write(path.fsName);  // 保存路径
    pathFile.close();
}

// 保存“截图后导入项目”的选项
function saveImportOption(shouldImport) {
    var file = new File(Folder.userData.fsName + "/importAfterShot.txt");
    file.open("w");
    file.write(shouldImport ? "1" : "0");
    file.close();
}

// 获取“截图后导入项目”的选项
function getImportOption() {
    var file = new File(Folder.userData.fsName + "/importAfterShot.txt");
    if (file.exists) {
        file.open("r");
        var content = file.read();
        file.close();
        return content === "1";
    }
    return false;  // 默认不导入
}


