var keycopy = buttonRow5.add("button", undefined, "Key复制");
keycopy.preferredSize = [55, 25];
keycopy.helpTip = "复制关键帧:直接单击正常复制，\n按shift+单击反转复制!\n跨图层复制:先选中关键帧，\n在选其他要复制关键帧的图层，\n单击按钮即可！";
keycopy.onClick = function () {
    app.beginUndoGroup("判断操作并执行");
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请选择一个合成！");
        return;
    }
    var selectedLayers = comp.selectedLayers;
    var keyframeLayer = null;
    // 判断是否选中了关键帧
    for (var i = 0; i < selectedLayers.length; i++) {
        var props = selectedLayers[i].selectedProperties;
        for (var j = 0; j < props.length; j++) {
            if (props[j] instanceof Property && props[j].isTimeVarying && props[j].selectedKeys.length > 0) {
                keyframeLayer = selectedLayers[i];
                break;
            }
        }
        if (keyframeLayer) break;
    }
    if (!keyframeLayer) {
        alert("请先选中至少一个关键帧！");
        app.endUndoGroup();
        return;
    }
    if (selectedLayers.length === 1) {
        keyAOBJ();//执行原图层复制关键帧
    } else {
         // 记录时间指示器的原始位置
        var originalTime = comp.time;
        keyBOBJ();//执行关键帧复制粘贴多个图层
         // 还原时间指示器到原始位置
        comp.time = originalTime;
    }
    app.endUndoGroup();
};

function keyAOBJ() {
    // 检查是否选中了关键帧
function hasSelectedKeyframes() {
    if (app.project.activeItem && app.project.activeItem instanceof CompItem) {
        var comp = app.project.activeItem;
        for (var i = 0; i < comp.selectedLayers.length; i++) {
            var layer = comp.selectedLayers[i];
            var props = layer.selectedProperties;
            for (var j = 0; j < props.length; j++) {
                if (props[j].numKeys > 0 && props[j].selectedKeys.length > 0) {
                    return true;
                }
            }
        }
    }
    return false;
}
    if (!hasSelectedKeyframes()) {
        alert("请先选中关键帧再执行！");
        return;
    }
    app.executeCommand(19); // 复制
    app.executeCommand(20); // 粘贴
};

function keyBOBJ() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请选择一个合成！");
        return;
    }

    var allLayers = comp.layers;
    var selectedLayers = comp.selectedLayers;
    var targetLayer = null;
    var targetProperty = null;
    var targetKeyIndex = null;

    // 找出选中图层中选中的关键帧
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        var props = layer.selectedProperties;

        for (var j = 0; j < props.length; j++) {
            var prop = props[j];
            if (prop instanceof Property && prop.isTimeVarying) {
                var selectedKeys = prop.selectedKeys;
                if (selectedKeys.length > 0) {
                    targetLayer = layer;
                    targetProperty = prop;
                    targetKeyIndex = selectedKeys[0];
                    break;
                }
            }
        }
        if (targetLayer) break;
    }

    if (!targetLayer || !targetProperty) {
        alert("没有找到选中的关键帧！");
        return;
    }

    var hasEffects = (targetLayer.property("ADBE Effect Parade") != null && targetLayer.property("ADBE Effect Parade").numProperties > 0);

    // 取消所有图层的选中状态
    for (var k = 1; k <= allLayers.length; k++) {
        allLayers[k].selected = false;
    }

    // 只选目标图层和关键帧
    targetLayer.selected = true;
    var props = targetLayer.selectedProperties;
    for (var m = 0; m < props.length; m++) {
        props[m].selected = false;
    }
    targetProperty.selected = true;
    targetProperty.setSelectedAtKey(targetKeyIndex, true);

    var onlyCopyKeyframes = selectedLayers.length <= 1;

    if (!onlyCopyKeyframes && hasEffects) {
        var effectGroup = targetLayer.property("ADBE Effect Parade");
        for (var e = 1; e <= effectGroup.numProperties; e++) {
            effectGroup.property(e).selected = true;
        }
    }

    app.executeCommand(19); // 复制
    targetLayer.selected = false;
    // 如果没有选中其他图层，就默认选当前图层
    if (selectedLayers.length === 0) {
        selectedLayers.push(targetLayer);
    }

    for (var n = 0; n < selectedLayers.length; n++) {
        var layer = selectedLayers[n];
        // 跳过源图层本身
        if (layer === targetLayer) continue;
        // 定位时间指示器到该图层的入点
        comp.time = layer.inPoint;
        // 选中图层
        layer.selected = true;
        // 粘贴关键帧和效果
        app.executeCommand(20);
        // 取消选中，避免多余干扰
        layer.selected = false;
    }
}

// ***********反向复制按钮*****************
keycopy.addEventListener("mousedown", function (event) {
      app.beginUndoGroup("关键帧反向复制");
    // 检查是否按下了shift键
    if (event.shiftKey) {
        // 获取“时间反向关键帧”命令的 ID（中英文兼容）
        function getReverseKeyframesCommandId() {
            var names = [
                "时间反向关键帧",       // 中文
                "Time-Reverse Keyframes" // 英文
            ];
            for (var i = 0; i < names.length; i++) {
                var id = app.findMenuCommandId(names[i]);
                if (id) return id;
            }
            return null;
        }

        // 检查是否选中了关键帧
        function hasSelectedKeyframes() {
            if (app.project.activeItem && app.project.activeItem instanceof CompItem) {
                var comp = app.project.activeItem;
                for (var i = 0; i < comp.selectedLayers.length; i++) {
                    var layer = comp.selectedLayers[i];
                    var props = layer.selectedProperties;
                    for (var j = 0; j < props.length; j++) {
                        if (props[j].numKeys > 0 && props[j].selectedKeys.length > 0) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        var comp = app.project.activeItem;
        if (!(comp && comp instanceof CompItem)) return;

        if (comp.selectedLayers.length > 1) {
            alert("请只选择一个图层进行操作！");
            return;
        }

        if (!hasSelectedKeyframes()) {
            alert("请先选中关键帧再执行！");
            return;
        }
        app.executeCommand(19); // 复制
        app.executeCommand(20); // 粘贴
        var cmdId = getReverseKeyframesCommandId();
        if (cmdId) {
            app.executeCommand(cmdId); // 执行反向关键帧
        }
        app.endUndoGroup();
    }
});

var proportionality = buttonRow5.add("button", [0,0,60,25], "形状锁边");
proportionality.onClick = function() {
var comp = app.project.activeItem;
if (comp && comp instanceof CompItem) {
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length > 0) {
        app.beginUndoGroup("自动识别形状并应用");

        for (var i = 0; i < selectedLayers.length; i++) {
            var layer = selectedLayers[i];
            var contents = layer.property("ADBE Root Vectors Group");

            if (contents) {
                for (var j = 1; j <= contents.numProperties; j++) {
                    var shapeGroup = contents.property(j);
                    if (shapeGroup.matchName === "ADBE Vector Group") {
                        var vectorProps = shapeGroup.property("ADBE Vectors Group");

                        // 遍历每个形状路径
                        for (var k = 1; k <= vectorProps.numProperties; k++) {
                            var path = vectorProps.property(k);

                            if (path.matchName === "ADBE Vector Shape - Rect") {
                                applyRectangleFunction(path, vectorProps);
                            } else if (path.matchName === "ADBE Vector Shape - Ellipse") {
                                applyEllipseFunction(path, vectorProps);
                            } else if (path.matchName === "ADBE Vector Shape - Star") {
                                applyStarFunction(path, vectorProps);
                            } else if (path.matchName === "ADBE Vector Shape") {
                                applyPathFunction(path);
                            }
                        }

                        // 选中 Transform -> Scale 并添加表达式
                        var transform = shapeGroup.property("ADBE Vector Transform Group");
                        if (transform) {
                            var scale = transform.property("ADBE Vector Scale");
                            if (scale) {
                                scale.selected = true;
                                scale.expression =
                                    "var scaleX = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[0]);\n" +
                                    "var scaleY = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[1]);\n" +
                                    "if (scaleX > 0 && scaleY > 0) {\n" +
                                    "    [value[0] / scaleX * 100, value[1] / scaleY * 100];\n" +
                                    "} else {\n" +
                                    "    [0, 0];\n" +
                                    "}";
                            }
                        }
                    }
                }
            }
        }
       Starshape();
        app.endUndoGroup();
    } else {
        alert("请选中一个形状图层！");
    }
} else {
    alert("请打开一个合成！");
    }
}

// ======================== 函数部分 ========================

// 矩形
function applyRectangleFunction(path, vectorProps) {
    var size = path.property("ADBE Vector Rect Size");
    if (size) {
        size.selected = true;
        size.expression =
            "var scaleX = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[0]);\n" +
            "var scaleY = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[1]);\n" +
            "[value[0] * (scaleX / 100), value[1] * (scaleY / 100)];";
    }
    applyStrokeWidth(vectorProps, "ADBE Vector Rect Size");
}

// 椭圆
function applyEllipseFunction(path, vectorProps) {
    var size = path.property("ADBE Vector Ellipse Size");
    if (size) {
        size.selected = true;
        size.expression =
            "var scaleX = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[0]);\n" +
            "var scaleY = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[1]);\n" +
            "[value[0] * (scaleX / 100), value[1] * (scaleY / 100)];";
    }
    applyStrokeWidth(vectorProps, "ADBE Vector Ellipse Size");
}

// 星形（外径）
function applyStarFunction(path, vectorProps) {
    var outerRadius = path.property("ADBE Vector Star Outer Radius");
    if (outerRadius) {
        outerRadius.selected = true;
        outerRadius.expression =
            "var scaleX = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[0]);\n" +
            "value * (scaleX / 100);";
    }
    applyStrokeWidth(vectorProps, "ADBE Vector Star Outer Radius");
}

// 手绘路径
function applyPathFunction(path) {
    var pathProp = path.property("ADBE Vector Shape");
    if (pathProp) {
        pathProp.selected = true;
        // 可拓展自定义逻辑
    }
}

// 通用 Stroke 宽度限制处理
function applyStrokeWidth(vectorProps, refPropertyName) {
    var stroke = vectorProps.property("ADBE Vector Graphic - Stroke");
    if (stroke) {
        var strokeWidth = stroke.property("ADBE Vector Stroke Width");
        if (strokeWidth) {
            strokeWidth.selected = true;
             strokeWidth.expression =
            "var strokeW = value;\n" +
            "var group = thisProperty.propertyGroup(1).propertyGroup(1).propertyGroup(1);\n" +
            "var radius = group(\"ADBE Vectors Group\")(1)(\"" + refPropertyName + "\");\n" +
            "if (radius <= strokeW / 2) {\n" +
            "strokeW = radius * 2;\n" +
            "}\n" +
            "strokeW;";
        }
    }
} 

function Starshape() {
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length > 0) {
            // 检查是否有内径属性
            var hasInnerRadius = false;

            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                var contents = layer.property("ADBE Root Vectors Group");
                if (contents) {
                    for (var j = 1; j <= contents.numProperties; j++) {
                        var shapeGroup = contents.property(j);
                        if (shapeGroup.matchName === "ADBE Vector Group") {
                            var vectorProps = shapeGroup.property("ADBE Vectors Group");
                            for (var k = 1; k <= vectorProps.numProperties; k++) {
                                var path = vectorProps.property(k);
                                if (path.matchName === "ADBE Vector Shape - Star") {
                                    // 检查是否存在 Inner Radius 属性
                                    var innerRadius = path.property("ADBE Vector Star Inner Radius");
                                    if (innerRadius) {
                                        hasInnerRadius = true;
                                    }
                                }
                            }
                        }
                    }
                }
            }
           // 检查：是否有内径执行
            if (!hasInnerRadius) {
                return; // 取消执行
            }

            // 对选中图层进行操作
            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                var contents = layer.property("ADBE Root Vectors Group");
                if (contents) {
                    for (var j = 1; j <= contents.numProperties; j++) {
                        var shapeGroup = contents.property(j);
                        if (shapeGroup.matchName === "ADBE Vector Group") {
                            var vectorProps = shapeGroup.property("ADBE Vectors Group");
                            for (var k = 1; k <= vectorProps.numProperties; k++) {
                                var path = vectorProps.property(k);
                                if (path.matchName === "ADBE Vector Shape - Star") {
                                    // 选中 Outer Radius（外径）
                                    var outerRadius = path.property("ADBE Vector Star Outer Radius");
                                    if (outerRadius) {
                                        outerRadius.selected = true;
                                        outerRadius.expression = "var scaleX = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[0]);\n" +
                                                                 "var scaleY = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[1]);\n" +
                                                                 "value * (scaleX / 100);";
                                    }

                                    // 选中 Inner Radius（内径）
                                    var innerRadius = path.property("ADBE Vector Star Inner Radius");
                                    if (innerRadius) {
                                        innerRadius.selected = true;
                                        innerRadius.expression = "var scaleX = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[0]);\n" +
                                                                 "var scaleY = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[1]);\n" +
                                                                 "value * (scaleX / 100);";
                                    }
                                } else if (path.matchName === "ADBE Vector Shape") { // 处理手绘路径
                                    var pathProp = path.property("ADBE Vector Shape");
                                    if (pathProp) {
                                        pathProp.selected = true;
                                    }
                                }
                            }
                            // 选中描边宽度（Stroke Width）
                            var stroke = vectorProps.property("ADBE Vector Graphic - Stroke");
                            if (stroke) {
                                var strokeWidth = stroke.property("ADBE Vector Stroke Width");
                                if (strokeWidth) {
                                    strokeWidth.selected = true;
                                    strokeWidth.expression = "var strokeW = value;\n" +
                                                             "var curShape = thisProperty.propertyGroup(1).propertyGroup(1).propertyGroup(1);\n" +
                                                             "var outerRadius = curShape(\"ADBE Vectors Group\")(1)(\"ADBE Vector Star Outer Radius\");\n" +
                                                             "if (outerRadius && outerRadius <= strokeW) {\n" +
                                                             "    strokeW = outerRadius;\n" +
                                                             "}\n" +
                                                             "strokeW;";
                                }
                            }
                            // 选中形状组的 Transform -> Scale
                            var transform = shapeGroup.property("ADBE Vector Transform Group");
                            if (transform) {
                                var scale = transform.property("ADBE Vector Scale");
                                if (scale) {
                                    scale.selected = true;
                                    scale.expression = "var scaleX = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[0]);\n" +
                                                       "var scaleY = Math.abs(thisLayer(\"ADBE Transform Group\")(\"ADBE Scale\")[1]);\n" +
                                                       "if (scaleX > 0 && scaleY > 0) {\n" +
                                                       "    [value[0] / scaleX * 100, value[1] / scaleY * 100];\n" +
                                                       "} else {\n" +
                                                       "    [0, 0];\n" +
                                                       "}";
                                }
                            }
                        }
                    }
                }
            }
        } else {
            alert("请选中一个形状图层！");
        }
    } else {
        alert("请打开一个合成！");
    }
}

