var SRTButton1 = buttonRow6.add("button", [0, 0, 55, 25], "导入SRT");
var SRTButton2 = buttonRow6.add("button", [0, 0, 55, 25], "导出SRT");

SRTButton1.onClick = function(){
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return;

    var file = File.openDialog("选择SRT文件","*.srt");
    if (!file) return;

    file.open("r");
    var txt = file.read();
    file.close();

    app.beginUndoGroup("导入SRT字幕");

    // 统一换行符
    txt = txt.replace(/\r\n/g,"\n").replace(/\r/g,"\n");

    var blocks = txt.split("\n\n");

    function timeToSec(t){

        var p = t.split(":");
        var s = p[2].split(",");

        return Number(p[0])*3600 +
               Number(p[1])*60 +
               Number(s[0]) +
               Number(s[1])/1000;
    }

    for(var i=0;i<blocks.length;i++){

        var lines = blocks[i].split("\n");

        if(lines.length < 2) continue;

        var timeLine = lines[1];

        if(timeLine.indexOf("-->") == -1) continue;

        var times = timeLine.split(" --> ");

        var start = timeToSec(times[0]);
        var end = timeToSec(times[1]);

        var text = "";

        for(var j=2;j<lines.length;j++){
            text += lines[j];
            if(j < lines.length-1) text += "\r";
        }

        if(text == "") continue;

        var layer = comp.layers.addText(text);

        // ===== 文字样式 =====
        var textProp = layer.property("Source Text");
        var textDoc = textProp.value;

        textDoc.fontSize = 60;
        textDoc.fillColor = [1,1,1]; // 白色
        textDoc.justification = ParagraphJustification.CENTER_JUSTIFY;

        textProp.setValue(textDoc);

        // ===== 时间 =====
        layer.inPoint = start;
        layer.outPoint = end;

        // ===== 锚点居中 =====
        var rect = layer.sourceRectAtTime(0,false);
        layer.anchorPoint.setValue([
            rect.left + rect.width/2,
            rect.top + rect.height/2
        ]);

        // ===== 底部居中 =====
        layer.position.setValue([
            comp.width/2,
            comp.height - 120
        ]);
    }

    app.endUndoGroup();
};

SRTButton2.onClick = function(){
        var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;
    if (layers.length === 0) return;

    // ===== 选择保存路径 =====
    var saveFile = File.saveDialog("保存SRT文件", "*.srt");
    if (!saveFile) return;

    function formatTime(t) {
        var h = Math.floor(t / 3600);
        var m = Math.floor((t % 3600) / 60);
        var s = Math.floor(t % 60);
        var ms = Math.floor((t % 1) * 1000);

        function pad(n, len) {
            return ("000" + n).slice(-len);
        }

        return pad(h,2) + ":" + pad(m,2) + ":" + pad(s,2) + "," + pad(ms,3);
    }

    var index = 1;
    var srt = "";

    app.beginUndoGroup("导出SRT");

    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];

        if (!(layer instanceof TextLayer)) continue;

        var text = layer.property("Source Text").value.text;
        var start = layer.inPoint;
        var end = layer.outPoint;

        srt += index + "\n";
        srt += formatTime(start) + " --> " + formatTime(end) + "\n";
        srt += text + "\n\n";

        index++;
    }

    app.endUndoGroup();

    // ===== 写入文件 =====
    saveFile.encoding = "UTF-8";
    saveFile.open("w");
    saveFile.write(srt);
    saveFile.close();
}


