// 随机不重复函数
function getUniqueRandomIntegers(count, min, max) {
    var numbers = [];
    for (var i = min; i <= max; i++) numbers.push(i);
    // Fisher–Yates 洗牌算法
    for (var i = numbers.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var temp = numbers[i];
        numbers[i] = numbers[j];
        numbers[j] = temp;
    }
    return numbers.slice(0, count);
}

