//裁剪目标区域

btnCrop.onClick=function(){Targetarea();unfocus(this);};
function Targetarea(){
app.beginUndoGroup("CropROI");
try{
var comp=app.project.activeItem;
if(!comp||!(comp instanceof CompItem)){alert("Please select a composition first!");return;}
var selectedLayers=comp.selectedLayers;
if(selectedLayers.length!==1){alert("Please select the precomp layer");return;}
var precompLayer=selectedLayers[0];
var precomp=precompLayer.source;
if(!precomp||!(precomp instanceof CompItem)){alert("Please select the precomp layer");return;}
var tempSavedParent=precompLayer.parent;
var saveA=precompLayer.property("ADBE Transform Group").property("ADBE Anchor Point").valueAtTime(comp.time,false);
var saveP=precompLayer.property("ADBE Transform Group").property("ADBE Position").valueAtTime(comp.time,false);
var anchorWorldA=getAnchorWorld(precompLayer,comp);
if(precomp.layers.length<1){alert("Error, precomp has no layers");return;}
var savedChildren=getChildrenOf(precompLayer);
unparentAll(savedChildren);
precomp.openInViewer();
var pos1=getPos1(precomp);
app.executeCommand(2997);
var pos2=getPos2(precomp);
var posDif=pos2-pos1;
comp.openInViewer();
var rect=precompLayer.sourceRectAtTime(comp.time,false);
var w=rect.width,h=rect.height;
var aAdj=[w/2,h/2,0];
var aProp=precompLayer.property("ADBE Transform Group").property("ADBE Anchor Point");
if(aProp.numKeys){aProp.setValueAtTime(comp.time,aAdj);}else{aProp.setValue(aAdj);}
var pProp=precompLayer.property("ADBE Transform Group").property("ADBE Position");
if(propHasKeys(pProp)){offsetKeyValues(pProp,precompLayer,comp,(-posDif-saveA)+aAdj);}
else{setValueOfProp(pProp,((saveP-posDif)-saveA)+aAdj);}
var anchorWorldB=getAnchorWorld(precompLayer,comp);
var anchorWorldDiff=anchorWorldB-anchorWorldA;
if(aProp.numKeys){aProp.setValueAtTime(comp.time,aProp.valueAtTime(comp.time,true)-anchorWorldDiff);}
else{aProp.setValue(aProp.value-anchorWorldDiff);}
if(propHasKeys(pProp)){offsetKeyValues(pProp,precompLayer,comp,-anchorWorldDiff);}
else{setValueOfProp(pProp,pProp.value-anchorWorldDiff);}
precompLayer.parent=tempSavedParent;
reparentAll(savedChildren,precompLayer);
}catch(err){alert("ERROR\nLine "+err.line+"\n"+err.toString());}
finally{app.endUndoGroup();}
}

function getChildrenOf(l){var c=l.containingComp,childrenFound=[];for(var i=1;i<=c.numLayers;i++){var curLayer=c.layer(i);if(curLayer.parent===l){childrenFound.push(curLayer);}}return childrenFound;}
function unparentAll(a){for(var i=0;i<a.length;i++){var curLayer=a[i],isLocked=false;if(curLayer.locked){isLocked=true;curLayer.locked=false;}curLayer.parent=null;if(isLocked){curLayer.locked=true;}}}
function reparentAll(a,l){for(var i=0;i<a.length;i++){var curLayer=a[i],isLocked=false;if(curLayer.locked){isLocked=true;curLayer.locked=false;}curLayer.parent=l;if(isLocked){curLayer.locked=true;}}}

function propHasKeys(prp){
if(!prp.dimensionsSeparated&&prp.numKeys){return true;}
if(prp.dimensionsSeparated){for(var i=0;i<2;i++){if(prp.getSeparationFollower(i).numKeys>0){return true;}}}
return false;
}

function setValueOfProp(prp,val){
if(prp.dimensionsSeparated){for(var i=0;i<2;i++){prp.getSeparationFollower(i).setValue(val[i]);}}
else{prp.setValue(val);}
}

function offsetKeyValues(prop,layer,comp,valToAdd){
try{
if(prop.dimensionsSeparated){
for(var j=0;j<2;j++){
var curDimension=prop.getSeparationFollower(j);
for(var i=1;i<=curDimension.numKeys;i++){
curDimension.setValueAtKey(i,curDimension.valueAtTime(curDimension.keyTime(i),true)+valToAdd[j]);
}}}
else{
for(var i=1;i<=prop.numKeys;i++){
prop.setValueAtKey(i,prop.valueAtTime(prop.keyTime(i),true)+valToAdd);
}}}
catch(err){alert(err.toString());}
}

function getAnchorWorld(l,comp){
var temp3D=l.property("ADBE Effect Parade").addProperty("ADBE Point3D Control");
var point3D=temp3D.property(1);
point3D.expression="thisLayer.toWorld(transform.anchorPoint);";
var ret=point3D.valueAtTime(comp.time,false);
temp3D.remove();
return ret;
}

function getPos1(c){
var tempNull=c.layers.addNull();
tempNull.name="CropROI_Temp_Null";
return tempNull.property("ADBE Transform Group").property("ADBE Position").valueAtTime(0,false);
}

function getPos2(c){
var tempNull=c.layer("CropROI_Temp_Null");
var tempPos2=tempNull.property("ADBE Transform Group").property("ADBE Position").valueAtTime(0,false);
tempNull.remove();
return tempPos2;
}

function unfocus(that){that.window.active=false;}

