// 弹性效果按钮
elasticBtn.onClick = function () {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先打开一个合成！");
        return;
    }

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请先选择至少一个图层！");
        return;
    }

    app.beginUndoGroup("Add Bounce Controls");

    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];

        // 添加滑块控制器（如果尚未存在）
        var ampSlider = getOrCreateSlider(layer, "幅度", 20);
        var freqSlider = getOrCreateSlider(layer, "频率", 40);
        var decaySlider = getOrCreateSlider(layer, "阻力", 60);

        // 遍历变换属性并应用表达式
        applyBounceExpression(layer.transform);

        // 遍历效果属性并应用表达式
        for (var k = 1; k <= layer.effect.numProperties; k++) {
            var effectProp = layer.effect.property(k);
            applyBounceExpression(effectProp);
        }
    }

    app.endUndoGroup();
};

// 获取或创建滑块控制器
function getOrCreateSlider(layer, name, defaultValue) {
    var effect = layer.effect;
    for (var i = 1; i <= effect.numProperties; i++) {
        if (effect.property(i).name === name) {
            return effect.property(i);
        }
    }
    var slider = effect.addProperty("ADBE Slider Control");
    slider.name = name;
    slider.property(1).setValue(defaultValue);
    return slider;
}

// 应用弹性表达式
function applyBounceExpression(propGroup) {
    for (var i = 1; i <= propGroup.numProperties; i++) {
        var prop = propGroup.property(i);
        if (prop.canSetExpression && prop.numKeys > 0) {
            var hasSelectedKey = false;

            for (var j = 1; j <= prop.numKeys; j++) {
                if (prop.keySelected(j)) {
                    hasSelectedKey = true;
                    break;
                }
            }

            if (hasSelectedKey) {
                prop.expression = getBounceExpression();
            }
        }
    }
}

// 生成弹性表达式
function getBounceExpression() {
    return "try {\n" +
        "  amp = effect(\"幅度\")(1) / 200;\n" +
        "  freq = effect(\"频率\")(1) / 30;\n" +
        "  decay = effect(\"阻力\")(1) / 10;\n" +
        "  n = 0;\n" +
        "  if (numKeys > 0) {\n" +
        "    n = nearestKey(time).index;\n" +
        "    if (key(n).time > time) {\n" +
        "      n--;\n" +
        "    }\n" +
        "  }\n" +
        "  if (n == 0) {\n" +
        "    t = 0;\n" +
        "  } else {\n" +
        "    t = time - key(n).time;\n" +
        "  }\n" +
        "  if (n > 0) {\n" +
        "    v = velocityAtTime(key(n).time - thisComp.frameDuration / 10);\n" +
        "    value + v * amp * Math.sin(freq * t * 2 * Math.PI) / Math.exp(decay * t);\n" +
        "  } else {\n" +
        "    value;\n" +
        "  }\n" +
        "} catch (e) {\n" +
        "  value;\n" +
        "}";
}
   

    //蒙版居中
    maskButton.onClick = repositionMasks;
    function repositionMasks() {
        try {
            var comp = app.project.activeItem;
            if (!(comp instanceof CompItem)) {
                alert("请先打开一个合成！");
                return;
            }

            var selLayers = comp.selectedLayers;
            if (selLayers.length < 1) {
                alert("请至少选择一个包含遮罩的图层！");
                return;
            }

            var numSelMasks = 0;
            app.beginUndoGroup("居中遮罩");

            // 遍历选中的图层
            for (var i = 0; i < selLayers.length; i++) {
                var layer = selLayers[i];

                // 遍历图层的所有遮罩
                for (var j = 1; j <= layer.Masks.numProperties; j++) {
                    var mask = layer.Masks.property(j);
                    if (mask.selected) {
                        numSelMasks++;

                        var maskShape = mask.maskShape;
                        var shape = maskShape.valueAtTime(comp.time, false);
                        var verts = shape.vertices;
                        var layerCenter = [layer.width / 2, layer.height / 2]; // 图层中心

                        // 计算遮罩的中心
                        var x = 0, y = 0;
                        for (var k = 0; k < verts.length; k++) {
                            x += verts[k][0];
                            y += verts[k][1];
                        }
                        var maskCenter = [x / verts.length, y / verts.length]; // 遮罩中心

                        // 计算偏移量
                        var delta = [layerCenter[0] - maskCenter[0], layerCenter[1] - maskCenter[1]];

                        // 更新遮罩的位置
                        var newVerts = [];
                        for (var k = 0; k < verts.length; k++) {
                            newVerts.push([verts[k][0] + delta[0], verts[k][1] + delta[1]]);
                        }

                        var newShape = new Shape();
                        newShape.vertices = newVerts;
                        newShape.inTangents = shape.inTangents;
                        newShape.outTangents = shape.outTangents;

                        maskShape.setValue(newShape);
                    }
                }
            }

            app.endUndoGroup();

            if (numSelMasks < 1) {
                alert("没有选中任何遮罩！");
            }

        } catch (err) {
            alert("发生错误：" + err.toString());
        }
    }


