//水平镜像和垂直镜像
function mirrorh() {
    app.beginUndoGroup("Horizontal Mirror");
    var mainComp = app.project.activeItem;

    if (!(mainComp && mainComp.selectedLayers.length > 0)) {
        alert("你没有选择图层哦！宝");
        return;
    }

    for (var i = 0; i < mainComp.selectedLayers.length; i++) {
        var selectedLayer = mainComp.selectedLayers[i];
        var ex = selectedLayer.transform.scale.expression;

        switch (ex) {
            case "":
                selectedLayer.transform.scale.expression = "[-value[0], value[1]]";
                break;
            case "[value[0], value[1]]":
                selectedLayer.transform.scale.expression = "[-value[0], value[1]]";
                break;
            case "[-value[0], value[1]]":
                selectedLayer.transform.scale.expression = "[value[0], value[1]]";
                break;
            case "[value[0], -value[1]]":
                selectedLayer.transform.scale.expression = "[-value[0], -value[1]]";
                break;
            case "[-value[0], -value[1]]":
                selectedLayer.transform.scale.expression = "[value[0], -value[1]]";
                break;
        }
    }
    app.endUndoGroup();
}

function mirrorv() {
    app.beginUndoGroup("Vertical Mirror");
    var mainComp = app.project.activeItem;

    if (!(mainComp && mainComp.selectedLayers.length > 0)) {
        alert("Select layer");
        return;
    }

    for (var i = 0; i < mainComp.selectedLayers.length; i++) {
        var selectedLayer = mainComp.selectedLayers[i];
        var ex = selectedLayer.transform.scale.expression;

        switch (ex) {
            case "":
                selectedLayer.transform.scale.expression = "[value[0], -value[1]]";
                break;
            case "[value[0], value[1]]":
                selectedLayer.transform.scale.expression = "[value[0], -value[1]]";
                break;
            case "[value[0], -value[1]]":
                selectedLayer.transform.scale.expression = "[value[0], value[1]]";
                break;
            case "[-value[0], value[1]]":
                selectedLayer.transform.scale.expression = "[-value[0], -value[1]]";
                break;
            case "[-value[0], -value[1]]":
                selectedLayer.transform.scale.expression = "[-value[0], value[1]]";
                break;
        }
    }
    app.endUndoGroup();
}   

