function processSoundToMarkers(threshold, minInterval, transferMarkers) {
    app.beginUndoGroup("Sound to Markers");
    var comp = app.project.activeItem;

    if (comp && comp instanceof CompItem && comp.selectedLayers.length > 0) {
        var audioLayer = comp.selectedLayers[0];

        // 执行 "Convert Audio to Keyframes"
        app.executeCommand(app.findMenuCommandId("将音频转换为关键帧"));
        var nullLayer = comp.layer(1);

        // 查找 "Both Channels" 或 "两个通道" 效果
        var audioEffect = nullLayer.effect.property("两个通道") || nullLayer.effect.property("Both Channels");
        if (audioEffect) {
            createMarkers(audioEffect.property(1), audioLayer, threshold, minInterval, transferMarkers); // 标记应用到选定的音频图层
            nullLayer.remove(); // 删除生成的 Null 层
        } else {
            alert("无法找到 '两个通道' 或 'Both Channels' 效果。请确保正确生成关键帧。");
        }
    } else {
        alert("请选中一个音频图层并确保当前项目是合成。");
    }
    audioLayer.label = 0;
    app.endUndoGroup();
}

function createMarkers(property, audioLayer, threshold, minInterval, transferMarkers) {
    var markerProperty = audioLayer.property("ADBE Marker");
    if (!markerProperty) {
        alert("无法访问标记属性。");
        return;
    }
    var lastMarkerTime = -1;
    for (var i = 1; i <= property.numKeys; i++) {
        var keyValue = property.keyValue(i);
        var keyTime = property.keyTime(i);
        if (keyValue >= threshold && (lastMarkerTime === -1 || keyTime - lastMarkerTime >= minInterval)) {
            createMarker(markerProperty, keyValue, keyTime, transferMarkers);
            lastMarkerTime = keyTime;
        }
    }
}

function createMarker(markerProperty, keyValue, keyTime, transferMarkers) {
    var myMarker = new MarkerValue("");
    markerProperty.setValueAtTime(keyTime, myMarker);

    // 如果勾选了复选框，将标记转移到合成时间线后删除选定图层的标记
    if (transferMarkers) {
        var comp = app.project.activeItem;
        var newMarker = new MarkerValue("");
        comp.markerProperty.setValueAtTime(keyTime, newMarker);
        
        // 删除选定图层上的标记
        markerProperty.removeKey(markerProperty.nearestKeyIndex(keyTime));
    }
}

