function cardA() {
   var selectedLayers = app.project.activeItem.selectedLayers; // 获取当前合成中选中的图层
    if (selectedLayers.length > 0) {

        for (var i = 0; i < selectedLayers.length; i++) {
            var selectedLayer = selectedLayers[i]; // 当前选中的图层

            // 获取图层的边界矩形信息（不包含变换信息）
            var layerRect = selectedLayer.sourceRectAtTime(0, false);
            var layerWidth = layerRect.width;
            var layerHeight = layerRect.height;

            var layerScale = selectedLayer.scale.value; // 获取图层缩放
            var layerPosition = selectedLayer.position.value; // 获取图层位置
            var layerAnchor = selectedLayer.anchorPoint.value; // 获取图层锚点

            // 计算生成的形状图层应放置的位置
            var shapePosition = [
                layerPosition[0] + (layerRect.left + layerRect.width / 2) - layerAnchor[0],
                layerPosition[1] + (layerRect.top + layerRect.height / 2) - layerAnchor[1]
            ];

            // 创建新的形状图层
            var shapeLayer = app.project.activeItem.layers.addShape();

            // 添加一个矢量组（形状的容器）
            var rectGroup = shapeLayer.content.addProperty("ADBE Vector Group");

            // 在组内添加矩形路径
            var rect = rectGroup.content.addProperty("ADBE Vector Shape - Rect");
            rect.size.setValue([layerWidth, layerHeight]); // 设置矩形大小为与原图层一致

            // 添加填充属性，并设置颜色为红色
            var fill = rectGroup.content.addProperty("ADBE Vector Graphic - Fill");
            fill.color.setValue([1, 1, 1, 1]); // 红色，RGBA 格式

            // 添加描边属性，并绑定颜色为填充颜色
            var stroke = rectGroup.content.addProperty("ADBE Vector Graphic - Stroke");
            stroke.color.expression = "content('组 1').content('填充 1').color"; // 使用表达式绑定描边颜色
            stroke.opacity.setValue(100); // 设置不透明度为 100%
            stroke.strokeWidth.setValue(parseFloat(miaobian.text)); // 设置描边粗细，从输入框读取

            // 设置形状图层的位置和缩放，保持一致
            shapeLayer.position.setValue(shapePosition);
            shapeLayer.scale.setValue(layerScale);

            // 设置父子关系，使形状图层跟随原图层
            shapeLayer.parent = selectedLayer;

            // 将新图层放在原图层之前
            shapeLayer.moveBefore(selectedLayer);

            // 保持时间范围一致
            shapeLayer.inPoint = selectedLayer.inPoint;
            shapeLayer.outPoint = selectedLayer.outPoint;

            // 取消选中状态
            shapeLayer.selected = false;
            selectedLayer.selected = false;
        }
    }
}

