            stroke.opacity.setValue(100); // 设置不透明度为 100%
            stroke.strokeWidth.setValue(parseFloat(miaobian.text)); // 设置描边粗细，从输入框读取

            // 设置形状图层的位置和缩放，保持一致
            shapeLayer.position.setValue(shapePosition);
            shapeLayer.scale.setValue(layerScale);

            // 设置父子关系，使形状图层跟随原图层
            shapeLayer.parent = selectedLayer;

            // 将新图层放在原图层之后
            shapeLayer.moveAfter(selectedLayer);

