    circulateButton.onClick = function() {
    app.beginUndoGroup("My Process");
    var comp = app.project.activeItem;
    if (comp == null) {
        alert("没有选择合成");
        app.endUndoGroup();
        return;
    }

    var selectedLayers = comp.selectedLayers;

    if (selectedLayers.length === 0) {
        alert("你还没有选定图层!!");
        app.endUndoGroup();
        return;
    }

    var numCopies = parseInt(numCopiesInput.text);  // 获取循环次数

    for (var i = 0; i < selectedLayers.length; i++) {
        var selectedLayer = selectedLayers[i];
        var framerate = 1 / comp.frameRate;
        var outpoint = selectedLayer.outPoint - framerate;
        var inpoint = selectedLayer.inPoint;

        // 添加设置时间重映射关键帧
        selectedLayer.timeRemapEnabled = true;
        selectedLayer.property("ADBE Time Remapping").addKey(inpoint); // 图层入点
        selectedLayer.property("ADBE Time Remapping").addKey(outpoint); // 图层出点
        var timeRemapProperty = selectedLayer.property("ADBE Time Remapping");
        var numKeyframes = timeRemapProperty.numKeys;
        
        // 处理3个关键帧或4个关键帧时删除其他关键帧
        if (numKeyframes == 4) {
            timeRemapProperty.removeKey(1);
            timeRemapProperty.removeKey(3);
        } else if (numKeyframes == 3) {
            var keyTime = timeRemapProperty.keyTime(1);
            var valueAtKeyframe = timeRemapProperty.valueAtTime(keyTime, true);
            if (valueAtKeyframe == 0) {
                timeRemapProperty.removeKey(3);
            }
        }

        // 设置时间重映射表达式为 loopOut()
        var keyTime = timeRemapProperty.keyTime(1);  // 获取第一个关键帧的时间
        timeRemapProperty.setValueAtTime(keyTime, timeRemapProperty.valueAtTime(keyTime, true));  // 获取关键帧的值
        timeRemapProperty.expression = "loopOut()";  // 设置循环表达式

        // 获取原始图层的时长 = 原始图层出点时间 - 原始图层入点时间
        var layerDuration = selectedLayer.outPoint - selectedLayer.inPoint;

        // 计算新的出点：原始入点 + （时长 * 循环次数）
        var newOutPoint = selectedLayer.inPoint + (layerDuration * numCopies);

        // 延长图层的持续时间
        selectedLayer.outPoint = newOutPoint;
    }

    // 如果勾选了“是否预合成”，则执行预合成操作
    if (PrecomposeCheckbox.value) {
        precomposeEachSelectedLayer();
    }
}

// 预合成操作
function precomposeEachSelectedLayer() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("Please select a composition.");
        return;
    }
    if (comp.selectedLayers.length === 0) {
        alert("Please select at least one layer.");
        return;
    }

    var selectedLayers = comp.selectedLayers;

    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        var layerIndex = layer.index;
        var minInPoint = layer.inPoint;
        var maxOutPoint = layer.outPoint;
        var duration = maxOutPoint - minInPoint;
        var baseName = layer.name; // 使用原图层名称
        var index = 1;

        //  查找一个唯一的预合成名称
        while (true) {
            var precompName = baseName + " " + index;
            var existingComp = null;
            for (var k = 1; k <= app.project.items.length; k++) {
                if (app.project.item(k) instanceof CompItem && app.project.item(k).name === precompName) {
                    existingComp = app.project.item(k);
                    break;
                }
            }
            if (!existingComp) {
                break;
            }
            index++;
        }

        // 预合成图层
        var precomp = comp.layers.precompose([layerIndex], precompName, true);
        precomp.frameRate = comp.frameRate;
        precomp.duration = duration;

        //调整预合成中图层的开始时间
        var minInPointInPrecomp = Infinity;
        for (var l = 1; l <= precomp.numLayers; l++) {
            var layerInPrecomp = precomp.layer(l);
            if (layerInPrecomp.inPoint < minInPointInPrecomp) {
                minInPointInPrecomp = layerInPrecomp.inPoint;
            }
        }
        for (var l = 1; l <= precomp.numLayers; l++) {
            var layerInPrecomp = precomp.layer(l);
            layerInPrecomp.startTime -= minInPointInPrecomp;
        }

        // 将新的预合成图层添加到主合成
        var newPrecompLayer = comp.layers.add(precomp);
        newPrecompLayer.moveBefore(comp.layer(layerIndex + 1));
        newPrecompLayer.startTime = minInPoint;

        // 如果有必要，删除原始图层
        if ((newPrecompLayer.index + 1) <= comp.numLayers) {
            comp.layer(newPrecompLayer.index + 1).remove();
        }
    }

    app.endUndoGroup();
}

