function moveMarkers(direction) {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        alert("请先选择一个合成！");
        return;
    }

    var timeOffset = comp.frameDuration * direction;
    var layers = comp.selectedLayers;
    var hasMarker = false; // 记录是否有选中的图层带有标记

    app.beginUndoGroup("Move Markers");

    // 先检查选中的图层是否有标记
    for (var l = 0; l < layers.length; l++) {
        var layer = layers[l];
        var markerProperty = layer.property("Marker");
        if (markerProperty.numKeys > 0) {
            hasMarker = true;
            break; // 只要找到一个图层有标记，就跳出循环
        }
    }

    if (hasMarker) {
        // 选定的图层有标记，移动它们的标记
        for (var l = 0; l < layers.length; l++) {
            var layer = layers[l];
            var markerProperty = layer.property("Marker");
            if (markerProperty.numKeys > 0) {
                var markers = [];
                
                for (var i = 1; i <= markerProperty.numKeys; i++) {
                    markers.push({
                        time: markerProperty.keyTime(i),
                        value: markerProperty.keyValue(i)
                    });
                }

                while (markerProperty.numKeys > 0) {
                    markerProperty.removeKey(1);
                }

                for (var j = 0; j < markers.length; j++) {
                    markerProperty.setValueAtTime(markers[j].time + timeOffset, markers[j].value);
                }
            }
        }
    } else {
        // 没有选定带有标记的图层，移动合成的标记
        var markerProperty = comp.markerProperty;
        if (markerProperty.numKeys > 0) {
            var markers = [];

            for (var i = 1; i <= markerProperty.numKeys; i++) {
                markers.push({
                    time: markerProperty.keyTime(i),
                    value: markerProperty.keyValue(i)
                });
            }

            while (markerProperty.numKeys > 0) {
                markerProperty.removeKey(1);
            }

            for (var j = 0; j < markers.length; j++) {
                markerProperty.setValueAtTime(markers[j].time + timeOffset, markers[j].value);
            }
        }
    }

    app.endUndoGroup();
}

function alignFirstMarker() {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        alert("请先选择一个合成！");
        return;
    }

    var layers = comp.selectedLayers;
    var currentTime = comp.time;
    var hasMarker = false; // 记录是否有选中的图层带有标记
    app.beginUndoGroup("Align First Marker");

    // 遍历选中的图层，查找是否有标记
    for (var l = 0; l < layers.length; l++) {
        var layer = layers[l];
        var markerProperty = layer.property("Marker");
        if (markerProperty.numKeys > 0) {
            hasMarker = true;
            break; // 只要有一个图层有标记，就跳出循环
        }
    }

    if (hasMarker) {
        // 偏移选定图层的标记
        for (var l = 0; l < layers.length; l++) {
            var layer = layers[l];
            var markerProperty = layer.property("Marker");
            if (markerProperty.numKeys > 0) {
                var markers = [];
                for (var i = 1; i <= markerProperty.numKeys; i++) {
                    markers.push({
                        time: markerProperty.keyTime(i),
                        value: markerProperty.keyValue(i)
                    });
                }
                var timeOffset = currentTime - markers[0].time;
                while (markerProperty.numKeys > 0) {
                    markerProperty.removeKey(1);
                }
                for (var j = 0; j < markers.length; j++) {
                    markerProperty.setValueAtTime(markers[j].time + timeOffset, markers[j].value);
                }
            }
        }
    } else {
        // 没有选定带有标记的图层，则偏移合成标记
        var markerProperty = comp.markerProperty;
        if (markerProperty.numKeys > 0) {
            var markers = [];
            for (var i = 1; i <= markerProperty.numKeys; i++) {
                markers.push({
                    time: markerProperty.keyTime(i),
                    value: markerProperty.keyValue(i)
                });
            }
            var timeOffset = currentTime - markers[0].time;
            while (markerProperty.numKeys > 0) {
                markerProperty.removeKey(1);
            }
            for (var j = 0; j < markers.length; j++) {
                markerProperty.setValueAtTime(markers[j].time + timeOffset, markers[j].value);
            }
        }
    }

    app.endUndoGroup();
}

