var tunnel = buttonRow2.add("panel", undefined, "隧道");
tunnel.orientation = "row";
tunnel.spacing = 1;
tunnel.margins = 5;
// 行1：复制次数
var row = tunnel.add("group");
row.orientation = "column";
row.alignChildren = ["left","center"];
row.spacing = 1;
var tunnelcopiesInput = row.add("edittext", [0,0,40,20], "5");
tunnelcopiesInput.helpTip = "图层数量";
var tunneloffsetInput = row.add("edittext", [0,0,40,20], "500");
tunneloffsetInput.helpTip = "Z轴偏移量";
var tunnelbtn = tunnel.add("button", undefined, "执行", {name:"ok"});
tunnelbtn.preferredSize = [40, 40];

tunnelbtn.onClick = function(){
    var copies = parseInt(tunnelcopiesInput.text-1, 10);
    if (isNaN(copies) || copies < 0) copies = 1;

    var zOffsetPer = parseFloat(tunneloffsetInput.text);
    if (isNaN(zOffsetPer)) zOffsetPer = 0;

    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var selLayers = comp.selectedLayers;
    if (!selLayers || selLayers.length === 0) return;

    app.beginUndoGroup("开启3D并批量复制");

    try {
        var originals = selLayers.slice();
        var allLayers = [];
        var earliestIn = comp.duration;
        var latestOut = 0;

        for (var i=0; i<originals.length; i++){
            var lyr = originals[i];
            allLayers.push(lyr);
            try { lyr.threeDLayer = true; } catch(e){}

            if (lyr.inPoint < earliestIn) earliestIn = lyr.inPoint;
            if (lyr.outPoint > latestOut) latestOut = lyr.outPoint;

            // 获取原始层的Z轴位置
            var baseZ = 0;
            try {
                var pos = lyr.property("ADBE Transform Group").property("ADBE Position");
                var cur = pos.numKeys === 0 ? pos.value : pos.valueAtTime(comp.time, false);
                baseZ = (cur.length > 2) ? cur[2] : 0;
            } catch(e){}

            // 上一个创建的层（用于 moveAfter 排序）
            var lastCreated = lyr;

            for (var c=0; c<copies; c++){
                var dup = lyr.duplicate();
                allLayers.push(dup);
                try { dup.threeDLayer = true; } catch(e){}

                // 线性Z偏移
                if (zOffsetPer !== 0){
                    try {
                        var pos = dup.property("ADBE Transform Group").property("ADBE Position");
                        var cur = pos.numKeys === 0 ? pos.value : pos.valueAtTime(comp.time, false);
                        cur = [cur[0], cur[1], baseZ + zOffsetPer * (c+1)];
                        pos.setValue(cur);
                    } catch(e){}
                }

                // ✅ 按顺序堆叠
                dup.moveAfter(lastCreated);
                lastCreated = dup;

                if (dup.inPoint < earliestIn) earliestIn = dup.inPoint;
                if (dup.outPoint > latestOut) latestOut = dup.outPoint;
            }
        }

        // 清空所有选中状态
        for (var i = 1; i <= comp.numLayers; i++) {
            comp.layer(i).selected = false;
        }

        // 创建控制空对象
        var nullLayer = comp.layers.addNull();
        nullLayer.name = "控制空对象";
        nullLayer.threeDLayer = true;
        nullLayer.moveToBeginning();
        nullLayer.inPoint = earliestIn;
        nullLayer.outPoint = latestOut;

        // 设置父链接
        for (var i=0; i<allLayers.length; i++){
            try { allLayers[i].parent = nullLayer; } catch(e){}
        }

        nullLayer.selected = true;

    } catch(e) {
        // 忽略错误
    } finally {
        app.endUndoGroup();
    }
};

