function setTextD(layer) {
    try {
        var textProp = layer.property("Source Text");
        var textDocument = textProp.value;
        textDocument.fontSize = 100;  // 字体默认大小
        textProp.setValue(textDocument);
    } catch (err) {
        alert("设置文本失败: " + err.toString());
    }
}

function getTextRangeType(index) {
    var types = [1, 4, 2];
    return types[index] || 1;
}

textMasks.onClick = function () {
    try {
        app.beginUndoGroup("文字绑定蒙版");
        var comp = app.project.activeItem;
        if (comp && comp instanceof CompItem) {
            var selectedLayers = comp.selectedLayers;
            if (selectedLayers.length > 0) {
                for (var i = 0; i < selectedLayers.length; i++) {
                    if (!(selectedLayers[i] instanceof TextLayer)) {
                        continue;
                    }
                    var layer = selectedLayers[i];
                    setTextD(layer);

                    if (layer.mask.numProperties == 0) {
                        var mask = layer.Masks.addProperty("Mask");
                        mask.name = "Mask 1";
                        var maskShape = mask.property("ADBE Mask Shape").value;
                        var maskPath = maskShape.vertices;
                        var textLength = layer.property("Source Text").value.text.length;
                        var newMaskPath = [];
                        for (var j = 0; j < textLength; j++) {
                            newMaskPath.push([0, 0]);
                            newMaskPath[j][0] += (100 * j);
                        }
                        maskShape.vertices = newMaskPath;
                        maskShape.closed = false;
                        mask.property("ADBE Mask Shape").setValue(maskShape);
                    }

                    var animator1 = layer.property("ADBE Text Properties").property("ADBE Text Animators").addProperty("ADBE Text Animator");
                    animator1.name = "位置";
                    var selector1 = animator1.property("ADBE Text Selectors").addProperty("ADBE Text Expressible Selector");
                    selector1.property("ADBE Text Range Type2").setValue(getTextRangeType(dropdown.selection.index));
                    var selector1Amount = selector1.property("ADBE Text Expressible Amount");
                    selector1Amount.expression = "pt = mask(1).maskPath.points();\nline = Math.min(textIndex - 1, pt.length - 1);\nx = linear(pt[line][0], -width, width, -100, 100);\ny = linear(pt[line][1], -height, height, -100, 100);\n[x, y];";

                    var posProp = animator1.property("ADBE Text Animator Properties").addProperty("ADBE Text Position 3D");
                    posProp.expression = "[width, height];";

                    var animator2 = layer.property("ADBE Text Properties").property("ADBE Text Animators").addProperty("ADBE Text Animator");
                    animator2.name = "缩放";
                    var selector2 = animator2.property("ADBE Text Selectors").addProperty("ADBE Text Expressible Selector");
                    selector2.property("ADBE Text Range Type2").setValue(getTextRangeType(dropdown.selection.index));
                    var selector2Amount = selector2.property("ADBE Text Expressible Amount");
                    selector2Amount.expression = "p = mask(1).maskPath;\npt = p.points();\nline = Math.min(textIndex - 1, pt.length - 1);\nx1 = p.outTangents()[line][0];\ny1 = p.outTangents()[line][1];\noutLength = Math.sqrt(x1*x1 + y1*y1);\nx2 = p.inTangents()[line][0];\ny2 = p.inTangents()[line][1];\ninLength = Math.sqrt(x2*x2 + y2*y2);\ndisLength = Math.max(outLength, inLength);\ns = linear(disLength, -1000, 1000, -100, 100);\n[s, s];";
                    var scaleProp = animator2.property("ADBE Text Animator Properties").addProperty("ADBE Text Scale 3D");
                    scaleProp.expression = "[2000, 2000];";

                    var animator3 = layer.property("ADBE Text Properties").property("ADBE Text Animators").addProperty("ADBE Text Animator");
                    animator3.name = "旋转";
                    var selector3 = animator3.property("ADBE Text Selectors").addProperty("ADBE Text Expressible Selector");
                    selector3.property("ADBE Text Range Type2").setValue(getTextRangeType(dropdown.selection.index));
                    var selector3Amount = selector3.property("ADBE Text Expressible Amount");
                    selector3Amount.expression = "p = mask(1).maskPath;\npt = p.points();\nline = Math.min(textIndex - 1, pt.length - 1);\nlastpoint = (line==pt.length-1);x = lastpoint ? p.inTangents()[line][0] : p.outTangents()[line][0];\ny = lastpoint ? p.inTangents()[line][1] : p.outTangents()[line][1];\noutAngle = Math.atan2(y, x) * 180 / Math.PI;\noutAngle = (lastpoint && x!=0 && y!=0) ? outAngle-180 : outAngle \na = linear(outAngle, -360, 360, -100, 100);\na;";

                    var rotaProp = animator3.property("ADBE Text Animator Properties").addProperty("ADBE Text Rotation");
                    rotaProp.expression = "360;";
                }
            } else {
                alert("请选中至少一个文字层");
            }
        } else {
            alert("当前没有活动的合成");
        }
        app.endUndoGroup();
    } catch (err) {
        app.endUndoGroup();
        alert("错误\n" + err.toString());
    }
};
var MaskDecomposition = Panel1.add("button",[0,0,120,25], "蒙版分解");

MaskDecomposition.onClick = function() {
app.beginUndoGroup("复制图层并按蒙版保留");
var comp = app.project.activeItem;
if (comp && comp instanceof CompItem) {
    if (!comp.hideShyLayers) { // 只有在未隐藏的情况下才执行
        comp.hideShyLayers = true;
    }
    var newLayers = []; // 用于存储新复制的图层
    var selectedLayers = comp.selectedLayers; // 存储原选定图层
    for (var i = 0; i < comp.selectedLayers.length; i++) {
        var layer = comp.selectedLayers[i];
        // 获取图层的蒙版数量
        var maskCount = layer.mask ? layer.mask.numProperties : 0;
        // 根据蒙版数量复制图层
        for (var j = 0; j < maskCount; j++) {
            var newLayer = layer.duplicate();  // 复制图层
            // 删除新图层的所有蒙版
            for (var m = newLayer.mask.numProperties; m >= 1; m--) {
                try {
                    // 只保留指定的蒙版
                    if (m !== j + 1) {
                        newLayer.mask.property(m).remove();
                    }
                } catch (e) {
                    // 如果删除蒙版时遇到问题，跳过
                }
            }
            // 将新图层移动到原图层之前
            newLayer.moveBefore(layer);
            // 将新图层加入到新图层数组
            newLayers.push(newLayer);
            // 修改新图层的所有蒙版模式为 ADD
                for (var m = 1; m <= newLayer.mask.numProperties; m++) {
                    var mask = newLayer.mask.property(m);
                    if (mask) {
                        mask.maskMode = MaskMode.ADD;
                    }
                }
            }
        }
    // 选择所有新图层
    for (var k = 0; k < newLayers.length; k++) {
        newLayers[k].selected = true;
        app.executeCommand(10312); // 锚点居中命令
        newLayers[k].selected = false;
    }
    // 开启原选定图层的 shy 属性
    for (var i = 0; i < selectedLayers.length; i++) {
        selectedLayers[i].shy = true;
        selectedLayers[i].enabled = false; // 设置图层不可见
    }
    app.endUndoGroup();
} else {
    alert("请选中至少一个图层");
    }
}

