function Rounded_corners_mask() {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        alert("请选择一个合成！");
        return;
    }
    if (comp.selectedLayers.length === 0) {
        alert("请选择一个图层！");
        return;
    }
    var layer = comp.selectedLayers[0];
    // 检查选中图层是否有蒙版，没有则创建一个
    var mask;
    if (layer.mask.numProperties === 0) {
        var width = layer.width;
        var height = layer.height;
        mask = layer.Masks.addProperty("ADBE Mask Atom");
        var vertices = [
            [0, 0],
            [width, 0],
            [width, height],
            [0, height]
        ];
        var inTangents = [[0,0],[0,0],[0,0],[0,0]];
        var outTangents = [[0,0],[0,0],[0,0],[0,0]];
        var maskShape = new Shape();
        maskShape.vertices = vertices;
        maskShape.inTangents = inTangents;
        maskShape.outTangents = outTangents;
        maskShape.closed = true;
        mask.property("maskPath").setValue(maskShape);
    } else {
        mask = layer.mask(1);
    }
    // 添加滑块效果（TL/TR/BR/BL）
    function addCtrl(name, def) {
        var ef = layer.property("ADBE Effect Parade").property(name);
        if (!ef) {
            ef = layer.property("ADBE Effect Parade").addProperty("ADBE Slider Control");
            ef.name = name;
            ef.property("ADBE Slider Control-0001").setValue(def);
        }
        return ef;
    }
    var TL = addCtrl("左上", 50);
    var TR = addCtrl("右上", 50);
    var BL = addCtrl("左下", 50);
    var BR = addCtrl("右下", 50);
    // 获取蒙版点位（二维数组）
    var pts = mask.property("maskPath").value.vertices;
    // 自动识别四角
    var TL_pt, TR_pt, BR_pt, BL_pt;
    for (var i = 0; i < pts.length; i++) {
        var p = pts[i];
        if (!TL_pt || (p[0] <= TL_pt[0] && p[1] <= TL_pt[1])) TL_pt = p; // 左上
        if (!TR_pt || (p[0] >= TR_pt[0] && p[1] <= TR_pt[1])) TR_pt = p; // 右上
        if (!BR_pt || (p[0] >= BR_pt[0] && p[1] >= BR_pt[1])) BR_pt = p; // 右下
        if (!BL_pt || (p[0] <= BL_pt[0] && p[1] >= BL_pt[1])) BL_pt = p; // 左下
    }
    var originalPts_sorted = [TL_pt, TR_pt, BR_pt, BL_pt];
    // 写入表达式（四角切角方向修正）
    var expr =
"TL = effect(\"左上\")(\"滑块\");\n" +
"TR = effect(\"右上\")(\"滑块\");\n" +
"BL = effect(\"左下\")(\"滑块\");\n" +
"BR = effect(\"右下\")(\"滑块\");\n" +
"pts = " + JSON.stringify(originalPts_sorted) + ";\n" +
"xs = pts.map(p=>p[0]);\n" +
"ys = pts.map(p=>p[1]);\n" +
"w = Math.max.apply(null,xs)-Math.min.apply(null,xs);\n" +
"h = Math.max.apply(null,ys)-Math.min.apply(null,ys);\n" +
"lim = Math.min(w,h)/2;\n" +
"TL = Math.min(TL,lim);\nTR = Math.min(TR,lim);\nBR = Math.min(BR,lim);\nBL = Math.min(BL,lim);\n" +
"k=0.55228475;\n" +
"p=[\n" +
"  [pts[0][0]+TL, pts[0][1]],\n" +
"  [pts[1][0]-TR, pts[1][1]],\n" +
"  [pts[1][0], pts[1][1]+TR],\n" +
"  [pts[2][0], pts[2][1]-BR],\n" +
"  [pts[2][0]-BR, pts[2][1]],\n" +
"  [pts[3][0]+BL, pts[3][1]],\n" +
"  [pts[3][0], pts[3][1]-BL],\n" +
"  [pts[0][0], pts[0][1]+TL]\n" +
"];\n" +
"inT=[ [-k*TL,0], [-k*TR,0], [0,-k*TR], [0,-k*BR], [k*BR,0], [k*BL,0], [0,k*BL], [0,k*TL] ];\n" +
"outT=[ [k*TL,0], [k*TR,0], [0,k*TR], [0,k*BR], [-k*BR,0], [-k*BL,0], [0,-k*BL], [0,-k*TL] ];\n" +
"createPath(p,inT,outT,true);";
    mask.property("maskPath").expression = expr;
};

function IndieCorners(){
var comp = app.project.activeItem;
if(!(comp instanceof CompItem)) return;
// 创建Shape层
var shapeLayer = comp.layers.addShape();
shapeLayer.name = "形状图层(圆角)";
var contents = shapeLayer.property("ADBE Root Vectors Group");
// Group
var group = contents.addProperty("ADBE Vector Group");
group.name = "Box";
var vectors = group.property("ADBE Vectors Group");
// Path
var pathGroup = vectors.addProperty("ADBE Vector Shape - Group");
// Fill
var fill = vectors.addProperty("ADBE Vector Graphic - Fill");
fill.property("ADBE Vector Fill Color").setValue([1,1,1]);
// 重新获取 Path 属性（关键）
var pathProp = shapeLayer
.property("ADBE Root Vectors Group")
.property("Box")
.property("ADBE Vectors Group")
.property(1)
.property("ADBE Vector Shape");
// 初始 Shape
var sh = new Shape();
sh.vertices = [[0,0],[100,0],[100,100],[0,100]];
sh.inTangents = [[0,0],[0,0],[0,0],[0,0]];
sh.outTangents = [[0,0],[0,0],[0,0],[0,0]];
sh.closed = true;
pathProp.setValue(sh);
// 控制器
var fx = shapeLayer.property("ADBE Effect Parade");
function slider(name,val){
var s = fx.addProperty("ADBE Slider Control");
s.name = name;
if(val!==undefined) s.property(1).setValue(val);
}
slider("宽",800);
slider("高",400);
slider("左上",0);
slider("右上",0);
slider("左下",0);
slider("右下",0);
// 表达式
var exp =
'w=effect("宽")(1);\
h=effect("高")(1);\
m=Math.min(w/2,h/2);\
tl=clamp(effect("左上")(1),0,m);\
tr=clamp(effect("右上")(1),0,m);\
br=clamp(effect("右下")(1),0,m);\
bl=clamp(effect("左下")(1),0,m);\
t=0.5519;\
createPath(\
[[0,tl],[tl,0],[w-tr,0],[w,tr],[w,h-br],[w-br,h],[bl,h],[0,h-bl]],\
[[0,0],[-tl*t,0],[0,0],[0,-tr*t],[0,0],[br*t,0],[0,0],[0,bl*t]],\
[[0,-tl*t],[0,0],[tr*t,0],[0,0],[0,br*t],[0,0],[-bl*t,0],[0,0]],\
true);';
// 设置表达式
pathProp.expression = exp;
app.executeCommand(10312);
var center = [comp.width/2, comp.height/2];
if (shapeLayer.threeDLayer){
    shapeLayer.property("ADBE Transform Group")
        .property("ADBE Position")
        .setValue([center[0], center[1], 0]);
}else{
    shapeLayer.property("ADBE Transform Group")
        .property("ADBE Position")
        .setValue(center);
}
}


