function adjustCompDuration(increase) {
    var comp = app.project.activeItem; // 获取当前活动的合成
    if (comp && comp instanceof CompItem) {
        var currentDuration = comp.duration;  // 当前合成的时长
        var frameRate = comp.frameRate; // 当前帧速率
        
        // 根据increase参数决定是否增加或减少
        var newDuration = increase ? currentDuration + (1 / frameRate) : currentDuration - (1 / frameRate);
        comp.duration = newDuration;
    }
}

CurrentTime.onClick = function() {
    // 获取当前合成
    app.beginUndoGroup("工作区");
    var comp = app.project.activeItem;

    if (comp instanceof CompItem) {
        // 检查是否有选定的图层
        var selectedLayers = comp.selectedLayers;

        if (selectedLayers.length > 0) {
            // 初始化工作区域的开始时间和结束时间
            var workAreaStart = selectedLayers[0].inPoint;
            var workAreaEnd = selectedLayers[0].outPoint;

            // 遍历所有选定的图层，计算最早的入点和最晚的出点
            for (var i = 1; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                // 更新工作区域的开始时间和结束时间
                workAreaStart = Math.min(workAreaStart, layer.inPoint);
                workAreaEnd = Math.max(workAreaEnd, layer.outPoint);
            }

            // 设置工作区域的开始和结束时间
            comp.workAreaStart = workAreaStart;
            comp.workAreaDuration = workAreaEnd - workAreaStart;
        } else {
            alert("请选中一个图层！");
        }
    } else {
        alert("请确保你在一个合成中！");
    }
app.endUndoGroup();
};

