// 正常预合成
function SinglePrecomp(precompName) {
    app.beginUndoGroup("单预合成");

    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请选择当前合成。");
        return;
    }

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请先选择图层。");
        return;
    }

    // ✅ 取第一个选中图层的实际帧速率（而非素材文件帧率）
    var sourceFrameRate = comp.frameRate;
    var firstLayer = selectedLayers[0];
    if (firstLayer.source && firstLayer.source.frameRate) {
        sourceFrameRate = firstLayer.source.frameRate;
    } else if (firstLayer.source && firstLayer.source.mainSource && firstLayer.source.mainSource.frameRate) {
        // 兼容旧素材导入类型（如图像序列）
        sourceFrameRate = firstLayer.source.mainSource.frameRate;
    }

    // 计算所有图层的 in / out 范围
    var minInPoint = selectedLayers[0].inPoint;
    var maxOutPoint = selectedLayers[0].outPoint;
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        if (layer.inPoint < minInPoint) minInPoint = layer.inPoint;
        if (layer.outPoint > maxOutPoint) maxOutPoint = layer.outPoint;
    }
    var duration = maxOutPoint - minInPoint;

    // 创建唯一合成名
    var baseName = precompName || "预合成";
    var index = 1;
    var finalName = baseName;
    while (true) {
        var exists = false;
        for (var i = 1; i <= app.project.numItems; i++) {
            if (app.project.item(i) instanceof CompItem && app.project.item(i).name === finalName) {
                exists = true;
                break;
            }
        }
        if (!exists) break;
        index++;
        finalName = baseName + " " + index;
    }

    // ✅ 新建预合成并使用图层帧速率
    var precomp = app.project.items.addComp(
        finalName,
        comp.width,
        comp.height,
        comp.pixelAspect,
        duration,
        sourceFrameRate
    );

    // 将选中图层复制到新预合成
    for (var i = 0; i < selectedLayers.length; i++) {
        selectedLayers[i].copyToComp(precomp);
    }

    // 在原合成中添加预合成图层
    var newLayer = comp.layers.add(precomp);
    newLayer.startTime = minInPoint;

    // 删除原选中图层
    for (var i = 0; i < selectedLayers.length; i++) {
        selectedLayers[i].remove();
    }

    app.endUndoGroup();
}


// 链接对象预合成
function SingleParentPrecomp() {
    function precomposeSelectedLayersAndParents(precompName) {
        var comp = app.project.activeItem;
        if (!(comp && comp instanceof CompItem)) {
            alert("请选择当前合成。");
            return;
        }
        if (comp.selectedLayers.length === 0) {
            return;
        }
        var selectedLayers = comp.selectedLayers;
        var layerIndices = [];
        var processedLayers = {};
        var topmostLayerIndex = comp.numLayers;

        function addLayerAndParents(layer) {
            if (!layer || processedLayers[layer.index]) {
                return;
            }
            layerIndices.push(layer.index);
            processedLayers[layer.index] = true;
            if (layer.index < topmostLayerIndex) {
                topmostLayerIndex = layer.index;
            }
            if (layer.parent) {
                addLayerAndParents(layer.parent);
            }
        }
        for (var i = 0; i < selectedLayers.length; i++) {
            addLayerAndParents(selectedLayers[i]);
        }
        var minInPoint = comp.layer(layerIndices[0]).inPoint;
        var maxOutPoint = comp.layer(layerIndices[0]).outPoint;
        for (var i = 0; i < layerIndices.length; i++) {
            var layer = comp.layer(layerIndices[i]);
            if (layer.inPoint < minInPoint) {
                minInPoint = layer.inPoint;
            }
            if (layer.outPoint > maxOutPoint) {
                maxOutPoint = layer.outPoint;
            }
        }
        var duration = maxOutPoint - minInPoint;
        var baseName = precompName || "预合成";
        var index = 1;
        while (true) {
            var finalName = baseName + " " + index;
            var existingComp = null;
            for (var i = 1; i <= app.project.items.length; i++) {
                if (app.project.item(i) instanceof CompItem && app.project.item(i).name === finalName) {
                    existingComp = app.project.item(i);
                    break;
                }
            }
            if (!existingComp) {
                break;
            }
            index++;
        }

        var precomp = comp.layers.precompose(layerIndices, finalName, true);
        precomp.frameRate = comp.frameRate;
        precomp.duration = duration;

        var minInPointInPrecomp = Infinity;
        for (var j = 1; j <= precomp.numLayers; j++) {
            var layerInPrecomp = precomp.layer(j);
            if (layerInPrecomp.inPoint < minInPointInPrecomp) {
                minInPointInPrecomp = layerInPrecomp.inPoint;
            }
        }
        for (var j = 1; j <= precomp.numLayers; j++) {
            var layerInPrecomp = precomp.layer(j);
            layerInPrecomp.startTime -= minInPointInPrecomp;
        }
        var newPrecompLayer = comp.layers.add(precomp);
        newPrecompLayer.moveBefore(comp.layer(topmostLayerIndex + 1));
        newPrecompLayer.startTime = minInPoint;
        if ((newPrecompLayer.index + 1) <= comp.numLayers) {
            comp.layer(newPrecompLayer.index + 1).remove();
        }
    }
    precomposeSelectedLayersAndParents(edt_preComp.text); // 传入输入框的文本作为预合成名称
}

