            // 如果自己是需要跳过的文件夹
            if (item instanceof FolderItem && arrayIndexOf(skipFolders, item.name) !== -1) return true;
            // 如果它的父级是需要跳过的文件夹
            if (item.parentFolder && arrayIndexOf(skipFolders, item.parentFolder.name) !== -1) return true;
