function collectAssets(replaceAssets) {
    var proj = app.project;

    var rootFolder = Folder.selectDialog("请选择保存素材和项目文件的总文件夹");
    if (!rootFolder) return false;

    var folderName = prompt("请输入保存总文件夹的名称", "");
    if (!folderName) return false;

    var totalFolder = new Folder(rootFolder.fsName + "/" + folderName);
    if (!totalFolder.exists) totalFolder.create();

    var assets = [];

    for (var i = 1; i <= proj.numItems; i++) {
        var item = proj.item(i);
        if (item instanceof FootageItem && item.file) {
            assets.push(item);
        }
    }

    var assetMap = copyAssetsToFolder(assets, totalFolder);

    if (replaceAssets) {
        replaceProjectAssets(assetMap);
    }

    saveProject(proj, totalFolder, folderName);

    alert("完成！");
    return true;
}


// ================== 复制素材 ==================
function copyAssetsToFolder(assets, targetFolder) {
    var assetMap = {};
    var copiedFolders = {};

    for (var i = 0; i < assets.length; i++) {
        var asset = assets[i];
        if (!(asset instanceof FootageItem) || !asset.file) continue;

        var sourceFile = asset.file;
        var sourceFolder = sourceFile.parent;

        var isSequence = isImageSequence(sourceFile);

        if (isSequence) {
            // ===== 图片序列：复制整个文件夹 =====
            var destFolder = new Folder(targetFolder.fsName + "/" + sourceFolder.name);

            if (!copiedFolders[sourceFolder.fsName]) {
                copyFolder(sourceFolder, destFolder);
                copiedFolders[sourceFolder.fsName] = true;
            }

            // 👉 只记录第一帧路径（关键）
            var firstFile = getFirstFrame(sourceFile);
            if (firstFile) {
                assetMap[sourceFile.fsName] = new File(destFolder.fsName + "/" + firstFile.name).fsName;
            }

        } else {
            // ===== 普通素材 =====
            var destFile = new File(targetFolder.fsName + "/" + sourceFile.name);

            if (!destFile.exists) {
                sourceFile.copy(destFile);
            }

            assetMap[sourceFile.fsName] = destFile.fsName;
        }
    }

    return assetMap;
}


// ================== 判断图片序列 ==================
function isImageSequence(file) {
    var name = file.name;

    var match = name.match(/^(.*?)(\d+)(\.\w+)$/);
    if (!match) return false;

    var prefix = match[1];
    var ext = match[3];

    var folder = file.parent;
    var files = folder.getFiles();

    var count = 0;

    for (var i = 0; i < files.length; i++) {
        var f = files[i];
        if (!(f instanceof File)) continue;

        var m = f.name.match(/^(.*?)(\d+)(\.\w+)$/);

        if (m && m[1] === prefix && m[3] === ext) {
            count++;
        }

        if (count >= 3) return true;
    }

    return false;
}


// ================== 获取序列第一帧 ==================
function getFirstFrame(file) {
    var folder = file.parent;
    var files = folder.getFiles();
    var seq = [];

    var match = file.name.match(/^(.*?)(\d+)(\.\w+)$/);
    if (!match) return file;

    var prefix = match[1];
    var ext = match[3];

    for (var i = 0; i < files.length; i++) {
        var f = files[i];
        if (!(f instanceof File)) continue;

        var m = f.name.match(/^(.*?)(\d+)(\.\w+)$/);

        if (m && m[1] === prefix && m[3] === ext) {
            seq.push(f);
        }
    }

    // 按文件名排序
    seq.sort(function(a, b) {
        return a.name > b.name ? 1 : -1;
    });

    return seq.length > 0 ? seq[0] : file;
}


// ================== 复制文件夹 ==================
function copyFolder(srcFolder, dstFolder) {
    if (!dstFolder.exists) dstFolder.create();

    var files = srcFolder.getFiles();

    for (var i = 0; i < files.length; i++) {
        var file = files[i];

        if (file instanceof Folder) {
            copyFolder(file, new Folder(dstFolder.fsName + "/" + file.name));
        } else {
            file.copy(new File(dstFolder.fsName + "/" + file.name));
        }
    }
}


// ================== 替换素材（关键优化） ==================
function replaceProjectAssets(assetMap) {
    var proj = app.project;

    for (var i = 1; i <= proj.numItems; i++) {
        var item = proj.item(i);

        if (!(item instanceof FootageItem) || !item.file) continue;

        var file = item.file;
        var newPath = assetMap[file.fsName];

        if (!newPath) continue;

        // ✅ 判断是否为图片序列
        var isSequence = isImageSequence(file);

        if (isSequence) {
            // ❗关键：序列不 replace，避免变单帧
            continue;
        }

        // ✅ 普通素材才替换
        try {
            item.replace(new File(newPath));
        } catch (e) {
            $.writeln("替换失败: " + file.fsName);
        }
    }
}

// ================== 保存项目 ==================
function saveProject(proj, targetFolder, folderName) {
    var projectFile = new File(targetFolder.fsName + "/" + folderName + ".aep");

    try {
        proj.save(projectFile);
    } catch (e) {
        alert("保存失败: " + e.toString());
    }
}

function Replace() {
    var proj = app.project;
    if (!proj) {
        alert("没有工程");
        return;
    }
    if (!proj.file) {
        alert("请先保存工程");
        return;
    }
    var rootFolder = proj.file.parent;
    // 获取工程目录下所有文件夹
    function getAllFolders(folder, list) {
        var items = folder.getFiles();
        for (var i = 0; i < items.length; i++) {
            var f = items[i];
            if (f instanceof Folder) {
                list.push(f);
                getAllFolders(f, list);
            }
        }
    }
    var allFolders = [];
    getAllFolders(rootFolder, allFolders);
    // 判断是否为序列
    function isSequence(item) {
        if (!(item instanceof FootageItem)) return false;
        if (!item.file) return false;

        try {
            return item.mainSource && item.mainSource.isStill === false;
        } catch (e) {
            return false;
        }
    }
    // 获取序列所在文件夹名
    function getSequenceFolderName(file) {
        if (!file) return null;
        var parentFolder = file.parent;
        return parentFolder ? parentFolder.name : null;
    }
    // 查找同名文件夹
    function findFolderByName(name) {
        for (var i = 0; i < allFolders.length; i++) {
            if (allFolders[i].name === name) {
                return allFolders[i];
            }
        }
        return null;
    }
    // 获取序列首帧
    function getFirstFrame(folder) {
        var files = folder.getFiles();
        var images = [];
        for (var i = 0; i < files.length; i++) {
            if (files[i] instanceof File) {
                images.push(files[i]);
            }
        }

        if (images.length === 0) return null;

        images.sort(function (a, b) {
            return a.name.localeCompare(b.name);
        });

        return images[0];
    }
    // ✅ 缓存避免重复导入
    var importCache = {};
    function getSequenceFromFolder(folder) {
        if (importCache[folder.name]) {
            return importCache[folder.name];
        }
        var firstFrame = getFirstFrame(folder);
        if (!firstFrame) return null;
        var importOptions = new ImportOptions(firstFrame);
        importOptions.sequence = true;
        var footage = proj.importFile(importOptions);
        importCache[folder.name] = footage;
        return footage;
    }
    var count = 0;
    // 遍历所有合成
    for (var i = 1; i <= proj.numItems; i++) {
        var comp = proj.item(i);
        if (!(comp instanceof CompItem)) continue;
        // 遍历图层
        for (var j = 1; j <= comp.numLayers; j++) {
            var layer = comp.layer(j);
            if (!(layer instanceof AVLayer)) continue;
            if (!layer.source) continue;
            var source = layer.source;
            if (!isSequence(source)) continue;
            try {
                var oldFile = source.file;
                if (!oldFile) continue;
                var folderName = getSequenceFolderName(oldFile);
                if (!folderName) continue;
                var newFolder = findFolderByName(folderName);
                if (!newFolder) continue;
                var newFootage = getSequenceFromFolder(newFolder);
                if (!newFootage) continue;
                // ✅ 替换图层素材（关键）
                layer.replaceSource(newFootage, false);
                count++;
            } catch (e) {
                $.writeln("错误: " + e.toString());
            }
        }
    }
};

function Delete_non_catalog_footage() {
    var proj = app.project;
    if (!proj || !proj.file) {
        alert("请先保存工程文件（.aep）");
        return;
    }
    var rootPath = proj.file.parent.fsName;
    // 判断路径是否在工程目录下
    function isInProjectFolder(filePath, rootPath) {
        return filePath.indexOf(rootPath) === 0;
    }
    // 从后往前遍历，避免删除时索引错乱
    for (var i = proj.numItems; i >= 1; i--) {
        var item = proj.item(i);
        // 只处理素材
        if (item instanceof FootageItem && item.file) {
            var filePath = item.file.fsName;
            // 如果不在工程目录 → 删除
            if (!isInProjectFolder(filePath, rootPath)) {
                try {
                    item.remove();
                } catch (e) {}
            }
        }
    }
};

