runshakeBtn.onClick = function () {

    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;
    if (!layers || layers.length === 0) return;

    app.beginUndoGroup("Shake With 3D Toggle");

    var states = [];
    var hasAny3D = false;

    // 记录状态 + 统一关闭3D
    for (var i = 0; i < layers.length; i++) {
        var ly = layers[i];
        states.push({
            layer: ly,
            is3D: ly.threeDLayer
        });

        if (ly.threeDLayer) {
            hasAny3D = true;
            ly.threeDLayer = false;
        }
    }

    SHAKE();

    // 如果之前有3D图层 → 恢复 + 执行Z轴
    if (hasAny3D) {
        for (var j = 0; j < states.length; j++) {
            if (states[j].is3D) {
                states[j].layer.threeDLayer = true;
            }
        }
        Z_axis();
    }

    app.endUndoGroup();
};


// ===================== 主函数 =====================
function SHAKE() {

    var comp = app.project.activeItem;
    var layer = comp ? comp.selectedLayers[0] : null;
    if (!layer) return;

    // ===================== UI驱动参数 =====================
    var kCount = parseInt(KEYDropdown.selection.text);

    var posMin, posMax;
    var rotMin, rotMax;

    switch (posDropdown.selection.text) {
        case "小":
            posMin = 5; posMax = 20;
            rotMin = 2; rotMax = 3;
            break;
        case "中":
            posMin = 10; posMax = 50;
            rotMin = 2; rotMax = 5;
            break;
        case "大":
            posMin = 30; posMax = 150;
            rotMin = 2; rotMax = 8;
            break;
    }

    var frameRate = comp.frameRate;

    // ===================== 🔥 帧率自适配（核心修改） =====================
    var scale = frameRate / 30;

    var minInterval = Math.round(13 * scale);
    var maxInterval = Math.round(15 * scale);

    var tens = 33;
    var preFrameOffset = 2;
    var offsetFrames = Math.max(1, Math.round(1 * scale));

    // ================= 检查是否已有关键帧 =================
    layer.transform.position.dimensionsSeparated = true;

    var hasKeys =
        layer.transform.rotation.numKeys > 0 ||
        layer.transform.xPosition.numKeys > 0 ||
        layer.transform.yPosition.numKeys > 0;

    if (hasKeys) {
        alert("⚠️ 该图层已存在关键帧\n请清除或创建空对象后再运行！");
        return;
    }

    var layerInPoint = layer.inPoint;
    var startTime = layerInPoint - (preFrameOffset / frameRate);

    // ⭐ 旋转
    var scale = frameRate / 30;
// 12帧基准 → 自动缩放
var rotStep = Math.round(12 * scale);
var rotCount = kCount + 1;
applyRotationSway(layer.transform.rotation, rotMin, rotMax, rotStep, rotCount);

    // ⭐ 位置
    applySway(layer.transform.xPosition, posMin, posMax);
    applySway(layer.transform.yPosition, posMin, posMax);

    // 随机提前
    var shiftProp = Math.random() > 0.5
        ? layer.transform.xPosition
        : layer.transform.yPosition;

    shiftKeysEarlier(shiftProp, offsetFrames);


    // ================= 核心函数（未改逻辑） =================
    function applyRotationSway(prop, minV, maxV, fixedFrameStep, count) {

        var baseValue = prop.valueAtTime(startTime, false);
        var direction = Math.random() > 0.5 ? 1 : -1;
        var currentTime = startTime;

        for (var i = 0; i < count; i++) {

            var offset = (minV + Math.random() * (maxV - minV)) * direction;
            prop.setValueAtTime(currentTime, baseValue + offset);

            var keyIndex = prop.nearestKeyIndex(currentTime);
            var ease = new KeyframeEase(0, tens);
            prop.setTemporalEaseAtKey(keyIndex, [ease], [ease]);

            currentTime += fixedFrameStep / frameRate;
            direction *= -1;
        }
    }


    function applySway(prop, minV, maxV) {

        var baseValue = prop.valueAtTime(startTime, false);
        var direction = Math.random() > 0.5 ? 1 : -1;
        var currentTime = startTime;

        for (var i = 0; i < kCount; i++) {

            var offset = (minV + Math.random() * (maxV - minV)) * direction;
            prop.setValueAtTime(currentTime, baseValue + offset);

            var keyIndex = prop.nearestKeyIndex(currentTime);
            var ease = new KeyframeEase(0, tens);
            prop.setTemporalEaseAtKey(keyIndex, [ease], [ease]);

            var frameStep = Math.floor(Math.random() * (maxInterval - minInterval + 1)) + minInterval;
            currentTime += frameStep / frameRate;

            direction *= -1;
        }
    }


    function shiftKeysEarlier(prop, frames) {

        var offsetTime = frames / frameRate;
        var keyCount = prop.numKeys;
        if (keyCount === 0) return;

        var keys = [];

        for (var i = 1; i <= keyCount; i++) {
            keys.push({
                time: prop.keyTime(i),
                value: prop.keyValue(i),
                inEase: prop.keyInTemporalEase(i),
                outEase: prop.keyOutTemporalEase(i)
            });
        }

        for (var i = keyCount; i >= 1; i--) {
            prop.removeKey(i);
        }

        for (var i = 0; i < keys.length; i++) {
            var newTime = keys[i].time - offsetTime;
            prop.setValueAtTime(newTime, keys[i].value);

            var kIndex = prop.nearestKeyIndex(newTime);
            prop.setTemporalEaseAtKey(kIndex, keys[i].inEase, keys[i].outEase);
        }
    }
}


// ===================== Z轴（不改结构，仅建议可后续优化） =====================
function Z_axis(){

    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {

        var layers = comp.selectedLayers;
        if (layers.length === 0) {
            alert("请先选中图层");
            return;
        }

        var kCount = parseInt(KEYDropdown.selection.text, 10);

        var tens = 33;
        var fps = comp.frameRate;

        // ===================== 🔥 帧率自适配 =====================
        var scale = fps / 30;
        var interval = 25 * scale;
        var step = interval / fps;

        var zMin = 0;
        var zMax = 100;

        function clamp(v, min, max) {
            return Math.min(Math.max(v, min), max);
        }

        for (var i = 0; i < layers.length; i++) {

            var layer = layers[i];
            if (!layer.threeDLayer) continue;

            var zProp = layer.transform.zPosition;
            if (!zProp) continue;

            if (zProp.expressionEnabled) {
                zProp.expressionEnabled = false;
            }

            var startTime = layer.inPoint - (3 / fps);

            var keyIndex = [];

            for (var k = 0; k < kCount; k++) {

                var t = startTime + k * step;
                var baseZ = layer.transform.position.value[2];

                var mode = k % 2;
                var small = tens * 0.4;
                var big = tens * 1.6;

                var amp = (mode == 0) ? small : big;
                var direction = (mode == 0) ? -1 : 1;

                var z = baseZ
                    + direction * amp
                    + Math.sin(k * 0.6) * (tens * 0.2);

                z = clamp(z, zMin, zMax);

                zProp.setValueAtTime(t, z);
                keyIndex.push(zProp.nearestKeyIndex(t));
            }

            for (var j = 0; j < keyIndex.length; j++) {

                var idx = keyIndex[j];

                if (idx > 0) {
                    var easeIn = new KeyframeEase(tens, tens);
                    var easeOut = new KeyframeEase(tens, tens);
                    zProp.setTemporalEaseAtKey(idx, [easeIn], [easeOut]);
                }
            }
        }

    } else {
        alert("请打开合成");
    }
}
