//选定子级图层
function sublayer() {
var comp = app.project.activeItem;
if (!(comp instanceof CompItem)) {
if (true) alert("请先打开一个合成！");
} else {
var selectedLayers = comp.selectedLayers;
if (selectedLayers.length === 0) {
if (true) alert("请先选中一个图层！");
} else {
var bottomLayers = [];
function findBottomLayer(layer) {
var children = [];
for (var i = 1; i <= comp.numLayers; i++) {
if (comp.layer(i).parent === layer) {
children.push(comp.layer(i));
}
}
if (children.length === 0) {
bottomLayers.push(layer);
} else {
for (var j = 0; j < children.length; j++) {
findBottomLayer(children[j]);
}
}
}
for (var i = 0; i < selectedLayers.length; i++) {
var layer = selectedLayers[i];
if (layer.nullLayer) {
findBottomLayer(layer);
}
}
if (bottomLayers.length !== 0) {
for (var i = 1; i <= comp.numLayers; i++) {
comp.layer(i).selected = false;
}
for (var m = 0; m < bottomLayers.length; m++) {
bottomLayers[m].selected = true;
}
}
}
}
}

