    function randomInt(min, max){
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function buildRotationKeys(baseValue) {

    if (isNaN(baseValue)) return;

    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;
    if (layers.length === 0) return;

    app.beginUndoGroup("重建旋转关键帧 + 缓动");

    var frameRate = comp.frameRate;

        // 以30fps为基准自动缩放
    var stepMin = Math.round(13 * frameRate / 30);
    var stepMax = Math.round(10 * frameRate / 30);

    var maxKeys = 10;

    for (var i = 0; i < layers.length; i++) {

        var layer = layers[i];
        var transform = layer.property("ADBE Transform Group");
        if (!transform) continue;

        var rotationProp = transform.property("ADBE Rotate Z");
        if (!rotationProp) continue;

        // 清除已有关键帧
        if (rotationProp.numKeys > 0) {
            for (var k = rotationProp.numKeys; k >= 1; k--) {
                rotationProp.removeKey(k);
            }
        }

        // 第一个关键帧：入点前3帧
        var tR = layer.inPoint - (3 / frameRate);

        for (var j = 0; j < maxKeys; j++) {

            if (tR > comp.duration) break;

            // ⭐ 输入框决定范围
            var rot = ((j % 2 === 0) ? -1 : 1) *
                randomInt(baseValue, baseValue + 3);

            rotationProp.setValueAtTime(tR, rot);

            // 选中关键帧
            var idx = rotationProp.numKeys;
            rotationProp.setSelectedAtKey(idx, true);

            // 时间递增
            var step = randomInt(stepMin, stepMax) / frameRate;
            tR += step;
        }
    }

    // 应用缓动
    app.executeCommand(2509);

    app.endUndoGroup();
    }
    
