function moveXKeys(direction){
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;
    if (layers.length === 0) return;

    var frameDur = comp.frameDuration;

    app.beginUndoGroup("X轴关键帧移动");

    for (var i = 0; i < layers.length; i++){
        var pos = layers[i].transform.position;

        if (!pos.dimensionsSeparated){
            pos.dimensionsSeparated = true;
        }

        var xPos = layers[i].transform.xPosition;
        if (xPos.numKeys < 1) continue;

        for (var k = xPos.numKeys; k >= 1; k--){
            var t = xPos.keyTime(k);
            var v = xPos.keyValue(k);

            xPos.removeKey(k);

            // direction = 1 后移，-1 前移
            xPos.setValueAtTime(t + frameDur * direction, v);
        }
    }

    app.endUndoGroup();
}    
function moveYKeys(direction){
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;
    if (layers.length === 0) return;

    var frameDur = comp.frameDuration;

    app.beginUndoGroup("Y轴关键帧移动");

    for (var i = 0; i < layers.length; i++){
        var pos = layers[i].transform.position;

        if (!pos.dimensionsSeparated){
            pos.dimensionsSeparated = true;
        }

        var yPos = layers[i].transform.yPosition;
        if (yPos.numKeys < 1) continue;

        for (var k = yPos.numKeys; k >= 1; k--){
            var t = yPos.keyTime(k);
            var v = yPos.keyValue(k);

            yPos.removeKey(k);

            // direction = 1 后移，-1 前移
            yPos.setValueAtTime(t + frameDur * direction, v);
        }
    }

    app.endUndoGroup();
}
    
    

