Mask_Shanke.onClick=function(){

    var comp = app.project.activeItem;

    if (!(comp && comp instanceof CompItem)) {
        alert("请先选中一个合成！");
        return;
    }

    var layers = comp.selectedLayers;

    if (layers.length === 0) {
        alert("请先选中图层！");
        return;
    }
// ===== ★记录时间指示器位置===== 
var savedTime = comp.time;
// ===== ★移动时间指示器到入点 ===== 
comp.time = layers[0].inPoint;
    app.beginUndoGroup("Bezier Check Run");

    var hasBezier = false;

    // =========================
    // 贝塞尔检测（是否有拉杆）
    // =========================
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];

        var masks = layer.property("ADBE Mask Parade");
        if (!masks || masks.numProperties === 0) continue;

        for (var m = 1; m <= masks.numProperties; m++) {

            var shapeProp = masks.property(m).property("ADBE Mask Shape");
            if (!shapeProp) continue;

            var shape = shapeProp.value;

            var inT = shape.inTangents;
            var outT = shape.outTangents;

            for (var v = 0; v < inT.length; v++) {

                if (
                    inT[v][0] !== 0 || inT[v][1] !== 0 ||
                    outT[v][0] !== 0 || outT[v][1] !== 0
                ) {
                    hasBezier = true;
                    break;
                }
            }

            if (hasBezier) break;
        }

        if (hasBezier) break;
    }

    // =========================
    // 分支执行
    // =========================
    if (hasBezier) {
        size2();
selectMaskPaths();
//selectFirstAndLastPositionKeys(); 
stretchPositionKeysToLayerInOut();
createRotationKeys();
    } else {
        Mask_shakeB();
    }
// ===== ★恢复时间指示器位置===== 
comp.time = savedTime;
    app.endUndoGroup();
};

