function createRotationKeys() {

    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;
    if (layers.length === 0) return;

    //app.beginUndoGroup("生成旋转关键帧 + 缓动");

    var frameRate = comp.frameRate;

    for (var n = 0; n < layers.length; n++) {

        var layer = layers[n];

        var positionProp = layer.property("ADBE Transform Group")
                                .property("ADBE Position");

        var rotationProp = layer.property("ADBE Transform Group")
                                .property("ADBE Rotate Z");

        if (!positionProp || !rotationProp) continue;
        if (positionProp.numKeys === 0) continue;

        // 清空旋转关键帧
        while (rotationProp.numKeys > 0) {
            rotationProp.removeKey(1);
        }

        // 图层持续时间
        var layerDuration = layer.outPoint - layer.inPoint;

        // 基础间隔 = 持续时间一半
        var baseStepTime = layerDuration / 2;

        // 随机
        var randomOffsetFrames = randomInt(2, 5);
        var randomOffsetTime = randomOffsetFrames / frameRate;

        // 最终间隔
        var stepTime = baseStepTime + randomOffsetTime+frameRate*5;

        // 偏移2帧
        var frameOffset = 2 / frameRate;

       var tR = positionProp.keyTime(1);

for (var i = 0; i <= positionProp.numKeys; i++) {

    var rot = ((i % 2 === 0) ? -1 : 1) * randomInt(5, 10);

    rotationProp.setValueAtTime(tR - frameOffset, rot);

    // ⭐ 每一段都重新随机间隔
    var randomOffsetFrames = randomInt(0, 3);
    var randomOffsetTime = randomOffsetFrames / frameRate;

    var stepTime = (layerDuration / 2) + randomOffsetTime;

    tR += stepTime;
}

        // 缓动
        var kNum = rotationProp.numKeys;

        for (var k = 1; k <= kNum; k++) {

            var easeIn  = new KeyframeEase(0, 33.333);
            var easeOut = new KeyframeEase(0, 33.333);

            rotationProp.setTemporalEaseAtKey(
                k,
                [easeIn],
                [easeOut]
            );
        }
    }

    //app.endUndoGroup();
}
