function selectMaskPaths() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    var layers = comp.selectedLayers;
    if (layers.length === 0) return;
    // 先清空已有选择（可选）
    for (var i = 1; i <= comp.numLayers; i++) {
        var ly = comp.layer(i);
        if (!ly) continue;

        var masks = ly.property("ADBE Mask Parade");
        if (!masks) continue;

        for (var m = 1; m <= masks.numProperties; m++) {
            var maskShape = masks.property(m).property("ADBE Mask Shape");
            if (maskShape) {
                maskShape.selected = false;
            }
        }
    }

    // 选中当前选中图层的蒙版路径
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var masks = layer.property("ADBE Mask Parade");
        if (!masks) continue;

        for (var m = 1; m <= masks.numProperties; m++) {
            var maskShape = masks.property(m).property("ADBE Mask Shape");
            if (maskShape) {
                maskShape.selected = true;
                app.executeCommand(19);
            }
        }
    }

    // =========================
    // ❶ 删除蒙版
    // =========================
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var masks = layer.property("ADBE Mask Parade");
        if (!masks) continue;

        for (var m = masks.numProperties; m >= 1; m--) {
            masks.property(m).remove();
        }
    }

    // =========================
    // ❷ 选中 Position 属性
    // =========================
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var transform = layer.property("ADBE Transform Group");
        if (!transform) continue;

        var pos = transform.property("ADBE Position");
        if (pos) {
            pos.selected = true;
            app.executeCommand(20);
        }
    }
}

function selectFirstAndLastPositionKeys() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
     //   alert("请先选中一个合成！");
        return;
    }
    var layers = comp.selectedLayers;
    if (layers.length === 0) {
     //   alert("请先选中图层！");
        return;
    }
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];

        var pos = layer.property("ADBE Transform Group").property("ADBE Position");

        if (!pos || pos.numKeys < 1) continue;

        var firstKey = 1;
        var lastKey = pos.numKeys;

        // 选中第一个关键帧
        pos.setSelectedAtKey(firstKey, true);

        // 如果只有一个关键帧，就不用重复选
        if (lastKey !== firstKey) {
            pos.setSelectedAtKey(lastKey, true);
        }
    }
app.executeCommand(2509);//缓动
}

function randomInt(min,max){
    return Math.floor(Math.random()*(max-min+1))+min;
}

function Mask_shakeB(){

    var comp=app.project.activeItem;
    if(!(comp&&comp instanceof CompItem)){
        alert("请先选中一个合成！");
        return;
    }

    var layer=comp.selectedLayers[0];
    if(!layer){
        alert("请选中一个图层！");
        return;
    }

    if(layer.mask.numProperties<1){
        alert("请在该图层创建蒙版！");
        return;
    }

    //app.beginUndoGroup("Shake");

    //size();
    size2();

    var mask=layer.mask(1);
    var shape=mask.property("ADBE Mask Shape").value;
    var vertices=shape.vertices;

    if(vertices.length<2){
        alert("蒙版点数太少！");
        //app.endUndoGroup();
        return;
    }

    var anchor=layer.property("Anchor Point").value;
    var scale=layer.property("Scale").value;
    var position=layer.property("Position").value;
    var startTime=layer.inPoint;

    var frameRate=comp.frameRate;

    // 整体提前2帧
    var frameOffset=2/frameRate;

    // 以30fps为基准自动缩放
    // 30fps = 10~15帧
    // 60fps = 20~30帧
    var stepMin=Math.round(10*frameRate/30);
    var stepMax=Math.round(15*frameRate/30);

    // =========================
    // 单独尺寸模式
    // =========================
    if(Individual_sizesCheckbox.value){

        layer.property("Position").dimensionsSeparated=true;

        var tg=layer.property("ADBE Transform Group");
        var xProp=tg.property("ADBE Position_0");
        var yProp=tg.property("ADBE Position_1");
        var rotationProp=layer.property("Rotation");

        var tX=startTime,
            tY=startTime,
            tR=startTime;

        for(var i=0;i<vertices.length;i++){

            var pt=vertices[i];

            var sp=[
                pt[0]*(scale[0]/100),
                pt[1]*(scale[1]/100)
            ];

            var fx=position[0]+(sp[0]-anchor[0]);
            var fy=position[1]+(sp[1]-anchor[1]);

            // X
            xProp.setValueAtTime(tX-frameOffset,fx);

            // Y
            yProp.setValueAtTime(tY-frameOffset,fy);

            // Rotation
            var rot=((i%2===0)?-1:1)*randomInt(5,10);
            rotationProp.setValueAtTime(tR-frameOffset,rot);

            tX+=randomInt(stepMin,stepMax)/frameRate;
            tY+=randomInt(stepMin,stepMax)/frameRate;
            tR+=randomInt(stepMin,stepMax)/frameRate;
        }

        // =========================
        // Y轴关键帧整体随机前后2帧
        // =========================
        if(yProp.numKeys>0){

            var move=randomInt(-2,2)/frameRate;

            for(var k=yProp.numKeys;k>=1;k--){

                var t=yProp.keyTime(k);
                var v=yProp.keyValue(k);

                yProp.removeKey(k);
                yProp.setValueAtTime(t+move,v);
            }
        }

        xProp.selected=true;
        yProp.selected=true;
        rotationProp.selected=true;

    }else{

        var pos=layer.property("Position");
        var rotProp=layer.property("Rotation");

        var t=startTime,
            tr=startTime;

        for(var j=0;j<vertices.length;j++){

            var pt2=vertices[j];

            var sp2=[
                pt2[0]*(scale[0]/100),
                pt2[1]*(scale[1]/100)
            ];

            var fp=[
                position[0]+(sp2[0]-anchor[0]),
                position[1]+(sp2[1]-anchor[1])
            ];

            // Position
            pos.setValueAtTime(t-frameOffset,fp);

            // Rotation
            var rot2=(j%2===0?-1:1)*randomInt(5,10);
            rotProp.setValueAtTime(tr-frameOffset,rot2);

            t+=randomInt(stepMin,stepMax)/frameRate;
            tr+=randomInt(stepMin,stepMax)/frameRate;
        }

        pos.selected=true;
        rotProp.selected=true;
    }

    app.executeCommand(2509);
    layer.mask(1).remove();

    //app.endUndoGroup();
}


   function size2() {
    var comp = app.project.activeItem;

    if (comp && comp instanceof CompItem && comp.selectedLayers.length > 0) {

        var layers = comp.selectedLayers;

        for (var i = 0; i < layers.length; i++) {
            var layer = layers[i];
            var transform = layer.property("ADBE Transform Group");

            // 展开 Transform
            transform.selected = true;

            var position = transform.property("ADBE Position");
            if (position && position.canSetExpression) {
                position.selected = true;
            } else {
                var xPos = transform.property("ADBE Position_0");
                if (xPos && xPos.canSetExpression) {
                    xPos.selected = true;
                    app.executeCommand(3764); // 单独尺寸
                }
            }
        }

        // ✅ 取消所有“属性选中状态”，但不影响图层
        app.executeCommand(2004); // Clear Selection（关键）

        // （保险）确保图层仍然选中
        for (var j = 0; j < layers.length; j++) {
            layers[j].selected = true;
        }

    } else {
        alert("请选中至少一个图层。");
    }
}
    
    function stretchPositionKeysToLayerInOut() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    var layers = comp.selectedLayers;
    if (layers.length === 0) return;
  //  app.beginUndoGroup("位置关键帧拉伸到图层出入点");
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var pos = layer.property("ADBE Transform Group").property("ADBE Position");
        if (!pos || pos.numKeys < 2) continue;
        // ===== 原关键帧范围 =====
        var firstKeyTime = pos.keyTime(1);
        var lastKeyTime  = pos.keyTime(pos.numKeys);
        var oldDuration = lastKeyTime - firstKeyTime;
        // 防止除0
        if (oldDuration <= 0) continue;
        // ===== 图层出入点 =====
        var layerIn  = layer.inPoint;
        var layerOut = layer.outPoint;
        var newDuration = layerOut - layerIn;
        // ===== 保存关键帧数据 =====
        var keyData = [];
        for (var k = 1; k <= pos.numKeys; k++) {
            keyData.push({
                time: pos.keyTime(k),
                value: pos.keyValue(k),
                inEase: pos.keyInTemporalEase(k),
                outEase: pos.keyOutTemporalEase(k),
                inInterp: pos.keyInInterpolationType(k),
                outInterp: pos.keyOutInterpolationType(k),
                spatialAutoBezier: pos.keySpatialAutoBezier(k),
                spatialContinuous: pos.keySpatialContinuous(k),
                inSpatialTangent: pos.keyInSpatialTangent(k),
                outSpatialTangent: pos.keyOutSpatialTangent(k)
            });
        }
        // ===== 删除原关键帧 =====
        while (pos.numKeys > 0) {
            pos.removeKey(1);
        }
        // ===== 重新生成关键帧 =====
        for (var j = 0; j < keyData.length; j++) {
            var d = keyData[j];
            // 归一化时间
            var t = (d.time - firstKeyTime) / oldDuration;
            // 映射到图层出入点
            var newTime = layerIn + (t * newDuration);
            var newKey = pos.addKey(newTime);
            pos.setValueAtKey(newKey, d.value);
            pos.setTemporalEaseAtKey(
                newKey,
                d.inEase,
                d.outEase
            );
            pos.setInterpolationTypeAtKey(
                newKey,
                d.inInterp,
                d.outInterp
            );
            pos.setSpatialTangentsAtKey(
                newKey,
                d.inSpatialTangent,
                d.outSpatialTangent
            );
            pos.setSpatialAutoBezierAtKey(
                newKey,
                d.spatialAutoBezier
            );
            pos.setSpatialContinuousAtKey(
                newKey,
                d.spatialContinuous
            );
        }
    }
run();
 //   app.endUndoGroup();
}

function getRoveCommandId() {
    var id = app.findMenuCommandId("漂浮穿梭时间");
    if (!id || id === 0) {
        id = app.findMenuCommandId("Rove Across Time");
    }
    return id;
}
function selectAllPositionKeys(layer) {
    var pos = layer.transform.position;
    // 如果是分离维度
    if (layer.transform.position.dimensionsSeparated) {
        var props = [
            layer.transform.xPosition,
            layer.transform.yPosition,
            layer.transform.zPosition
        ];
        for (var p = 0; p < props.length; p++) {
            if (!props[p]) continue;

            var prop = props[p];
            for (var i = 1; i <= prop.numKeys; i++) {
                prop.setSelectedAtKey(i, true);
            }
        }
    } else {
        for (var i = 1; i <= pos.numKeys; i++) {
            pos.setSelectedAtKey(i, true);
        }
    }
}
function run() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先选中一个合成！");
        return;
    }
    var layers = comp.selectedLayers;
    if (!layers || layers.length === 0) {
        alert("请先选中图层！");
        return;
    }
    // 1. 选中所有 Position 关键帧
    for (var i = 0; i < layers.length; i++) {
        selectAllPositionKeys(layers[i]);
    }
    // 2. 执行 Rove Across Time
    var cmdId = getRoveCommandId();
    if (cmdId && cmdId !== 0) {
        app.executeCommand(cmdId);
    } else {
        alert("未找到 Rove Across Time / 漂浮穿梭时间 命令");
    }
}
    

