// Shake FFX 面板
// =======================
var ShakePanel2 = Shake2.add("group");
ShakePanel2.orientation = "column";
ShakePanel2.spacing = 2;
ShakePanel2.margins = 0;

// 脚本路径
var scriptFile = new File($.fileName);
var scriptPath = scriptFile.path;
// FFX 文件夹
var presetsFolder = new Folder(scriptPath + "/FFX/Shake FFX");

// 下拉框
var ShakeffxDropdown = ShakePanel2.add(
    "dropdownlist",
    [0, 0, 170, 20],
    []
);

// ===== 全局变量 =====
var ffxFiles = [];
var ffxNames = [];

// ===== 刷新函数 =====
function refreshFFXDropdown() {
    var lastText = ShakeffxDropdown.selection
        ? ShakeffxDropdown.selection.text
        : null;
    ShakeffxDropdown.removeAll();

    ffxFiles = [];
    ffxNames = [];

    if (!presetsFolder.exists) {
        ShakeffxDropdown.add("item", "未找到 FFX 文件夹");
        ShakeffxDropdown.selection = 0;
        return;
    }

    var files = presetsFolder.getFiles("*.ffx");
    if (files.length === 0) {
        ShakeffxDropdown.add("item", "无 FFX 文件");
        ShakeffxDropdown.selection = 0;
        return;
    }

    var restoreIndex = 0;
    for (var i = 0; i < files.length; i++) {
        var name = decodeURI(files[i].name.replace(/\.ffx$/i, ""));
        ShakeffxDropdown.add("item", name);

        ffxFiles.push(files[i]);  // 保存文件路径
        ffxNames.push(name);      // 保存名称

        if (name === lastText) {
            restoreIndex = i;
        }
    }

    ShakeffxDropdown.selection = restoreIndex;
}

