// =======================
// 普通应用预设
// =======================
function ShakeapplyA() {
    app.beginUndoGroup("应用Shake预设");

    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请选中一个合成");
        app.endUndoGroup();
        return;
    }

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请至少选择一个图层");
        app.endUndoGroup();
        return;
    }

    // 清除所有图层选中状态
    for (var i = 1; i <= comp.layers.length; i++) {
        comp.layers[i].selected = false;
    }

    // 对每个选中图层单独应用预设
    for (var j = 0; j < selectedLayers.length; j++) {
        var layer = selectedLayers[j];
        layer.selected = true;
        ffxapplyBtnA();
        layer.selected = false;
    }

    app.endUndoGroup();
}

// 普通应用预设函数
function ffxapplyBtnA() {
    var comp = app.project.activeItem;
    var selectedLayers = comp.selectedLayers;

    if (selectedLayers.length === 0) return;

    var selectedIndex = ShakeffxDropdown.selection.index;
    if (selectedIndex < 0 || selectedIndex >= ffxFiles.length) {
        alert("请选择一个有效的预设！");
        return;
    }

    var ffxFile = ffxFiles[selectedIndex];
    var originalTime = comp.time;

    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        comp.time = layer.inPoint;
        layer.applyPreset(ffxFile);
    }

    comp.time = originalTime;
}

// =======================
// 带标记应用预设
// =======================
function ShakeapplyB() {
    app.beginUndoGroup("应用Shake预设并添加标记");

    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请选中一个合成");
        app.endUndoGroup();
        return;
    }

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请至少选择一个图层");
        app.endUndoGroup();
        return;
    }

    // 清除所有图层选中状态
    for (var i = 1; i <= comp.layers.length; i++) {
        comp.layers[i].selected = false;
    }

    for (var j = 0; j < selectedLayers.length; j++) {
        var layer = selectedLayers[j];
        layer.selected = true;
        ffxapplyBtnB();
        layer.selected = false;
    }

    app.endUndoGroup();
}

// 带标记应用预设函数
function ffxapplyBtnB() {
    var comp = app.project.activeItem;
    var selectedLayers = comp.selectedLayers;

    if (selectedLayers.length === 0) return;

    var selectedIndex = ShakeffxDropdown.selection.index;
    if (selectedIndex < 0 || selectedIndex >= ffxFiles.length) {
        alert("请选择一个有效的预设！");
        return;
    }

    var ffxFile = ffxFiles[selectedIndex];
    var presetName = ffxNames[selectedIndex];
    var originalTime = comp.time;

    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        comp.time = layer.inPoint;
        layer.applyPreset(ffxFile);

        // === 添加标记 ===
        var marker = new MarkerValue(presetName);
        layer.property("Marker").setValueAtTime(layer.inPoint, marker);
    }

    comp.time = originalTime;
}



