function ShakeNull(layer) {
    if (!(app.project.activeItem && app.project.activeItem instanceof CompItem)) {
        alert("请先选择一个合成。");
        return;
    }
    var comp = app.project.activeItem;
    var selectedLayers = comp.selectedLayers;
    comp.motionBlur = true;

    function findShakeLayer(comp) {
        for (var i = 1; i <= comp.numLayers; i++) {
            var l = comp.layer(i);
            if (l.name === "空" && l.nullLayer) return l;
        }
        return null;
    }
    var nullLayer = findShakeLayer(comp);
    if (!nullLayer) {
        nullLayer = comp.layers.addNull();
        nullLayer.name = "空";
    }

    if (selectedLayers.length === 0) {
        // 不选图层，添加空对象即可
    } else {
        var minInPoint = Number.MAX_VALUE;
        var maxOutPoint = Number.MIN_VALUE;
        var topmostLayer = null;
        var topmostLayerIndex = Number.MAX_VALUE;

        for (var i = 0; i < selectedLayers.length; i++) {
            var layer = selectedLayers[i];
            minInPoint = Math.min(minInPoint, layer.inPoint);
            maxOutPoint = Math.max(maxOutPoint, layer.outPoint);

            var currentLayer = layer;
            while (currentLayer) {
                if (currentLayer.index < topmostLayerIndex) {
                    topmostLayer = currentLayer;
                    topmostLayerIndex = currentLayer.index;
                }
                currentLayer = currentLayer.parent;
            }
        }
        nullLayer.inPoint = minInPoint;
        nullLayer.outPoint = maxOutPoint;
        if (topmostLayer) nullLayer.moveBefore(topmostLayer);

        function canParent(layer, potentialParent) {
            var current = layer;
            while (current) {
                if (current === potentialParent) return false;
                current = current.parent;
            }
            return true;
        }
        function parentToNull(layer) {
            if (layer.parent && canParent(layer.parent, nullLayer)) {
                parentToNull(layer.parent);
            }
            if (canParent(layer, nullLayer)) {
                layer.parent = nullLayer;
            }
        }
        for (var j = 0; j < selectedLayers.length; j++) {
            parentToNull(selectedLayers[j]);
        }
        var is3D = false;
        for (var i = 0; i < selectedLayers.length; i++) {
            if (selectedLayers[i].threeDLayer) {
                is3D = true;
                break;
            }
        }
        if (is3D) nullLayer.threeDLayer = true;

        for (var i = 0; i < selectedLayers.length; i++) {
            var layer = selectedLayers[i];
            if (layer.motionBlur !== undefined) {
                if ((layer instanceof AVLayer || layer instanceof TextLayer || layer instanceof ShapeLayer) &&
                    !(layer instanceof LightLayer) &&
                    !layer.adjustmentLayer &&
                    !layer.nullLayer) {
                    layer.motionBlur = true; // 替换为 motionBlurCheckbox1.value;
                } else {
                    $.writeln("图层 '" + layer.name + "' 不支持运动模糊。");
                }
            }
        }
        // 清除选中，选中空对象
        for (var k = 0; k < selectedLayers.length; k++) {
            selectedLayers[k].selected = false;
        }
    }
    nullLayer.selected = false; 
    nullLayer.label = 1;
}

