function shuxingAndKeyframeFixedValues1() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请先打开一个合成并选中图层");
        return;
    }
    var layers = comp.selectedLayers;
    if (layers.length === 0) {
        alert("请至少选中一个图层");
        return;
    }
    var frameRate = comp.frameRate;
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var transformGroup = layer.property("ADBE Transform Group");
        if (!transformGroup) continue;

        var inPoint = layer.inPoint;

        // 保存关键帧时间点
        var xposTimes = [inPoint, inPoint + 5 / frameRate, inPoint + 18 / frameRate, inPoint + 31 / frameRate, inPoint + 44 / frameRate, inPoint + 57 / frameRate, inPoint + 70 / frameRate];
        var yposTimes = [inPoint, inPoint + 13 / frameRate, inPoint + 26 / frameRate, inPoint + 39 / frameRate, inPoint + 52 / frameRate, inPoint + 65 / frameRate];
        var rotTimes  = [inPoint, inPoint + 13 / frameRate, inPoint + 26 / frameRate, inPoint + 39 / frameRate, inPoint + 52 / frameRate, inPoint + 65 / frameRate];

        // 位置属性
        var positionProp = transformGroup.property("ADBE Position");
        if (positionProp) {
            if (!positionProp.dimensionsSeparated) {
                positionProp.selected = true;
                app.executeCommand(3764); // 强制开启“分离维度”
            }

            if (positionProp.dimensionsSeparated) {
                var xpos = transformGroup.property("ADBE Position_0");
                var ypos = transformGroup.property("ADBE Position_1");

                if (xpos) {
                    var xposValues = [86, -66, 100, -20, 40, -20, 20];
                    for (var j = 0; j < xposTimes.length; j++) {
                        xpos.setValueAtTime(xposTimes[j], xposValues[j]);
                    }
                    // 选中关键帧
                    for (var j = 0; j < xposTimes.length; j++) {
                        var k = xpos.nearestKeyIndex(xposTimes[j]);
                        xpos.setSelectedAtKey(k, true);
                    }
                }

                if (ypos) {
                    var yposValues = [213, -90, 60, -80, 40, -20];
                    for (var j = 0; j < yposTimes.length; j++) {
                        ypos.setValueAtTime(yposTimes[j], yposValues[j]);
                    }
                    // 选中关键帧
                    for (var j = 0; j < yposTimes.length; j++) {
                        var k = ypos.nearestKeyIndex(yposTimes[j]);
                        ypos.setSelectedAtKey(k, true);
                    }
                }
            }
        }

        // 旋转属性
        var rot = transformGroup.property("ADBE Rotate");
        if (!rot) rot = transformGroup.property("ADBE Rotate Z");
        if (rot) {
            var rotValues = [5, -5, 5, -4, 3, -3];
            for (var j = 0; j < rotTimes.length; j++) {
                rot.setValueAtTime(rotTimes[j], rotValues[j]);
            }
            // 选中关键帧
            for (var j = 0; j < rotTimes.length; j++) {
                var k = rot.nearestKeyIndex(rotTimes[j]);
                rot.setSelectedAtKey(k, true);
            }
        }
    }
app.executeCommand(2509);//缓动
}
    
