//**********************重置*******************************
// tab10属性函数
function CHONGZHI() {
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem && comp.selectedLayers.length > 0) {
        for (var i = 0; i < comp.selectedLayers.length; i++) {
            var layer = comp.selectedLayers[i];
            var transform = layer.property("ADBE Transform Group");
            
            // 展开 Transform 属性组
            transform.selected = true;

            // 获取 Position 属性
            var position = transform.property("ADBE Position");
            if (position && position.canSetExpression) {
                position.selected = true;
            } else {
                var xPos = transform.property("ADBE Position_0");
                if (xPos && xPos.canSetExpression) {
                    xPos.selected = true;
                    app.executeCommand(3764); // 独立尺寸
                }
            }

            // 检测父级是否为空对象
            if (layer.parent && layer.parent.nullLayer) {
                resetProperty(layer.property("Position"), [0, 0]);
            } else {
                resetProperty(layer.property("Position"), [comp.width / 2, comp.height / 2]);
            }

            // 重置其他常规属性
            resetProperty(layer.property("Rotation"), 0);
            resetProperty(layer.property("Scale"), [100, 100]);
        }
    } else {
        alert("请先选择至少一个图层。");
    }

    function resetProperty(property, defaultValue) {
        if (property) {
            // 清除表达式
            if (property.canSetExpression && property.expression !== "") {
                property.expression = "";
            }
            // 移除关键帧
            while (property.numKeys > 0) {
                property.removeKey(property.numKeys);
            }
            // 设置默认值
            if (property.isTimeVarying) {
                property.setValue(property.valueAtTime(property.time, false));
            } else {
                property.setValue(defaultValue);
            }
        }
    }
}
