function Import_copy_images() {
    if ((!app.project) || (!app.project.activeItem) || (!(app.project.activeItem instanceof CompItem))) {
        alert("Please select a Composition Timeline first.", "Fast Paste");
        return;
    }

    // 必须先保存工程
    if (!app.project.file) {
        alert("请先保存项目。", "快速粘贴");
        return;
    }

    var comp = app.project.activeItem;

    // 工程所在目录
    var projectFolder = app.project.file.parent;

    // 保存到工程目录
    var tempImg = new File(
        projectFolder.fsName + "\\Paste_" + new Date().getTime() + ".png"
    );

    var success = ClipboardSaver.saveWithNirCmd(tempImg);
    if (!success) {
        success = ClipboardSaver.saveWithPowerShell(tempImg);
    }

    if (success && tempImg.exists) {

        try {
            app.beginUndoGroup("Fast Paste Image");

            var io = new ImportOptions(tempImg);
            var footage = app.project.importFile(io);

            footage.name = "Paste_" + new Date().getTime().toString().substring(5);

            var layer = comp.layers.add(footage);
            layer.startTime = comp.time;
            layer.position.setValue([comp.width / 2, comp.height / 2]);
            layer.selected = true;

            app.endUndoGroup();

        } catch (e) {
            alert("Import Error: " + e.toString(), "Fast Paste");
        }

    } else {
        alert("在剪贴板中找不到图片。\n请尝试再次复制（Ctrl+C）。","快速粘贴");
    }
}

var Utils = {
    getAppDataFolder: function () {
        var appData = Folder.appData.fsName;
        var folder = new Folder(appData + "\\AE_FastPaste_Tool");
        if (!folder.exists) folder.create();
        return folder;
    },

    getNirCmdPath: function () {
        return this.getAppDataFolder().fsName + "\\nircmd.exe";
    }
};

var NirCmdInstaller = {

    install: function () {

        var targetExe = Utils.getNirCmdPath();
        var zipPath = Utils.getAppDataFolder().fsName + "\\nircmd_temp.zip";

        var psScript = [
            "$ProgressPreference = 'SilentlyContinue'",
            "$ErrorActionPreference = 'Stop'",
            "$url = 'https://www.nirsoft.net/utils/nircmd-x64.zip'",
            "$zip = '" + zipPath + "'",
            "$exe = '" + targetExe + "'",
            "try {",
            "   [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12",
            "   Invoke-WebRequest -Uri $url -OutFile $zip -UseBasicParsing",
            "   Unblock-File -Path $zip -ErrorAction SilentlyContinue",
            "   Add-Type -AssemblyName System.IO.Compression.FileSystem",
            "   $zipObj = [System.IO.Compression.ZipFile]::OpenRead($zip)",
            "   $entry = $zipObj.Entries | Where-Object { $_.Name -eq 'nircmd.exe' }",
            "   if ($entry) {",
            "       if (Test-Path $exe) { Remove-Item $exe -Force }",
            "       [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $exe, $true)",
            "   }",
            "   $zipObj.Dispose()",
            "   Remove-Item $zip -Force",
            "   Unblock-File -Path $exe -ErrorAction SilentlyContinue",
            "} catch { exit 1 }"
        ].join("\r\n");

        var psFile = new File(Folder.temp.fsName + "\\ae_nircmd_install.ps1");
        psFile.open("w");
        psFile.write(psScript);
        psFile.close();

        system.callSystem("powershell.exe -NoProfile -ExecutionPolicy Bypass -File \"" + psFile.fsName + "\"");

        if (psFile.exists) psFile.remove();

        return this.isInstalled();
    },

    isInstalled: function () {
        var f = new File(Utils.getNirCmdPath());
        return (f.exists) && (f.length > 1000);
    }
};

var ClipboardSaver = {

    saveWithNirCmd: function (targetPath) {

        if (!NirCmdInstaller.isInstalled()) {
            if (!NirCmdInstaller.install()) return false;
        }

        var nircmdExe = Utils.getNirCmdPath();
        var vbsPath = Folder.temp.fsName + "\\nircmd_runner.vbs";
        var vbsFile = new File(vbsPath);

        var vbsCode =
            "Set WshShell = CreateObject(\"WScript.Shell\")\r\n" +
            "exePath = \"" + nircmdExe + "\"\r\n" +
            "imgPath = \"" + targetPath.fsName + "\"\r\n" +
            "cmd = chr(34) & exePath & chr(34) & \" clipboard saveimage \" & chr(34) & imgPath & chr(34)\r\n" +
            "WshShell.Run cmd, 0, True";

        vbsFile.open("w");
        vbsFile.write(vbsCode);
        vbsFile.close();

        system.callSystem("wscript.exe \"" + vbsPath + "\"");

        if (vbsFile.exists) vbsFile.remove();

        var f = new File(targetPath.fsName);
        return (f.exists) && (f.length > 0);
    },

    saveWithPowerShell: function (targetPath) {

        var psPath = Folder.temp.fsName + "\\ae_clipboard_dump.ps1";
        var psFile = new File(psPath);

        var psScript = [
            "Add-Type -AssemblyName System.Windows.Forms",
            "Add-Type -AssemblyName System.Drawing",
            "$dest = '" + targetPath.fsName + "'",
            "try {",
            "   if ([System.Windows.Forms.Clipboard]::ContainsImage()) {",
            "       $img = [System.Windows.Forms.Clipboard]::GetImage()",
            "       $img.Save($dest, [System.Drawing.Imaging.ImageFormat]::Png)",
            "       $img.Dispose()",
            "   }",
            "} catch {}"
        ].join("\r\n");

        psFile.open("w");
        psFile.write(psScript);
        psFile.close();

        var vbsRunner = Folder.temp.fsName + "\\ps_runner.vbs";
        var vbs = new File(vbsRunner);

        vbs.open("w");
        vbs.write("CreateObject(\"WScript.Shell\").Run \"powershell -NoProfile -ExecutionPolicy Bypass -File \"\"" + psPath + "\"\"\", 0, True");
        vbs.close();

        system.callSystem("wscript.exe \"" + vbsRunner + "\"");

        if (psFile.exists) psFile.remove();
        if (vbs.exists) vbs.remove();

        var f = new File(targetPath.fsName);
        return (f.exists) && (f.length > 0);
    }
};

