downloadBtn.onClick = function(){
    app.executeCommand(5);
    var videoURL = urlInput.text;

    if(videoURL == ""){
        alert("请输入视频网址！");
        return;
    }

    if(!toolboxFolder){
        alert(
            "请先设置工具箱大师中转站路径"
        );
        return;
    }
    var targetFolder = new Folder(toolboxFolder.fsName + "/yt-dlp");

    if (!targetFolder.exists){
        targetFolder.create();
    }

    var batFile = new File(targetFolder.fsName + "/run.bat");
    batFile.encoding = "UTF-8";

    if(batFile.open("w")){
        var exePath = targetFolder.fsName + "/yt-dlp.exe";
        var batContent = "";

        batContent += "@echo off\r\n";
        batContent += "chcp 65001\r\n";
        batContent += "cd /d \"%~dp0\"\r\n";

        if(audioOnlyCheckbox.value){
            // 只下载音频
            batContent += "\"" + exePath + "\" -x --audio-format mp3 \"" + videoURL + "\"\r\n";
        }else{
            // 下载完整视频
            batContent += "\"" + exePath + "\" \"" + videoURL + "\"\r\n";
        }

        batFile.write(batContent);
        batFile.close();

        batFile.execute();

        // 开始检测下载完成
        waitForDownload(targetFolder);
// app.executeCommand(2156);//适合画面
    }else{
        alert("无法创建 BAT 文件！");
    }
};

function FIX() {
    app.beginUndoGroup("移动资源并生成bat");

    // 获取当前选中的合成
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先选择一个合成！");
        app.endUndoGroup();
        return;
    } else if (comp.selectedLayers.length === 0) {
        alert("请先选中图层！");
        app.endUndoGroup();
        return;
    }

    // 目标文件夹
    if(!toolboxFolder){
        alert(
            "请先设置工具箱大师中转站路径"
        );
        return;
    }
    var targetFolder = new Folder(toolboxFolder.fsName + "/yt-dlp");
    if (!targetFolder.exists) targetFolder.create();

    // 存储信息
    var filesToMove = [];

    // ===== 新增：编号 =====
    var index = 1;

    // ===================== 1. 移动并重命名文件 =====================
    for (var i = 0; i < comp.selectedLayers.length; i++) {
        var layer = comp.selectedLayers[i];

        if (layer.source && layer.source.file) {

            var srcFile = layer.source.file;

            // ===== 生成新文件名：下载视频_1.xxx =====
            var ext = "";
            var nameParts = srcFile.name.split(".");
            if (nameParts.length > 1) {
                ext = nameParts[nameParts.length - 1];
            }

            var newName = "修复下载视频_" + index;
            if (ext !== "") {
                newName += "." + ext;
            }
            index++;

            var destFile = new File(targetFolder.fsName + "/" + newName);

            try {
                if (destFile.exists) destFile.remove();

                // 复制 + 删除原文件
                srcFile.copy(destFile);
                srcFile.remove();

                filesToMove.push({
                    layer: layer,
                    newFile: destFile,
                    projectItem: layer.source
                });

                $.writeln("已移动并改名: " + newName);

            } catch (e) {
                $.writeln("移动失败: " + srcFile.name + " 错误: " + e.toString());
            }
        }
    }

    // ===================== 2. 删除选中图层 =====================
    for (var j = comp.selectedLayers.length - 1; j >= 0; j--) {
        comp.selectedLayers[j].remove();
    }

    // ===================== 3. 删除项目面板素材 =====================
    for (var k = 0; k < filesToMove.length; k++) {
        var item = filesToMove[k];
        try {
            if (item.projectItem && item.projectItem.parentFolder) {
                item.projectItem.remove();
            }
        } catch (e) {
            // 忽略已删除或无法删除
        }
    }

    // ===================== 4. 创建修复.bat =====================
    var batFile = new File(targetFolder.fsName + "/修复.bat");

    var batContent = "";
    batContent += "@echo off\r\n";
    batContent += "setlocal enabledelayedexpansion\r\n";
    batContent += "set \"ffmpeg=%~dp0ffmpeg.exe\"\r\n";
    batContent += "set \"ext_list=mp4 avi mov mkv flv wmv mpeg mpg m4v 3gp webm vob ts mts m2ts rm rmvb\"\r\n";

    batContent += "for %%F in (*) do (\r\n";
    batContent += "    set \"input=%%~fF\"\r\n";
    batContent += "    set \"name=%%~nF\"\r\n";
    batContent += "    set \"ext=%%~xF\"\r\n";
    batContent += "    set \"ext=!ext:~1!\"\r\n";
    batContent += "    set \"is_video=0\"\r\n";
    batContent += "    for %%E in (%ext_list%) do if /i \"!ext!\"==\"%%E\" set \"is_video=1\"\r\n";

    batContent += "    if \"!is_video!\"==\"1\" (\r\n";
    batContent += "        set \"output=%%~dpF!name!_converted.mp4\"\r\n";
    batContent += "        \"%ffmpeg%\" -i \"!input!\" -c:v libx264 -b:v 5000k -preset medium -c:a aac -b:a 160k -y \"!output!\"\r\n";
    batContent += "        if exist \"!output!\" del /f /q \"!input!\"\r\n";
    batContent += "    )\r\n";
    batContent += ")\r\n";

    batContent += "echo 所有视频转换完成，旧视频已删除！\r\n";
    batContent += "pause\r\n";

    batFile.encoding = "UTF-8";
    batFile.open("w");
    batFile.write(batContent);
    batFile.close();

    // ===================== 5. 启动 bat =====================
    var cmd = 'cmd /k "cd /d "' + targetFolder.fsName + '" && "' + batFile.fsName + '"';
    system.callSystem(cmd);

    waitForDownload(targetFolder);

    // ===================== 6. 适合画面 =====================
  //  app.executeCommand(2156);

    app.endUndoGroup();
}

function waitForDownload(folder){
    var videoExt = /\.(mp4|mov|mkv|avi|flv|webm|m4v|mp3|wav|m4a|aac|flac|ogg)$/i;
    var maxWait = 86400; // 最多等待86400秒
    var count = 0;
    while (count < maxWait){
        var files = folder.getFiles(function(f){
            return (f instanceof File) && videoExt.test(f.name);
        });
        if(files.length > 0){
            // 再确认文件大小稳定（防止还在下载）
            var size1 = files[0].length;
            $.sleep(2000);
            var size2 = files[0].length;
            if(size1 == size2){
                Super_import();
                return;
            }
        }
        $.sleep(1000);
        count++;
    }
    alert("下载超时！");
}

function Super_import() {
    if (!app.project.file) {
        alert("请先保存工程文件");
        return;
    }

    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先打开一个合成");
        return;
    }

    var projectFolder = app.project.file.parent;
    if(!toolboxFolder){
        alert(
            "请先设置工具箱大师中转站路径"
        );
        return;
    }
    var targetFolder = new Folder(toolboxFolder.fsName + "/yt-dlp");
    if (!targetFolder.exists) {
        alert("未找到 yt-dlp 文件夹");
        return;
    }

    var videoExt = /\.(mp4|mov|mkv|avi|flv|webm|m4v|mp3|wav|m4a|aac|flac|ogg)$/i;

    var files = targetFolder.getFiles();
    var importedFile = null;

    for (var i = 0; i < files.length; i++) {
        if (!(files[i] instanceof File)) continue;
        if (!videoExt.test(files[i].name)) continue;

        var sourceFile = files[i];
        var newName = sourceFile.name.replace(/_converted(\.[^\.]+)$/i, "$1");
        var newFile = new File(projectFolder.fsName + "/" + newName);

        var count = 1;
        while (newFile.exists) {
            var nameParts = newName.match(/^(.*?)(\.[^\.]+)$/);
            var baseName = nameParts[1];
            var ext = nameParts[2];
            newFile = new File(projectFolder.fsName + "/" + baseName + "_" + count + ext);
            count++;
        }

        sourceFile.copy(newFile.fsName);
        sourceFile.remove();
        importedFile = newFile;

        // -------- 删除原始文件逻辑 --------
        // 获取文件名基本部分和扩展名
        var fileNameParts = newFile.name.match(/^(.*?)(_?\d*)?(\.[^\.]+)$/);
        var baseNameOnly = fileNameParts[1];
        var ext = fileNameParts[3];

        // 查找同名但没有数字后缀的文件
        var allFiles = projectFolder.getFiles(baseNameOnly + ext);
        for (var j = 0; j < allFiles.length; j++) {
            if (allFiles[j] instanceof File) {
                try { allFiles[j].remove(); } catch(e) {}
            }
        }

        break; // 只处理一个文件
    }

    if (importedFile) {
        var importOptions = new ImportOptions(importedFile);
        var footage = app.project.importFile(importOptions);

        var layer = comp.layers.add(footage);
        layer.startTime = 0;
        layer.moveToBeginning();
    }

    deselectProjectItems();
}


