function openSelectedAudio() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return;
    var layers = comp.selectedLayers;
    if (layers.length == 0) return;
    for (var i = 0; i < layers.length; i++) {
        layers[i].audioEnabled = true;
    }
}
function Delete_rideo() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
var baseFolder = new Folder(toolboxFolder.fsName + "/保留人声");

if (baseFolder.exists) {
    var files = baseFolder.getFiles(function(f) {
        return f instanceof File && /\.(mp3|wav|aiff|aac)$/i.test(f.name);
    });

    for (var i = 0; i < files.length; i++) {
        try {
            files[i].remove();
        } catch (e) {
            $.writeln("无法删除文件: " + files[i].fsName);
        }
    }
} else {
    alert("文件夹不存在：" + baseFolder.fsName);
}
}

function DeleteAllSubFolders() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var vocalFolder = new Folder(toolboxFolder.fsName + "/保留人声/vocal");
    if (!vocalFolder.exists) return;
    // 先改名所有子文件夹为 "1"
    var items = vocalFolder.getFiles();
    for (var i = 0; i < items.length; i++) {
        var it = items[i];
        if (it instanceof Folder) {
            var newName = it.parent.fsName + "/1";
            // 如果目标名已存在则继续增加数字
            var counter = 1;
            while (Folder(newName).exists) {
                counter++;
                newName = it.parent.fsName + "/1_" + counter;
            }
            it.rename(newName.split("/").pop());
        }
    }
    // 删除用递归
    function deleteFolderRecursive(folder) {
        var files = folder.getFiles();
        for (var j = 0; j < files.length; j++) {
            var f = files[j];
            if (f instanceof Folder) {
                deleteFolderRecursive(f);
                f.remove();
            } else {
                f.remove();
            }
        }
    }
    // 再删全部子文件夹
    var folders = vocalFolder.getFiles();
    for (var k = 0; k < folders.length; k++) {
        var fd = folders[k];
        if (fd instanceof Folder) {
            deleteFolderRecursive(fd);
            fd.remove();
        }
    }
}

function DeleteVocalFolder() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var baseFolder = new Folder(toolboxFolder.fsName + "/保留人声");
    var vocalFolder = new Folder(baseFolder.fsName + "/vocal");
    if (!vocalFolder.exists) {
        return; // 没有 vocal 就直接结束
    }
    // 递归删除文件夹内容
    function deleteFolderRecursive(folder) {
        var files = folder.getFiles();
        for (var i = 0; i < files.length; i++) {
            var f = files[i];
            if (f instanceof Folder) {
                deleteFolderRecursive(f);
                f.remove();
            } else {
                f.remove();
            }
        }
    }
    // 清空 vocal 里面内容
    deleteFolderRecursive(vocalFolder);
    // 删除 vocal 文件夹本体
    vocalFolder.remove();
}

