function RunVocals() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }

    var targetFolder = new Folder(toolboxFolder.fullName + "/保留人声");
    if (!targetFolder.exists) return false;

    var exeFile = new File(targetFolder.fsName + "/提取人声.exe");
    if (!exeFile.exists) return false;

    // 启动 EXE
    exeFile.execute();

    // 检测 vocal 文件夹是否有文件
    var vocalFolder = new Folder(targetFolder.fsName + "/vocal");

    // 等待 EXE 生成文件，最多等 1 天，每 0.5 秒检查一次
    var maxWait = 86400000; // 毫秒
    var interval = 500;  // 毫秒
    var waited = 0;
    while (waited < maxWait) {
        if (vocalFolder.exists) {
            var files = vocalFolder.getFiles();
            if (files.length > 0) {
                Move_wav_and_import(); // 找到文件，执行
                return true;
            }
        }
        $.sleep(interval); // 延迟
        waited += interval;
    }

    // 超时也没文件，不执行
    // alert("未生成 vocal 文件，跳过 Move_wav_and_import()");
    return false;
}
