function Move_wav_and_import() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var sourceVocalFolder = new Folder(toolboxFolder.fsName + "/保留人声/vocal");

    if (!sourceVocalFolder.exists) {
     //   alert("源文件夹不存在！");
        return;
    }

    if (app.project.file == null) {
        alert("请先保存当前工程！");
        return;
    }

    var targetFolder = new Folder(app.project.file.parent.fsName);

    // 复制文件夹（递归）
    function copyFolder(srcFolder, destFolder) {
        if (!destFolder.exists) destFolder.create();
        var files = srcFolder.getFiles();
        for (var i = 0; i < files.length; i++) {
            var f = files[i];
            if (f instanceof Folder) {
                copyFolder(f, new Folder(destFolder.fsName + "/" + f.name));
            } else if (f instanceof File) {
                f.copy(destFolder.fsName + "/" + f.name);
            }
        }
    }

    // 删除文件夹（递归）
    function deleteFolder(folder) {
        var files = folder.getFiles();
        for (var i = 0; i < files.length; i++) {
            var f = files[i];
            if (f instanceof Folder) {
                deleteFolder(f);
            } else {
                f.remove();
            }
        }
        folder.remove();
    }

    function getOrCreateMasterFolder() {
        for (var i = 1; i <= app.project.rootFolder.numItems; i++) {
            var item = app.project.rootFolder.item(i);
            if (item instanceof FolderItem && item.name === "工具箱大师提取人声") {
                return item;
            }
        }
        return app.project.items.addFolder("工具箱大师提取人声");
    }

    var masterFolder = getOrCreateMasterFolder();
    var subFolders = sourceVocalFolder.getFiles(function(f){ return f instanceof Folder; });

    for (var j = 0; j < subFolders.length; j++) {
        var subFolder = subFolders[j];
        var destSubFolder = new Folder(targetFolder.fsName + "/" + subFolder.name);
        copyFolder(subFolder, destSubFolder);

        var audioFiles = destSubFolder.getFiles(function(f){
            return f instanceof File && /\.(wav|mp3|flac|m4a|ogg|aac)$/i.test(f.name);
        });

        for (var k = 0; k < audioFiles.length; k++) {
            var file = audioFiles[k];
            var importOptions = new ImportOptions(file);
            if (importOptions.canImportAs(ImportAsType.FOOTAGE)) {
                importOptions.importAs = ImportAsType.FOOTAGE;
            }
            var imported = app.project.importFile(importOptions);
            imported.parentFolder = masterFolder;

            // 如果有选中图层 → 放到下面并对齐
            if (app.project.activeItem instanceof CompItem && app.project.activeItem.selectedLayers.length > 0) {
                var comp = app.project.activeItem;
                var inputLayer = comp.selectedLayers[0];

                var newLayer = comp.layers.add(imported);
                newLayer.startTime = inputLayer.inPoint;

                // 放到选中图层正下方
                var targetIndex = inputLayer.index + 1;
                if (targetIndex > comp.layers.length) {
                    newLayer.moveToEnd();
                } else {
                    newLayer.moveAfter(inputLayer);
                }
            }
        }
    }

    deleteFolder(sourceVocalFolder);
}

function closeAboveAudio() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return;
    var layer = comp.selectedLayers[0];
    if (!layer) return;
    var index = layer.index;
    //关闭选中图层上方所有音频
    for (var i = 1; i < index; i++) {

        comp.layer(i).audioEnabled = false;

    }

}

