function deleteAudioAndSRT() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var targetFolder = new Folder(toolboxFolder.fsName + "/语音转文字");

    if (!targetFolder.exists) return; // 文件夹不存在就退出

    // 获取所有音频和 SRT 文件
    var files = targetFolder.getFiles(function(f) {
        return f instanceof File && f.name.match(/\.(srt|mp3|wav)$/i);
    });

    // 删除文件
    for (var i = 0; i < files.length; i++) {
        try {
            files[i].remove();
        } catch (e) {
            $.writeln("无法删除文件: " + files[i].fsName);
        }
    }
}

