function depth_imageSequence() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var sourceFolder = new Folder(toolboxFolder.fsName + "/深度分析");

    var projectFolder;
    if (app.project.file) {
        projectFolder = app.project.file.parent;
    } else {
        alert("请先保存工程文件，脚本才能移动文件到工程目录！");
        return;
    }

    if (!sourceFolder.exists) {
        alert("深度分析文件夹不存在！");
        return;
    }

    var sequenceFolders = sourceFolder.getFiles(function(f) { return f instanceof Folder; });
    if (sequenceFolders.length === 0) {
        alert("未找到图片序列文件夹！");
        return;
    }

    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请先选择一个合成！");
        return;
    }

    var selectedLayers = comp.selectedLayers;
    var referenceLayer = (selectedLayers.length > 0) ? selectedLayers[0] : null;

    app.beginUndoGroup("移动并导入图片序列");

    for (var i = 0; i < sequenceFolders.length; i++) {
        var folder = sequenceFolders[i];
        var destFolder = new Folder(projectFolder.fsName + "/" + folder.name);
        if (!destFolder.exists) destFolder.create();

        // 复制文件
        var files = folder.getFiles("*.png"); // 根据需要改 jpg/tif
        for (var j = 0; j < files.length; j++) {
            files[j].copy(new File(destFolder.fsName + "/" + files[j].name));
            files[j].remove(); // 删除原文件
        }
        // 删除空文件夹
        folder.remove();

        if (files.length === 0) continue;

        // 导入为图片序列
        var importOptions = new ImportOptions(new File(destFolder.fsName + "/" + files[0].name));
        importOptions.sequence = true;
        if (importOptions.canImportAs(ImportAsType.FOOTAGE)) {
            importOptions.importAs = ImportAsType.FOOTAGE;
            var importedItem = app.project.importFile(importOptions);

            var newLayer = comp.layers.add(importedItem);
            if (referenceLayer) {
                newLayer.moveBefore(referenceLayer);
                newLayer.startTime = referenceLayer.startTime;
            } else {
                newLayer.startTime = 0;
            }

            $.writeln("已导入图片序列：" + newLayer.name);
        } else {
            alert("无法导入图片序列：" + folder.name);
        }
    }

    app.endUndoGroup();
}

function addTintToSelectedLayersSilently() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        return;
    }
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        return;
    }
    app.beginUndoGroup("添加 Tint 效果");
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        // 仅对可添加效果的图层处理
        if (layer instanceof AVLayer || layer instanceof ShapeLayer) {
            try {
                var tintEffect = layer.Effects.addProperty("ADBE Tint");
                if (tintEffect) {
                    // 设置黑色映射为蓝色
                    tintEffect.property("ADBE Tint-0001").setValue([1, 1, 1]);
                    // 设置白色映射为橙色
                    tintEffect.property("ADBE Tint-0002").setValue([0, 0, 0]);
                }
            } catch (e) {
                // 出错不提示，直接跳过
            }
        }
    }

    app.endUndoGroup();
};
