//AI 抠图
// 抠图流程诊断：true=关键步骤弹窗便于排查；正常使用可改为 false
var BG_REMOVE_DEBUG = false;

// 不再弹窗
function bgRemoveDiag(step, message, isError) {
    return;
}

// saveFrameToPng 写入磁盘有延迟，需轮询等待
function bgRemoveWaitForFile(file, maxLoops) {
    maxLoops = maxLoops || 200;
    var f = new File(file.fsName);

    for (var i = 0; i < maxLoops; i++) {
        if (f.exists && f.length > 0) return f;
        $.sleep(50);
        f = new File(file.fsName);
    }

    return (f.exists && f.length > 0) ? f : null;
}

function bgRemoveSanitizeFileName(name) {
    return String(name)
        .replace(/[\\\/:\*\?"<>\|]/g, "_")
        .replace(/^\s+|\s+$/g, "");
}

// 统一启动 background_remove.exe（PyInstaller 必须在 _internal 同级目录运行）
function launchBackgroundRemoveExe(useAdmin) {

    var step = useAdmin ? "启动抠图程序(视频)" : "启动抠图程序(图片)";

    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var targetFolder = new Folder(
        toolboxFolder.fsName + "/抠图"
    );

    var exeFile = new File(
        targetFolder.fsName + "/background_remove.exe"
    );

    if (!exeFile.exists) {
        return false;
    }

    if (!targetFolder.exists && !targetFolder.create()) {
        return false;
    }

    var batFile = new File(
        targetFolder.fsName + "/run_background_remove_launch.bat"
    );

    batFile.encoding = "UTF-8";

    if (!batFile.open("w")) {
        return false;
    }

    batFile.write("@echo off\r\n");
    batFile.write("cd /d \"%~dp0\"\r\n");

    if (useAdmin) {
        batFile.write(
            "powershell -NoProfile -ExecutionPolicy Bypass -Command \"Start-Process -FilePath '%~dp0background_remove.exe' -WorkingDirectory '%~dp0' -Verb RunAs\"\r\n"
        );
    } else {
        batFile.write(
            "start \"\" \"background_remove.exe\"\r\n"
        );
    }

    batFile.write("exit\r\n");
    batFile.close();

    var errors = [];

    try {
        if (batFile.execute()) {
            return true;
        }
        errors.push("bat.execute() 返回 false");
    } catch (e1) {
        errors.push("bat.execute(): " + e1.toString());
    }

    try {
        if (exeFile.execute()) {
            return true;
        }
        errors.push("exe.execute() 返回 false");
    } catch (e2) {
        errors.push("exe.execute(): " + e2.toString());
    }

    try {
        var cmd =
            'cmd /c cd /d "' +
            targetFolder.fsName +
            '" && start "" "' +
            exeFile.fsName +
            '"';

        system.callSystem(cmd);

        return true;
    } catch (e3) {
        errors.push("callSystem: " + e3.toString());
    }

    return false;
}

