// 函数：创建运行中.txt
function createRunFile() {
    try {
        if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
        var targetFolder = new Folder(
            toolboxFolder.fsName + "/抠图"
        );

        if (!targetFolder.exists) {
            if (!targetFolder.create()) {
             //   $.writeln("无法创建文件夹：" + targetFolder.fsName);
                return null;
            }
        }

        var runFile = new File(
            targetFolder.fsName + "/运行中.txt"
        );

        if (!runFile.open("w")) {
            $.writeln("无法写入运行中.txt");
            return null;
        }

        runFile.write("运行中");
        runFile.close();

        return runFile;

    } catch (e) {
    //    $.writeln("createRunFile 错误：" + e.toString());
        return null;
    }
}

// 清空渲染队列
function rendering() {
    for (var r = app.project.renderQueue.numItems; r >= 1; r--) {
        app.project.renderQueue.item(r).remove();
    }
}

   function Save() {
   app.executeCommand(5);  //保存ID命令··
   }

function deleteAllImagesInFolder() {
    try {
        if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
        var targetFolder = new Folder(
            toolboxFolder.fsName + "/抠图"
        );

        if (!targetFolder.exists) {
            return;
        }

        var imageFiles = targetFolder.getFiles(function (f) {
            return f instanceof File &&
                   /\.(png|jpg|jpeg)$/i.test(f.name);
        });

        for (var i = 0; i < imageFiles.length; i++) {
            try {
                imageFiles[i].remove();
            } catch (e) {
                $.writeln("删除失败: " + imageFiles[i].fsName);
            }
        }

    } catch (e) {
    }
}

function PNG_background() {
if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var folderExport = new Folder(
        toolboxFolder.fsName + "/抠图"
    );

    if (!folderExport.exists) {
        if (!folderExport.create()) {
            return false;
        }
    }

    function getActiveComp() {
        if (app.project.activeItem instanceof CompItem) {
            return app.project.activeItem;
        }
        return null;
    }

    function frameAsPng(customName) {

        var compItem = getActiveComp();
        if (!compItem) {
            return false;
        }

        var filePngName = bgRemoveSanitizeFileName(
            customName || compItem.name || "Screenshot"
        );

        if (!filePngName) {
            return false;
        }

        var filePng = new File(
            folderExport.fsName + "/" + filePngName + ".png"
        );

        try {

            compItem.openInViewer();
            compItem.saveFrameToPng(
                compItem.time,
                filePng
            );

            var savedFile = bgRemoveWaitForFile(filePng);

            if (!savedFile) {
                return false;
            }

            if (!launchBackgroundRemoveExe(false)) {
                return false;
            }

            return true;

        } catch (e) {
            return false;
        }
    }

    var userFileName = prompt("请输入截图文件名：", "");

    if (userFileName !== null && userFileName !== "") {
        return frameAsPng(userFileName);
    }

    return false;
}

function matchInOutWithBelowLayer() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        app.endUndoGroup();
        return;
    }
    var sel = comp.selectedLayers;
    if (sel.length === 0) {
        app.endUndoGroup();
        return;
    }
    var layer = sel[0];
    // 判断是否存在下方图层
    if (layer.index >= comp.numLayers) {
        app.endUndoGroup();
        return;
    }
    var belowLayer = comp.layer(layer.index + 1);
    // 获取下方图层的入点和出点
    var inP  = belowLayer.inPoint;
    var outP = belowLayer.outPoint;
    // 设置选中图层入点和出点
    layer.inPoint  = inP;
    layer.outPoint = outP;
};


function waitForRunningFileDisappear() {

    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var folderExport = new Folder(
        toolboxFolder.fsName + "/抠图"
    );

    var runningFile = new File(
        folderExport.fsName + "/运行中.txt"
    );

    var maxLoops = 7200;
    var count = 0;

    while (runningFile.exists) {

        $.sleep(500);

        runningFile = new File(
            folderExport.fsName + "/运行中.txt"
        );

        count++;

        if (count >= maxLoops) {
            return;
        }
    }
}

function MAIN() {

    var comp = null;
    var selectedLayers = null;
    var originalStartTimes = [];
    var step = "";

    try {

        comp = app.project.activeItem;

        if (!(comp instanceof CompItem)) {
            return;
        }

        selectedLayers = comp.selectedLayers;

        if (!selectedLayers || selectedLayers.length === 0) {
            return;
        }

        // 记录原始入点
        for (var i = 0; i < selectedLayers.length; i++) {
            originalStartTimes.push(
                selectedLayers[i].startTime
            );
        }

        shiftInPointToCompStart();
        one_Workspace();
        outputmp4();

    } catch (e) {

    } finally {

        // 恢复图层入点与 solo
        try {

            if (
                comp &&
                selectedLayers &&
                selectedLayers.length === originalStartTimes.length
            ) {

                for (var j = 0; j < selectedLayers.length; j++) {

                    try {
                        selectedLayers[j].startTime =
                            originalStartTimes[j];
                    } catch (e1) {}
                }
            }

            if (comp instanceof CompItem) {

                for (var k = 1; k <= comp.numLayers; k++) {

                    try {

                        var lyr = comp.layer(k);

                        if (lyr && lyr.enabled) {
                            lyr.solo = false;
                        }

                    } catch (e2) {}
                }
            }

        } catch (e3) {}

        // 启动抠图程序并等待结束
        try {

            runBackgroundRemove();
            waitForRunningFileDisappear();

        } catch (e4) {}

        // 删除视频
        try {
            deleteVideoOnly();
        } catch (e5) {}

        // 导入结果
        try {
            copyImportAndAddPNGSequencesToTimeline();
        } catch (e6) {}

        // 收尾
        try {
            deselectProjectItems();
            cometime();
        } catch (e7) {}
    }
}

function cometime() {
// 获取当前合成
    var comp = app.project.activeItem;
    // 确保当前合成是有效的并且是一个合成项
    if (comp instanceof CompItem) {
        // 获取合成的总时长
        var compDuration = comp.duration;
        // 设置工作区的开始时间为0，持续时间为合成的总时长
        comp.workAreaStart = 0;
        comp.workAreaDuration = compDuration;
    } else {}
};

