// createRunFile 已在上方定义（含诊断弹窗）

// ---------- 主轮询函数 ----------
function monitorAndRun() {
    // 获取脚本所在目录
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    // 目标目录
    var targetFolder = new Folder(toolboxFolder.fsName + "/抠图");
    if (!targetFolder.exists) {
        alert("目录不存在: " + targetFolder.fsName);
        return;
    }
    // 运行中标记文件
    var runFile = new File(targetFolder.fsName + "/运行中.txt");
    // 轮询等待
    while (true) {
        if (!runFile.exists) {
            // 文件不存在，可以执行函数
            try {
                copyImportAndAddPNGSequencesToTimeline();
            } catch (e) {
                $.writeln("执行函数出错: " + e.toString());
            }
            break; // 执行完后退出循环
        } else {
            $.writeln("检测到运行中.txt，等待中...");
            // 等待 0.5 秒再检测
            $.sleep(500);
        }
    }
}

// ---------- 主轮询函数 ----------
function monitorAndRun2() {
if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var targetFolder = new Folder(
        toolboxFolder.fsName + "/抠图"
    );

    if (!targetFolder.exists) {
        $.writeln("目录不存在：" + targetFolder.fsName);
        return;
    }

    var runFile = new File(
        targetFolder.fsName + "/运行中.txt"
    );

    var maxLoops = 7200;
    var count = 0;

    while (true) {

        if (!runFile.exists) {

            try {
                one_png();
                IN_OUT();
            } catch (e) {
                $.writeln("导入PNG失败：" + e.toString());
            }

            break;
        }

        count++;

        if (count >= maxLoops) {
            $.writeln("等待运行中.txt超时");
            break;
        }

        $.sleep(500);

        runFile = new File(
            targetFolder.fsName + "/运行中.txt"
        );
    }
}

// 获取当前合成并设置工作区时间
function Workspace() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return;

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) return;

    // 先关闭所有图层的 solo
    for (var i = 1; i <= comp.numLayers; i++) {
        comp.layer(i).solo = false;
    }

    // 计算选中图层的最早 inPoint 和最晚 outPoint
    var workAreaStart = selectedLayers[0].inPoint;
    var workAreaEnd   = selectedLayers[0].outPoint;

    for (var j = 0; j < selectedLayers.length; j++) {
        var layer = selectedLayers[j];
        workAreaStart = Math.min(workAreaStart, layer.inPoint);
        workAreaEnd   = Math.max(workAreaEnd, layer.outPoint);

        // 开启选中图层的 solo
        layer.solo = true;
    }

    // 设置工作区
    comp.workAreaStart = workAreaStart;
    comp.workAreaDuration = workAreaEnd - workAreaStart;
}


// 渲染
function outputmp4() {

    var comp = app.project.activeItem;

    if (!(comp && comp instanceof CompItem)) {
        return false;
    }

    if (comp.selectedLayers.length !== 1) {
        return false;
    }

    var layer = comp.selectedLayers[0];

    // 输出目录
   if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }

    var outFolder = new Folder(
        toolboxFolder.fsName + "/抠图"
    );

    if (!outFolder.exists) {
        if (!outFolder.create()) {
            return false;
        }
    }

    // 清理 Solo
    for (var i = 1; i <= comp.numLayers; i++) {
        comp.layer(i).solo = false;
    }

    layer.solo = true;

    // 添加渲染队列
    var rqItem = app.project.renderQueue.items.add(comp);

    rqItem.timeSpanStart = layer.inPoint;
    rqItem.timeSpanDuration = layer.outPoint - layer.inPoint;

    var om = rqItem.outputModule(1);

    try {
        om.applyTemplate("Lossless");
    } catch (e) {
        return false;
    }

    // 时间戳
    var now = new Date();

    var timeStr =
        now.getFullYear() +
        ("0" + (now.getMonth() + 1)).slice(-2) +
        ("0" + now.getDate()).slice(-2) + "_" +
        ("0" + now.getHours()).slice(-2) +
        ("0" + now.getMinutes()).slice(-2) +
        ("0" + now.getSeconds()).slice(-2);

    var name = layer.name.replace(/\.[^\.]+$/, "");

    var outputFile = new File(
        outFolder.fsName +
        "/input_" +
        name +
        "_" +
        timeStr +
        ".mp4"
    );

    om.file = outputFile;

    app.project.renderQueue.render();

    if (!outputFile.exists) {
        return false;
    }

    // 清理 Render Queue
    var rq = app.project.renderQueue;

    for (var r = rq.numItems; r >= 1; r--) {
        try {
            rq.item(r).remove();
        } catch (e) {}
    }

    // 恢复状态
    layer.solo = false;
    comp.openInViewer();

    return true;
}
