function checkAndRunBackgroundRemove() {
    return launchBackgroundRemoveExe(false);
}    

function runBackgroundRemove() {
    return launchBackgroundRemoveExe(true);
}

function RunpngBackgroundRemove() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var targetFolder = new Folder(toolboxFolder.fsName + "/抠图");

    if (!targetFolder.exists) {
        alert("目标文件夹不存在！");
        return false;
    }
    // 检查是否有 PNG 文件
        var files = targetFolder.getFiles(function (f) {
        return f instanceof File;  // 只要是文件就通过
    });

    if (files.length === 0) {
        alert("目标文件夹中没有任何文件！");
        return false;
    }
    // background_remove.exe 路径
    var exeFile = new File(toolboxFolder.fsName + "/抠图/background_remove.exe");
    if (!exeFile.exists) {
        alert("background_remove.exe 不存在！");
        return false;
    }
    // 使用 start /wait 确保 exe 执行完成再返回
    var cmd = 'cmd /c "cd /d "' + targetFolder.fsName + '" && "' + exeFile.fsName + '"';
    system.callSystem(cmd);
    // exe 完成后执行
    one_png();
    IN_OUT();
    return true;
}
