function deleteVideoOnly() {
    try {

        if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }

        var targetFolder = new Folder(
            toolboxFolder.fsName + "/抠图"
        );

        if (!targetFolder.exists) return;

        var videoFiles = targetFolder.getFiles("*.mp4");

        for (var i = 0; i < videoFiles.length; i++) {

            try {
                videoFiles[i].remove();
            } catch (e) {
                $.writeln("删除失败: " + videoFiles[i].fsName);
            }

        }

    } catch (e) {
        $.writeln("deleteVideoOnly 错误: " + e.toString());
    }
}

function Black_Picture() {
    // 获取脚本所在路径
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }

    // 构建目标路径
    var targetFolder = new Folder(toolboxFolder.fsName + "/抠图");
    if (!targetFolder.exists) {
        alert("目标文件夹不存在！");
        return;
    }

    // 获取子文件夹
    var subFolders = targetFolder.getFiles(function(f){ return f instanceof Folder; });

    for (var i = 0; i < subFolders.length; i++) {
        var seqFolder = subFolders[i];

        // 获取图片文件
        var images = seqFolder.getFiles(function(f){
            return f instanceof File && /\.(png|jpg|jpeg)$/i.test(f.name);
        });

        if (images.length === 0) continue;

        // 排序获取最后一张图片
        images.sort(function(a,b){ return a.name > b.name ? 1 : -1; });
        var lastImageFile = images[images.length - 1];

        // 判断是否为黑图（文件小于阈值）
        if (isBlackImage(lastImageFile)) {
            try {
                lastImageFile.remove();
                $.writeln("删除黑图: " + lastImageFile.fsName);
            } catch(e) {
                $.writeln("删除失败: " + lastImageFile.fsName + " 错误:" + e);
            }
        }
    }
}
// 根据文件大小判断黑图
function isBlackImage(file) {
    if (!file.exists) return false;
    // 小于阈值字节数认为是黑图（可调整）
    return file.length < 10000; // 小于1m视为黑图
}

function copyImportAndAddPNGSequencesToTimeline() {
    // 获取脚本所在目录
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var sourceRoot = new Folder(toolboxFolder.fsName + "/抠图");
    if (!sourceRoot.exists) return;

    // 获取 AE 项目保存路径
    if (!app.project.file) return;
    var projectPath = app.project.file.parent.fsName;

    var proj = app.project;
    if (!proj) return;

    // 获取当前合成
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请先选择一个合成！");
        return;
    }

    // 创建或获取 AE 项目内文件夹
    var targetFolder = null;
    for (var i = 1; i <= proj.rootFolder.numItems; i++) {
        var item = proj.rootFolder.item(i);
        if (item instanceof FolderItem && item.name === "工具箱大师抠图") {
            targetFolder = item;
            break;
        }
    }
    if (!targetFolder) targetFolder = proj.items.addFolder("工具箱大师抠图");

    // ---------- 遍历 PNG 序列文件夹 ----------
    var subFolders = sourceRoot.getFiles(function(f){ return f instanceof Folder; });
    for (var i = 0; i < subFolders.length; i++) {
        var folder = subFolders[i];

        // ✳️ 忽略名称为 "_internal" 的文件夹
        if (folder.name.toLowerCase() === "_internal") {
            continue;
        }

        var destFolder = new Folder(projectPath + "/" + folder.name);
        if (!destFolder.exists) destFolder.create();

        copyFolderRecursive(folder, destFolder);

        var importedItem = importPNGSequence(destFolder);
        if (importedItem) {
            importedItem.parentFolder = targetFolder;
            addToTimelineAlignInPoint(comp, importedItem);
        }

        removeFolderRecursive(folder);
    }

    // ---------- 辅助函数 ----------
    function copyFolderRecursive(src, dst) {
        var files = src.getFiles();
        for (var i = 0; i < files.length; i++) {
            var f = files[i];
            if (f instanceof Folder) {
                // ✳️ 忽略内部的 "_internal" 子文件夹
                if (f.name.toLowerCase() === "_internal") continue;

                var newFolder = new Folder(dst.fsName + "/" + f.name);
                if (!newFolder.exists) newFolder.create();
                copyFolderRecursive(f, newFolder);
            } else {
                var destFile = new File(dst.fsName + "/" + f.name);
                if (destFile.exists) destFile.remove();
                f.copy(destFile.fsName);
            }
        }
    }

    function removeFolderRecursive(folder) {
        var files = folder.getFiles();
        for (var i = 0; i < files.length; i++) {
            var f = files[i];
            if (f instanceof Folder) {
                // ✳️ 同样跳过删除 "_internal" 文件夹
                if (f.name.toLowerCase() === "_internal") continue;
                removeFolderRecursive(f);
            } else {
                f.remove();
            }
        }
        // 如果当前就是 "_internal"，不删除
        if (folder.name.toLowerCase() !== "_internal") {
            folder.remove();
        }
    }

    function importPNGSequence(folder) {
        var pngFiles = folder.getFiles("*.png");
        if (pngFiles.length === 0) return null;

        var importOptions = new ImportOptions();
        importOptions.file = pngFiles[0];
        importOptions.sequence = true;
        return proj.importFile(importOptions);
    }

    function addToTimelineAlignInPoint(comp, footageItem) {
        var selLayers = comp.selectedLayers;

        var targetStartTime = 0;
        var topLayer = null;

        if (selLayers.length > 0) {
            topLayer = selLayers[0];
            for (var i = 1; i < selLayers.length; i++) {
                if (selLayers[i].index < topLayer.index) {
                    topLayer = selLayers[i];
                }
            }
            targetStartTime = topLayer.inPoint;
        }

        var newLayer = comp.layers.add(footageItem);
        newLayer.startTime = targetStartTime;

        if (topLayer) {
            newLayer.moveBefore(topLayer);
        } else {
            newLayer.moveToBeginning();
        }
    }

    // 取消所有图层的独奏状态
    for (var j = 1; j <= comp.numLayers; j++) {
        comp.layer(j).solo = false;
    }
}

