function one_png() {

    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var sourceRoot = new Folder(
        toolboxFolder.fsName + "/抠图"
    );

    if (!sourceRoot.exists) {
        return;
    }

    if (!app.project.file) {
        return;
    }

    var projectPath = app.project.file.parent.fsName;
    var proj = app.project;

    if (!proj) {
        return;
    }

    var comp = app.project.activeItem;

    if (!(comp instanceof CompItem)) {
        return;
    }

    var targetFolder = null;

    for (var i = 1; i <= proj.rootFolder.numItems; i++) {

        var item = proj.rootFolder.item(i);

        if (
            item instanceof FolderItem &&
            item.name === "工具箱大师抠图"
        ) {
            targetFolder = item;
            break;
        }
    }

    if (!targetFolder) {
        targetFolder = proj.items.addFolder("工具箱大师抠图");
    }

    var pngFiles = sourceRoot.getFiles("*.png");

    if (pngFiles.length === 0) {
        return;
    }

    for (var i = 0; i < pngFiles.length; i++) {

        var pngFile = pngFiles[i];

        // 复制到项目目录
        var destFile = new File(
            projectPath + "/" + pngFile.name
        );

        if (destFile.exists) {
            destFile.remove();
        }

        pngFile.copy(destFile.fsName);

        // 导入 PNG
        var importOptions = new ImportOptions(destFile);
        importOptions.sequence = false;

        var importedItem =
            proj.importFile(importOptions);

        importedItem.parentFolder = targetFolder;

        // 添加到时间线
        addToTimelineAlignInPoint(
            comp,
            importedItem
        );

        // 删除中转站 PNG
        pngFile.remove();
    }

    function addToTimelineAlignInPoint(
        comp,
        footageItem
    ) {

        var selLayers = comp.selectedLayers;
        var targetStartTime = 0;
        var topLayer = null;

        if (selLayers.length > 0) {

            topLayer = selLayers[0];

            for (var i = 1; i < selLayers.length; i++) {

                if (
                    selLayers[i].index <
                    topLayer.index
                ) {
                    topLayer = selLayers[i];
                }
            }

            targetStartTime = topLayer.inPoint;
        }

        var newLayer = comp.layers.add(
            footageItem
        );

        newLayer.startTime = targetStartTime;

        if (topLayer) {
            newLayer.moveBefore(topLayer);
        } else {
            newLayer.moveToBeginning();
        }
    }

    /*
    for (var j = 1; j <= comp.numLayers; j++) {
        comp.layer(j).solo = false;
    }
    */
}

function IN_OUT() {
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;

        if (selectedLayers.length === 1) {
            var layer = selectedLayers[0];
            var layerIndex = layer.index;

            if (layerIndex < comp.numLayers) { // 确保下方有图层
                var belowLayer = comp.layer(layerIndex + 1);

                // 获取下方图层的出点
                var belowOutPoint = belowLayer.outPoint;

                // 将选中图层的出点对齐到下方图层出点
                var duration = layer.outPoint - layer.inPoint; // 当前图层持续时间
                layer.outPoint = belowOutPoint;
                

            } else {
                alert("选中图层下方没有图层");
            }
        } else {
            alert("请选择一个图层");
        }
    } else {
        alert("请先选择一个合成");
    }
}

