function Start4() {
var comp = app.project.activeItem;
if (!(comp instanceof CompItem)) {
return;
}
var selectedLayers = comp.selectedLayers;
if (selectedLayers.length === 0) {
return;
}
// 记录每个图层的入点和起始时间
var originalData = [];
for (var i = 0; i < selectedLayers.length; i++) {
var layer = selectedLayers[i];
originalData.push({
layer: layer,
inPoint: layer.inPoint,
startTime: layer.startTime
});
}
// 调整图层入点
var compStart = comp.displayStartTime;
for (var j = 0; j < selectedLayers.length; j++) {
var layer = selectedLayers[j];
var offset = compStart - layer.inPoint;
layer.startTime += offset;
}
run_Cut();
run_JSX();
// 恢复图层位置
for (var k = 0; k < originalData.length; k++) {
var data = originalData[k];
data.layer.startTime = data.startTime;
}
run_sceneCut();
}

function run_Cut() {
if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
var targetFolder = new Folder(toolboxFolder.fsName + "/场景裁剪");
if (!targetFolder.exists) {
alert("目标文件夹不存在！");
return false;
}
// 检查文件夹是否为空（不限制格式）
var files = targetFolder.getFiles(function(f) {
return f instanceof File; // 只要是文件即可
});
if (files.length === 0) {
alert("目标文件夹中没有任何文件！");
return false;
}
// 检查 Cut.exe 是否存在
var exeFile = new File(targetFolder.fsName + "/Cut.exe");
if (!exeFile.exists) {
alert("Cut.exe 不存在！");
return false;
}
// 构建命令执行 exe（切换到目标目录）
    var cmd = 'cmd /c "cd /d "' + targetFolder.fsName + '" && "' + exeFile.fsName + '"';
system.callSystem(cmd);
return true;
}


function run_JSX() {
// 获取当前脚本所在文件夹
if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
// 目标文件夹路径
var targetFolder = new Folder(toolboxFolder.fsName + "/场景裁剪");
// 检查文件夹是否存在
if (!targetFolder.exists) {
alert("目标文件夹不存在：" + targetFolder.fsName);
return;
}
// 获取文件夹下所有 JSX 文件
var jsxFiles = targetFolder.getFiles("*.jsx");
if (jsxFiles.length === 0) {
alert("目标文件夹中没有 JSX 文件");
return;
}
// 逐个执行 JSX 文件
for (var i = 0; i < jsxFiles.length; i++) {
try {
var file = jsxFiles[i];
$.evalFile(file); // 执行 JSX 文件
} catch (e) {
alert("运行失败：" + file.name + "\n" + e.toString());
}
}
}


function run_sceneCut() {
var comp = app.project.activeItem;
if (comp && comp instanceof CompItem) {
var layers = comp.selectedLayers;
if (layers.length > 0) {
for (var i = 0; i < layers.length; i++) {
var layer = layers[i];
var markers = layer.property("Marker");
var times = [];
// 获取所有标记时间
for (var m = 1; m <= markers.numKeys; m++) {
times.push(markers.keyTime(m));
}
var segments = [];
// 如果没有标记，则整段保留
if (times.length === 0) {
segments.push({ start: layer.inPoint, end: layer.outPoint });
} else {
// 第一段：从图层入点到第一个标记
segments.push({ start: layer.inPoint, end: times[0] });
// 中间段：标记之间
for (var j = 0; j < times.length - 1; j++) {
segments.push({ start: times[j], end: times[j + 1] });
}
// 最后一段：最后一个标记到图层结束
segments.push({ start: times[times.length - 1], end: layer.outPoint });
}
var duplicatedLayers = [];
// 复制图层并裁剪每段，同时删除每段的标记
for (var k = 0; k < segments.length; k++) {
var seg = segments[k];
var newLayer = layer.duplicate();
newLayer.inPoint = seg.start;
newLayer.outPoint = seg.end;
// 删除新图层的标记
var newMarkers = newLayer.property("Marker");
while (newMarkers.numKeys > 0) {
newMarkers.removeKey(1);
}
duplicatedLayers.push(newLayer);
}
// 删除原始图层
layer.remove();
// 保持新生成图层选中
for (var l = 0; l < duplicatedLayers.length; l++) {
duplicatedLayers[l].selected = true;
}
fps();
reverseSelectedLayersOrderVisible();
Delete_jsx();
for (var l = 0; l < duplicatedLayers.length; l++) {
duplicatedLayers[l].selected = false;
}
}
}
}
}

function reverseSelectedLayersOrderVisible() {
var comp = app.project.activeItem;
if (comp && comp instanceof CompItem) {
var selectedLayers = comp.selectedLayers;
if (selectedLayers.length > 0) {
// 复制选中图层数组，避免修改过程中影响原数组
var layersToProcess = selectedLayers.slice();
while (layersToProcess.length > 0) {
// 取消第一个选中图层
layersToProcess[0].selected = false;
// 获取剩下的选中图层
var remainingLayers = [];
for (var i = 0; i < layersToProcess.length; i++) {
if (layersToProcess[i].selected) {
remainingLayers.push(layersToProcess[i]);
}
}
if (remainingLayers.length > 0) {
// 按索引升序排序
remainingLayers.sort(function(a, b) {
return a.index - b.index;
});
// 向上移动
for (var j = 0; j < remainingLayers.length; j++) {
var layer = remainingLayers[j];
var currentIndex = layer.index;
if (currentIndex > 1) {
var previousLayer = comp.layer(currentIndex - 1);
layer.moveBefore(previousLayer);
}
}
}
// 更新 layersToProcess
layersToProcess = remainingLayers;
}
}
}
}

function fps() {
var comp = app.project.activeItem;
if (!(comp instanceof CompItem)) return; // 没有合成则退出
var fps = comp.frameRate;     // 当前合成帧速率
var frameDuration = 1 / fps;  // 一帧的时长
var selectedLayers = comp.selectedLayers;
if (selectedLayers.length === 0) return; // 没选中图层则退出
// 反向遍历，避免删除时索引变化
for (var i = selectedLayers.length - 1; i >= 0; i--) {
var layer = selectedLayers[i];
var duration = layer.outPoint - layer.inPoint; // 图层时长
if (duration < frameDuration) {
layer.remove(); // 删除不足1帧的图层
}
}
}

function Delete_jsx() {
if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
var targetFolder = new Folder(toolboxFolder.fsName + "/场景裁剪/");
if (targetFolder.exists) {
// 获取该目录下所有 .jsx 文件
var jsxFiles = targetFolder.getFiles("*.jsx");
for (var i = 0; i < jsxFiles.length; i++) {
var file = jsxFiles[i];
if (file instanceof File && file.exists) {
try {
file.remove(); // 删除文件
// $.writeln("已删除：" + file.fsName);
} catch (e) {
$.writeln("删除失败：" + file.fsName + "，错误：" + e.toString());
}
}
}
} else {
$.writeln("目标文件夹不存在：" + targetFolder.fsName);
}
}

