function restoreWorkArea() {
    var comp = app.project.activeItem;
    if (comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length > 0) {
            var compDuration = comp.duration;
            comp.workAreaStart = 0;
            comp.workAreaDuration = compDuration;
            // 关闭选定图层的 Solo
            for (var i = 0; i < selectedLayers.length; i++) {
                selectedLayers[i].solo = false;
            }
        }
    }
};

function moveAndImportMediaFiles() {
    // 获取脚本所在目录
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    // 工具箱大师中转站/转mp4 文件夹路径
    var sourceFolder = new Folder(toolboxFolder.fsName + "/场景裁剪");
    if (!sourceFolder.exists) return; // 文件夹不存在则直接返回
    // 获取 .mp4 和 .wav 文件
    var mediaFiles = sourceFolder.getFiles(function(f) {
        return f instanceof File && (f.name.match(/\.mp4$/i) || f.name.match(/\.wav$/i));
    });
    if (mediaFiles.length === 0) return; // 没有文件则直接返回
    // 获取项目保存路径
    if (!app.project.file) return; // 项目未保存则直接返回
    var projectPath = app.project.file.parent.fsName;
    // 获取当前激活合成
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return; // 没有合成则直接返回
    // 清除已有的选择
    for (var j = 1; j <= comp.layers.length; j++) {
        comp.layers[j].selected = false;
    }
    var newLayers = [];
    for (var i = 0; i < mediaFiles.length; i++) {
        var file = mediaFiles[i];
        var destFile = new File(projectPath + "/" + file.name);
        // 覆盖已存在的同名文件
        if (destFile.exists) destFile.remove();
        // 复制到工程目录
        if (file.copy(destFile.fsName)) {
            file.remove(); // 移动成功则删除原文件
            // 导入到 AE 项目
            var importOpts = new ImportOptions(destFile);
            if (importOpts.canImportAs(ImportAsType.FOOTAGE)) {
                importOpts.importAs = ImportAsType.FOOTAGE;
            }
            var imported = app.project.importFile(importOpts);
            // 放到时间线开头（0秒处）
            if (imported) {
                var layer = comp.layers.add(imported);
                layer.startTime = 0; // 起始帧（0秒）
                newLayers.push(layer); // 记录新图层
            }
        }
    }
    // 选中新图层
    for (var k = 0; k < newLayers.length; k++) {
        newLayers[k].selected = true;
    }
    if (comp && newLayers.length > 0) {
        var selectedLayers = comp.selectedLayers.slice();
        // 清除选择
        for (var j = 1; j <= comp.numLayers; j++) {
            comp.layer(j).selected = false;
        }
        // 按 index 从小到大（最上层开始）
        selectedLayers.sort(function (a, b) {
            return b.index - a.index;
        });
        for (var i = 0; i < selectedLayers.length; i++) {
            selectedLayers[i].selected = true;
        }
    }
}




