//重复帧删除
    function check_chunk(cur_frame, prev_frame, chunk) {
        var cr = Math.abs(cur_frame[chunk][0] - prev_frame[chunk][0]);
        var cg = Math.abs(cur_frame[chunk][1] - prev_frame[chunk][1]);
        var cb = Math.abs(cur_frame[chunk][2] - prev_frame[chunk][2]);
        var res = cr + cg + cb;
        return res;
    }

    function checkRGB(cur_frame, prev_frame, acc) {
        var sum = 0;
        var i = 0;
        while (i < acc) {
            sum += check_chunk(cur_frame, prev_frame, i);
            i++;
        }
        return sum;
    }
