function Finallytime() {
    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) return;
    var layers = comp.selectedLayers;
    if (layers.length === 0) return;
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        if (!layer.canSetTimeRemapEnabled) continue;
        if (!layer.timeRemapEnabled) {
            layer.timeRemapEnabled = true;
        }
        var remap = layer.property("ADBE Time Remapping");
        if (!remap) continue;
        // 删除最后一个关键帧（通常位于出点）
        if (remap.numKeys >= 2) {
            remap.removeKey(remap.numKeys);
        }
    }
};

function Frame() {
    if (!checkComp()) {
        return false;
    }
    Delete_KEY.active = true;
    Delete_KEY.active = false;

    app.beginUndoGroup("process");
    app.executeCommand(19);
    app.executeCommand(20);

    // 保存原选中的图层
    var comp = app.project.activeItem;
    var originalSelected = comp ? comp.selectedLayers.slice() : [];

    // 进度条
    var bar = new Window("palette", "working...", undefined);
    var progressbar = bar.add("progressbar", undefined, "");
    progressbar.value = 0;
    bar.center();
    bar.show();
    bar.update();

    var item = app.project.activeItem;
    var selected = item.selectedLayers;
    var width = item.width;
    var height = item.height;

    var same_pixels = 0;
    var skips = 0;
    var div = 100 / selected.length;
    var frameDuration = item.frameDuration;

    // 精度判断
    if (dropdown1.selection == 1) {
        acc = 2;
        treshhold1 = 2;
        treshhold2 = 1;
    } else {
        acc = 4;
        treshhold1 = 5;
        treshhold2 = 4;
    }

    var layer_names = new Array(selected.length);

    // 随机重命名图层避免表达式冲突
    for (var i = 0; i < selected.length; i++) {
        var name = selected[i].name;
        layer_names[i] = name;
        var rand = rng(100, 10000);
        selected[i].name = "...removing duplicates...(" + rand + ")";
    }

    // 主循环
    for (var i = 0; i < selected.length; i++) {

        var outPoint = selected[i].outPoint;
        var inPoint = selected[i].inPoint;

        selected[i].timeRemapEnabled = false;
        selected[i].timeRemapEnabled = true;

        var prev_frame = new Array(acc);
        var found = 0;

        selected[i].property("ADBE Time Remapping").addKey(inPoint);

        var rText = item.layers.addText(); rText.enabled = false;
        var gText = item.layers.addText(); gText.enabled = false;
        var bText = item.layers.addText(); bText.enabled = false;

        // 遍历每帧
        for (var j = 0; j < ((outPoint - inPoint) / frameDuration) - frameDuration; j++) {

            progressbar.value += (div / ((outPoint - inPoint) / frameDuration));
            bar.update();

            var cur_frame = new Array(acc);
            var pos = 0;
            var curTime = inPoint + (frameDuration * j);

            item.time = curTime;

            // 跳帧逻辑
            if (group2.checkbox2.value == 1 && j > 0 && found) {
                j++;
                curTime = inPoint + (frameDuration * j);
                item.time = curTime;
                progressbar.value += (div / ((outPoint - inPoint) / frameDuration));
                bar.update();
                found = 0;
                skips++;
            }

            if (curTime >= outPoint) break;

            var w_sp = (width / acc) / 2;

            for (var w = (width / acc) / 2; w < width; w += (width / acc)) {
                var h = height / 2;

                rText.property("Source Text").expression =
                    "targetLayer=thisComp.layer('" + selected[i].name +
                    "');samplePoint=[" + w + "," + h +
                    "];sampleRadius=[" + w_sp + "," + h +
                    "];s=255*targetLayer.sampleImage(samplePoint,sampleRadius);Math.round(s[0])";

                gText.property("Source Text").expression =
                    "targetLayer=thisComp.layer('" + selected[i].name +
                    "');samplePoint=[" + w + "," + h +
                    "];sampleRadius=[" + w_sp + "," + h +
                    "];s=255*targetLayer.sampleImage(samplePoint,sampleRadius);Math.round(s[1])";

                bText.property("Source Text").expression =
                    "targetLayer=thisComp.layer('" + selected[i].name +
                    "');samplePoint=[" + w + "," + h +
                    "];sampleRadius=[" + w_sp + "," + h +
                    "];s=255*targetLayer.sampleImage(samplePoint,sampleRadius);Math.round(s[2])";

                var r = parseInt(rText.property("Source Text").value);
                var g = parseInt(gText.property("Source Text").value);
                var b = parseInt(bText.property("Source Text").value);

                cur_frame[pos] = [r, g, b];
                pos++;
            }

            if (j != 0) {
                var checkresult = checkRGB(cur_frame, prev_frame, acc);

                for (var x = 0; x < acc; x++) {
                    if (check_chunk(cur_frame, prev_frame, x) == 0) {
                        same_pixels++;
                    }
                }

                if (same_pixels != acc && checkbox1.value) {
                    selected[i].property("ADBE Time Remapping").addKey(curTime);
                    prev_frame = cur_frame.slice();
                    skips = 0;
                    found = 1;
                } else if (same_pixels != acc && !checkbox1.value && checkresult >= treshhold1) {
                    selected[i].property("ADBE Time Remapping").addKey(curTime);
                    prev_frame = cur_frame.slice();
                    skips = 0;
                    found = 1;
                } else if (same_pixels == acc && checkresult >= treshhold1) {
                    selected[i].property("ADBE Time Remapping").addKey(curTime);
                    prev_frame = cur_frame.slice();
                    skips = 0;
                    found = 1;
                } else if (skips >= 2 && checkresult >= treshhold2) {
                    selected[i].property("ADBE Time Remapping").addKey(curTime);
                    prev_frame = cur_frame.slice();
                    skips = 0;
                    found = 1;
                } else {
                    skips++;
                    found = 0;
                }

            } else {
                prev_frame = cur_frame.slice();
                found = 0;
            }

            same_pixels = 0;
        }

        // ============================
        //   ⭐ 修复：最后一帧合并问题 ⭐
        // ============================
        var prop = selected[i].property("ADBE Time Remapping");
        var numKeys = prop.numKeys;
        var timeAdd = frameDuration;
        var start = 2;

        if (prop.keyTime(1) == selected[i].inPoint) {
            start--;
        }

        // 重排除头尾之外的关键帧
        for (var z = start; z < numKeys - 1; z++) {
            var val = prop.keyValue(z + 1);
            prop.removeKey(z + 1);
            prop.setValueAtTime(inPoint + timeAdd, [val]);
            timeAdd += frameDuration;
        }

        // ⭐ 强制处理 AE 自动尾帧 ⭐
        var lastKeyIndex = prop.numKeys;
        var lastKeyTime = prop.keyTime(lastKeyIndex);
        var lastKeyValue = prop.keyValue(lastKeyIndex);

        if (lastKeyTime >= outPoint - frameDuration * 0.5) {
            prop.removeKey(lastKeyIndex);
            prop.setValueAtTime(inPoint + timeAdd, lastKeyValue);
            timeAdd += frameDuration;
        }

        selected[i].outPoint = inPoint + timeAdd;

        // 删除临时文本层
        item.layer(1).remove();
        item.layer(1).remove();
        item.layer(1).remove();
    }

    // 恢复图层名称
    for (var i = 0; i < selected.length; i++) {
        selected[i].name = layer_names[i];
    }

    bar.close();

    // 恢复原选中图层
    for (var i = 0; i < originalSelected.length; i++) {
        try { originalSelected[i].selected = true; } catch(e) {}
        deleteLastFrameOfSelectedLayers();
    }
    app.endUndoGroup();
    app.activate();
}

function deleteLastFrameOfSelectedLayers() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    var fps = comp.frameRate;
    var selectedLayers = comp.selectedLayers;
    if (!selectedLayers || selectedLayers.length === 0) return;
    // 每帧时长
    var frameDur = 1 / fps;
    for (var i = 0; i < selectedLayers.length; i++) {
        var lyr = selectedLayers[i];
        // 删除最后 1 帧（缩短 outPoint）
        lyr.outPoint = lyr.outPoint - frameDur;
    }
}

