    function run_Image_RIFE(){
  var comp = app.project.activeItem;
  /*
    if (!(comp instanceof CompItem)) {
        alert("请先打开一个合成！");
        return;
    }
*/
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请先选中一个图层！");
        return;
    }

    var originalTime = comp.time;

    try {
        comp.time = originalTime;

        var scale = scaleDropdown.selection.text.replace("x", "");
        var noise = noiseLevelDropdown.selection.text;

        if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
        var basePath = toolboxFolder.fsName + "/提升画质";

        var baseFolderObj = new Folder(basePath);
        if (!baseFolderObj.exists) {
            alert("基础目录不存在！");
            return;
        }

        // ======================== 1. 生成 BAT ========================
        var batPath = basePath + "/realcugan_run.bat";
        var batFile = new File(batPath);

        batFile.encoding = "GB2312";
        batFile.open("w");

        batFile.writeln("@echo off");
            batFile.writeln("net session >nul 2>&1");
batFile.writeln("if %errorlevel% neq 0 (");
batFile.writeln("    powershell -Command \"Start-Process '%~f0' -Verb RunAs\"");
batFile.writeln("    exit");
batFile.writeln(")");
        batFile.writeln("cd /d %~dp0");
        batFile.writeln("(");
        batFile.writeln("echo " + scale);
        batFile.writeln("echo " + noise);
        batFile.writeln(") | realcugan_run.exe");
        batFile.writeln("exit");

        batFile.close();

        new File(batPath).execute();

        // ======================== 获取最新 output 文件夹 ========================
        function getLatestOutputFolder(path) {
            var base = new Folder(path);
            if (!base.exists) return null;

            var files = base.getFiles();
            var latestFolder = null;
            var latestTime = 0;

            for (var i = 0; i < files.length; i++) {
                var f = files[i];

                if (f instanceof Folder && f.name.indexOf("output_") === 0) {
                    var t = f.modified.getTime();
                    if (t > latestTime) {
                        latestTime = t;
                        latestFolder = f;
                    }
                }
            }

            return latestFolder;
        }

        // ======================== 2. 等待 output 文件夹 ========================
        var outputFolder = null;
        var waitFolderCount = 0;
        var maxWaitFolder = 120;

        while (!outputFolder && waitFolderCount < maxWaitFolder) {

            $.sleep(1000);
            waitFolderCount++;

            // ❗basePath 被删除检测
            if (!new Folder(basePath).exists) {
                alert("基础目录已被删除，任务终止！");
                return;
            }

            outputFolder = getLatestOutputFolder(basePath);
        }

        if (!outputFolder) {
            alert("未检测到 output_ 文件夹！");
            return;
        }

        // ======================== 3. 等待 done.txt ========================
        var doneFile = new File(outputFolder.fsName + "/done.txt");

        var maxWait = 60 * 60;
        var waitCount = 0;

        while (!doneFile.exists && waitCount < maxWait) {

            $.sleep(1000);
            waitCount++;

            // ❗output 文件夹被删除检测（关键）
            if (!outputFolder || !outputFolder.exists) {
                alert("检测到 output 文件夹已被删除，任务终止！");
                return;
            }

            // 更新最新 output 文件夹（防止 exe 延迟创建）
            var newFolder = getLatestOutputFolder(basePath);
            if (newFolder && newFolder.exists) {
                outputFolder = newFolder;
                doneFile = new File(outputFolder.fsName + "/done.txt");
            }
        }

        if (doneFile.exists) {
            Rename_video();
        } else {
            alert("等待 done.txt 超时！");
        }

    } catch (e) {
        alert("发生错误：" + e.toString());
    }
};

function Image_RIFE() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;
    if (layers.length === 0) return;

    // ===== 保存原状态 =====
    $.global.__originComp__ = comp;
    $.global.__originLayerIndex__ = [];

    for (var i = 0; i < layers.length; i++) {
        $.global.__originLayerIndex__.push(layers[i].index);
    }

    // ===== 计算时间范围 =====
    var minIn = layers[0].inPoint;
    var maxOut = layers[0].outPoint;

    for (var i = 1; i < layers.length; i++) {
        var l = layers[i];
        if (l.inPoint < minIn) minIn = l.inPoint;
        if (l.outPoint > maxOut) maxOut = l.outPoint;
    }

    // ===== 创建临时合成 =====
    var newComp = app.project.items.addComp(
        "Temp_Comp",
        1920,
        1080,
        comp.pixelAspect,
        comp.duration,
        comp.frameRate
    );

    // ===== 排序 =====
    var indices = [];
    for (var i = 0; i < layers.length; i++) {
        indices.push(layers[i].index);
    }
    indices.sort(function (a, b) { return a - b; });

    // ===== 复制图层 =====
    for (var i = 0; i < indices.length; i++) {
        var src = comp.layer(indices[i]);
        var dst = newComp.layers.add(src.source);

        dst.startTime = src.startTime;
        dst.inPoint = src.inPoint;
        dst.outPoint = src.outPoint;

        try {
            var sp = src.property("Transform");
            var dp = dst.property("Transform");

            var props = ["Position", "Scale", "Rotation", "Opacity", "Anchor Point"];

            for (var p = 0; p < props.length; p++) {
                var s = sp.property(props[p]);
                var d = dp.property(props[p]);

                if (s && d) {
                    if (s.numKeys > 0) {
                        for (var k = 1; k <= s.numKeys; k++) {
                            d.setValueAtTime(s.keyTime(k), s.keyValue(k));
                        }
                    } else {
                        d.setValue(s.value);
                    }
                }
            }
        } catch (e) {}
    }

    // ===== 修剪 =====
    newComp.workAreaStart = minIn;
    newComp.workAreaDuration = maxOut - minIn;

    for (var i = 1; i <= newComp.numLayers; i++) {
        newComp.layer(i).startTime -= minIn;
    }

    newComp.duration = maxOut - minIn;
    newComp.workAreaStart = 0;

    // ===== 打开新合成 =====
    newComp.openInViewer();

    // ===== 外部函数 =====
    syncWorkAreaToComp();
    app.executeCommand(2156);
    Delete_the_render();
     frame_by_frame();

    // ===== 延迟删除 + 返回原合成 =====
    $.global.__deleteTempComp__ = function () {
        try {
            newComp.remove();
        } catch (e) {}

        // ===== 返回原合成 =====
        var origin = $.global.__originComp__;
        if (origin) {
            origin.openInViewer();

            // 恢复选择
            var idxs = $.global.__originLayerIndex__ || [];
            for (var i = 1; i <= origin.numLayers; i++) {
                origin.layer(i).selected = false;
            }
            for (var j = 0; j < idxs.length; j++) {
                try {
                    origin.layer(idxs[j]).selected = true;
              //      openPrecompAndSelectAll();
                    origin.layer(idxs[j]).selected = true;
            //       runRIFEA();
                } catch (e) {}
            }
        }
    };
    app.scheduleTask("__deleteTempComp__()", 500, false);
}
    
function Rename_video() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var baseFolder = new Folder(toolboxFolder.fsName + "/提升画质");
    if (baseFolder.exists) {
        var folders = baseFolder.getFiles(function(f) {
            return f instanceof Folder && /^output_\d{8}_\d{6}$/.test(f.name);
        });
        if (folders.length > 0) {
            var targetFolder = folders[0];
            // 重命名为 video
            targetFolder.rename("video");
            // 重命名后的 video 文件夹
            var videoFolder = new Folder(baseFolder.fsName + "/video");
            if (videoFolder.exists) {
                // 删除 done.txt
                var doneFile = new File(videoFolder.fsName + "/done.txt");
                if (doneFile.exists) {
                    doneFile.remove();
                }
                // 获取图片文件
                var movedFiles = videoFolder.getFiles(function(f) {
                    return f instanceof File && /\.(png|jpg|jpeg)$/i.test(f.name);
                });
                // 按名称排序
                movedFiles.sort(function(a, b) {
                    return a.name > b.name ? 1 : -1;
                });
                if (movedFiles.length > 0) {
                    // 获取最后一帧
                    var lastFrame = movedFiles[movedFiles.length - 1];
                    var fileSize = lastFrame.length;
                    // ≤1MB 删除
                    if (fileSize <= 1 * 1024 * 1024) {
                        $.writeln("最后一帧小于等于1MB，删除：" + lastFrame.name);
                        lastFrame.remove();
                    } else {
                        $.writeln("最后一帧大于1MB，保留：" + lastFrame.name);
                    }
                }
                // =========================
                // 移动到 补帧 文件夹
                // =========================
                var targetBase = new Folder(toolboxFolder.fsName + "/补帧");
                if (!targetBase.exists) {
                    targetBase.create();
                }
                var targetPath = targetBase.fsName + "/video";
                // 如果目标 video 已存在先删除
                var oldVideo = new Folder(targetPath);
                if (oldVideo.exists) {
                    oldVideo.remove();
                }
                // 移动文件夹
                videoFolder.rename(targetPath);
                 RIFE2(); 
                 app.executeCommand(2156);//适合画面
                 deselectProjectItems();
            }
        }
    }
}

function RIFE2() {
    var modelIndex = RIFEDropdown1.selection.index + 1;
    var map = {
        2: 1,
        4: 2,
        8: 3,
        16: 4
    };
    var f = parseInt(
        RIFEDropdown2.selection.text,
        10
    );
    var factor = map[f] || 1;
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var inputPath =
        toolboxFolder.fsName +
        "/补帧";
    // =========================
    // 创建 BAT
    // =========================
    var batPath = inputPath + "/补帧.bat";
    var batFile = new File(batPath);
    batFile.encoding = "GB2312";
    batFile.open("w");
    batFile.writeln("@echo off");
        batFile.writeln("net session >nul 2>&1");
batFile.writeln("if %errorlevel% neq 0 (");
batFile.writeln("    powershell -Command \"Start-Process '%~f0' -Verb RunAs\"");
batFile.writeln("    exit");
batFile.writeln(")");
    batFile.writeln("cd /d %~dp0");
    batFile.writeln("(");
    batFile.writeln("echo " + modelIndex);
    batFile.writeln("echo " + factor);
    batFile.writeln(") | RIFE.exe");
    batFile.writeln("exit");
    batFile.close();
    // =========================
    // 执行 BAT
    // =========================
    new File(batPath).execute();
 $.sleep(6000);
    // =========================
    // 实时监测 video 文件夹
    // =========================
    var videoFolder = new Folder(
        inputPath + "/video"
    );
    while (true) {
        // 文件夹不存在
        if (!videoFolder.exists) {
            moveAndImportMP4Files2();
            break;
        }
        // 每秒检测一次
        $.sleep(1000);
    }
}


