var MergeKeyButton = timeBOX1.add("button", [0, 0, 50, 20], "合并帧");
var DeleteKeyButton = timeBOX1.add("button", [0, 0, 50, 20], "删除帧");
var BTN= timeBOX.add("button", [0, 0, 100, 20], "头尾帧裁剪");
DeleteKeyButton.onClick = function () {
    Delete_KEY2();
    }

    function checkComp() {
        if (app.project.activeItem == null || !(app.project.activeItem instanceof CompItem)) {
            alert("No comp selected");
            return false;
        } else {
            if (app.project.activeItem.selectedLayers.length == 0) {
                alert("Please select at least one layer");
                return false;
            }
        }
        return true;
    }

    function rng(x, y) {
        var num = Math.floor(generateRandomNumber() * ((y - x) + 1)) + x;
        return num;
    }

function Delete_KEY2() {
    if (!checkComp()) {
        return false;
    }
    app.beginUndoGroup("删除当前时间指示器关键帧");
    var comp = app.project.activeItem;
    var layers = comp.selectedLayers;
    var currentTime = comp.time; // 当前时间指示器
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var prop = layer.property("ADBE Time Remapping");
        if (!prop || prop.numKeys === 0) continue;
        var frameDuration = comp.frameDuration;
        var tolerance = frameDuration / 2; // 误差范围
        // 倒序删除（防止索引错位）
        for (var k = prop.numKeys; k >= 1; k--) {
            var keyTime = prop.keyTime(k);

            if (Math.abs(keyTime - currentTime) < tolerance) {
                prop.removeKey(k);
                break; // 只删一个
            }
        }
    }
MergeKey();
    app.endUndoGroup();
};

function MergeKey() {
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length < 1) {
            alert("没有选中任何图层。");
            return;
        }
        
        for (var j = 0; j < selectedLayers.length; j++) {
            var layer = selectedLayers[j];
            var timeRemapProperty = layer.property("ADBE Time Remapping");
            if (!timeRemapProperty || timeRemapProperty.numKeys < 2) {
                continue;
            }
            
            var keyframes = [];
            for (var i = 1; i <= timeRemapProperty.numKeys; i++) {
                var keyTime = timeRemapProperty.keyTime(i);
                if (layer.inPoint <= keyTime && keyTime <= layer.outPoint) {
                    keyframes.push(i);
                }
            }
            
            if (keyframes.length < 1) {
                continue;
            }
            
            var firstKeyframeTime = Math.max(timeRemapProperty.keyTime(keyframes[0]), layer.inPoint);
            var frameCounter = 0;

            for (var i = 0; i < keyframes.length; i++) {
                var keyIndex = keyframes[i];
                var keyframeValue = timeRemapProperty.keyValue(keyIndex);
                timeRemapProperty.removeKey(keyIndex);
                timeRemapProperty.setValueAtTime(firstKeyframeTime + (frameCounter / comp.frameRate), keyframeValue);
                frameCounter++;
            }
            layer.outPoint = firstKeyframeTime + (frameCounter / comp.frameRate);
        }
    }
};

