//预合成2
preCompose.onClick = function () {
    app.beginUndoGroup("Precompose Selected Layers");
    try {
        SinglePrecomp(EDTpreComp.text); // 使用输入框中的文本作为名称
    } catch (e) {
        alert("Error: " + e.toString());
    }
    
    function SinglePrecomp(precompName) {
        function precomposeSelectedLayers() {
            var comp = app.project.activeItem;
            if (!(comp && comp instanceof CompItem)) {
                alert("请选当前合成");
                return;
            }
            if (comp.selectedLayers.length === 0) {
                return;
            }
            var selectedLayers = comp.selectedLayers;
            var layerIndices = [];
            var topmostLayerIndex = comp.numLayers;
            for (var i = 0; i < selectedLayers.length; i += 1) {
                layerIndices.push(selectedLayers[i].index);
                if (selectedLayers[i].index < topmostLayerIndex) {
                    topmostLayerIndex = selectedLayers[i].index;
                }
            }
            var minInPoint = comp.layer(layerIndices[0]).inPoint;
            var maxOutPoint = comp.layer(layerIndices[0]).outPoint;
            for (var i = 0; i < layerIndices.length; i += 1) {
                var layer = comp.layer(layerIndices[i]);
                if (layer.inPoint < minInPoint) {
                    minInPoint = layer.inPoint;
                }
                if (layer.outPoint > maxOutPoint) {
                    maxOutPoint = layer.outPoint;
                }
            }
            var duration = maxOutPoint - minInPoint;
            var baseName = precompName || "预合成"; // 使用输入框内容作为名称
            var index = 1;
            while (true) {
                var finalName = baseName + " " + index;
                var existingComp = null;
                for (var i = 1; i <= app.project.items.length; i += 1) {
                    if (app.project.item(i) instanceof CompItem && app.project.item(i).name === finalName) {
                        existingComp = app.project.item(i);
                        break;
                    }
                }
                if (!existingComp) {
                    break;
                }
                index++;
            }

            var precomp = comp.layers.precompose(layerIndices, finalName, true);
            precomp.frameRate = comp.frameRate;
            precomp.duration = duration;

            var minInPointInPrecomp = Infinity;
            for (var j = 1; j <= precomp.numLayers; j += 1) {
                var layerInPrecomp = precomp.layer(j);
                if (layerInPrecomp.inPoint < minInPointInPrecomp) {
                    minInPointInPrecomp = layerInPrecomp.inPoint;
                }
            }
            for (var j = 1; j <= precomp.numLayers; j += 1) {
                var layerInPrecomp = precomp.layer(j);
                layerInPrecomp.startTime -= minInPointInPrecomp;
            }
            var newPrecompLayer = comp.layers.add(precomp);
            newPrecompLayer.moveBefore(comp.layer(topmostLayerIndex + 1));
            newPrecompLayer.startTime = minInPoint;
            if ((newPrecompLayer.index + 1) <= comp.numLayers) {
                comp.layer(newPrecompLayer.index + 1).remove();
            }
        }
        precomposeSelectedLayers();
    }

    app.endUndoGroup();
};

// 解预合成2
DEComposeButton.onClick = function() {
            var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请选中一个合成");
        return;
    }
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请至少选择一个图层");
        return;
    }
    var allLayers = comp.layers;
    // 清除所有图层的选中状态
    for (var i = 1; i <= allLayers.length; i++) {
        allLayers[i].selected = false;
    }
    // 逐个选中并执行操作
    for (var j = 0; j < selectedLayers.length; j++) {
        // 清除之前的选择
        for (var i = 1; i <= allLayers.length; i++) {
            allLayers[i].selected = false;
        }
        var layer = selectedLayers[j];
        layer.selected = true; // 只选中当前一个
        openPrecompAndSelectAll(layer); // 执行操作
    }
};

function openPrecompAndSelectAll() {
    app.beginUndoGroup("解预合成");
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        alert("请先选中一个合成！");
        return;
    }
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请先选中一个预合成图层！");
        return;
    }
    // 检查：如果选择了多个图层，弹出警告并自动取消执行
 /*   if (selectedLayers.length > 1) {
        alert("只能选择一个图层进行解预合成操作！\n要想多个操作请勾选批量解预合成复选框！");
        return; // 取消执行
    }  */
    var precomp = null;
    var originalInPoint = selectedLayers[0].inPoint; // 记录选定图层的入点
    
    for (var i = 0; i < selectedLayers.length; i++) {
        if (selectedLayers[i] instanceof AVLayer && selectedLayers[i].source instanceof CompItem) {
            precomp = selectedLayers[i].source;
            break;
        }
    }
    if (!precomp) {
        alert("选中的图层不是预合成！");
        return;
    }

    selectLayerSource();
    var mainComp = app.project.activeItem;
    precomp.openInViewer();

        for (var j = 1; j <= precomp.numLayers; j++) {
        precomp.layer(j).selected = false;
    }
    for (var j = 1; j <= precomp.numLayers; j++) {
        precomp.layer(j).selected = true;
    }
    app.endUndoGroup();
    app.executeCommand(19); // 复制
    if (mainComp) {
        mainComp.openInViewer();
        app.beginUndoGroup("返回原合成");
        
        app.executeCommand(20); // 粘贴
        var pastedLayers = mainComp.selectedLayers;
        adjustLayersToOriginalInPoint(pastedLayers, originalInPoint);
        
        for (var i = 0; i < pastedLayers.length; i++) {
            pastedLayers[i].selected = false;
            var belowLayer = mainComp.layer(pastedLayers[i].index + 1);
            if (belowLayer) {
                belowLayer.selected = true;
            }
        }
        app.executeCommand(21);
        shanchu();
        app.endUndoGroup();
    }
}

// 调整粘贴图层的最底层图层入点对齐选定图层的入点
function adjustLayersToOriginalInPoint(layers, originalInPoint) {
    if (layers.length < 1) return;
    // 获取最底层图层的入点（即最后一个图层的入点）
    var bottomLayerInPoint = layers[layers.length - 1].inPoint;
  // 计算偏移量
  var offsetAmount = originalInPoint;
  // 调整所有图层的入点
  for (var i = 0; i < layers.length; i++) {
    layers[i].startTime += offsetAmount;
  }
}


// 选中对应图层素材
function selectLayerSource() {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        return;
    }
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        return;
    }
    // 遍历所有选中的图层，优先取消在项目内已选中的素材再选中其对应的素材
    for (var i = 0; i < app.project.numItems; i++) {
        app.project.item(i + 1).selected = false; // 取消在项目内已选中的素材
    }
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        var source = layer.source;
        if (source) {
            source.selected = true;  // 选中对应的素材
        }
    }
}

// 删除项目面板选中项
function shanchu() {
    if (app.project.selection.length > 0) {
        for (var i = app.project.selection.length - 1; i >= 0; i--) {
            deleteItemRecursively(app.project.selection[i]);
        }
    }
}

// 递归删除项目中的项
function deleteItemRecursively(item) {
    if (item instanceof FolderItem) {
        for (var i = item.numItems; i >= 1; i--) {
            deleteItemRecursively(item.item(i));
        }
    }
    item.remove();
}
    


