// 提升画质
exportBtn.onClick = function () {

    var comp = app.project.activeItem;
    if (!(comp instanceof CompItem)) {
        alert("请先打开一个合成！");
        return;
    }

    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length === 0) {
        alert("请先选中一个图层！");
        return;
    }

    var originalTime = comp.time;

    try {

        app.executeCommand(5);
            app.executeCommand(2566); // 独显
        frame_by_frame();
    app.executeCommand(2566); // 独显
        comp.time = originalTime;

        var scale = scaleDropdown.selection.text.replace("x", "");
        var noise = noiseLevelDropdown.selection.text;

        if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
        var basePath = toolboxFolder.fsName + "/提升画质";

        var baseFolderObj = new Folder(basePath);
        if (!baseFolderObj.exists) {
            alert("基础目录不存在！");
            return;
        }

        // ======================== 1. 生成 BAT ========================
        var batPath = basePath + "/realcugan_run.bat";
        var batFile = new File(batPath);

        batFile.encoding = "GB2312";
        batFile.open("w");

        batFile.writeln("@echo off");
            batFile.writeln("net session >nul 2>&1");
batFile.writeln("if %errorlevel% neq 0 (");
batFile.writeln("    powershell -Command \"Start-Process '%~f0' -Verb RunAs\"");
batFile.writeln("    exit");
batFile.writeln(")");
        batFile.writeln("cd /d %~dp0");
        batFile.writeln("(");
        batFile.writeln("echo " + scale);
        batFile.writeln("echo " + noise);
        batFile.writeln(") | realcugan_run.exe");
        batFile.writeln("exit");

        batFile.close();

        new File(batPath).execute();

        // ======================== 获取最新 output 文件夹 ========================
        function getLatestOutputFolder(path) {
            var base = new Folder(path);
            if (!base.exists) return null;

            var files = base.getFiles();
            var latestFolder = null;
            var latestTime = 0;

            for (var i = 0; i < files.length; i++) {
                var f = files[i];

                if (f instanceof Folder && f.name.indexOf("output_") === 0) {
                    var t = f.modified.getTime();
                    if (t > latestTime) {
                        latestTime = t;
                        latestFolder = f;
                    }
                }
            }

            return latestFolder;
        }

        // ======================== 2. 等待 output 文件夹 ========================
        var outputFolder = null;
        var waitFolderCount = 0;
        var maxWaitFolder = 120;

        while (!outputFolder && waitFolderCount < maxWaitFolder) {

            $.sleep(1000);
            waitFolderCount++;

            // ❗basePath 被删除检测
            if (!new Folder(basePath).exists) {
                alert("基础目录已被删除，任务终止！");
                return;
            }

            outputFolder = getLatestOutputFolder(basePath);
        }

        if (!outputFolder) {
            alert("未检测到 output_ 文件夹！");
            return;
        }

        // ======================== 3. 等待 done.txt ========================
        var doneFile = new File(outputFolder.fsName + "/done.txt");

        var maxWait = 60 * 60;
        var waitCount = 0;

        while (!doneFile.exists && waitCount < maxWait) {

            $.sleep(1000);
            waitCount++;

            // ❗output 文件夹被删除检测（关键）
            if (!outputFolder || !outputFolder.exists) {
                alert("检测到 output 文件夹已被删除，任务终止！");
                return;
            }

            // 更新最新 output 文件夹（防止 exe 延迟创建）
            var newFolder = getLatestOutputFolder(basePath);
            if (newFolder && newFolder.exists) {
                outputFolder = newFolder;
                doneFile = new File(outputFolder.fsName + "/done.txt");
            }
        }

        if (doneFile.exists) {
            moveImageSequenceFolders();
        } else {
            alert("等待 done.txt 超时！");
        }

    } catch (e) {
        alert("发生错误：" + e.toString());
    }
};

function frame_by_frame() {
    // ========= 导出目录 =========
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var folderExport = new Folder(toolboxFolder.fsName + "/提升画质");
    if (!folderExport.exists) folderExport.create();

    // ========= 获取当前合成 =========
    if (!(app.project.activeItem instanceof CompItem)) {
        alert("没有激活的合成");
        return;
    }
    var comp = app.project.activeItem;

    // ========= 记录时间指示器当前位置 =========
    var originalTime = comp.time;

    // ========= 获取选中图层 =========
    if (comp.selectedLayers.length === 0) {
        alert("请先选中一个图层");
        return;
    }
    var layer = comp.selectedLayers[0];

    // ========= 帧参数 =========
    var frameDuration = comp.frameDuration;
    var startTime = layer.inPoint;
    var endTime = layer.outPoint;

    // ========= 计算目标帧数（包含首帧） =========
    var targetCount = Math.floor((endTime - startTime) / frameDuration) + 1;
    if (targetCount <= 0) {
        alert("目标帧数为 0");
        return;
    }

    // ========= 清空旧 PNG =========
    var oldFiles = folderExport.getFiles("*.png");
    for (var i = 0; i < oldFiles.length; i++) {
        oldFiles[i].remove();
    }

    // ========= 创建进度条 =========
    var win = new Window("palette", "导出进度", undefined);
        win.progressText = win.add("statictext",  [20, 20, 300, 40], "0 / " + targetCount);
    win.progressBar = win.add("progressbar", [20, 20, 300, 40], 0, targetCount);
    win.show();

    // ========= 逐帧导出 PNG =========
    for (var i = 0; i < targetCount; i++) {
        var t = startTime + i * frameDuration;
        if (t > endTime + 0.00001) break;
        comp.time = t;

        // ===== 新命名方式 =====
        var file = new File(
            folderExport.fsName + "/input_" + ("00000" + i).slice(-5) + ".png"
        );

        try {
            comp.saveFrameToPng(t, file);
        } catch (e) {}

        // ========= 等待写入完成 =========
        var waitCount = 0;
        while (!file.exists) {
            $.sleep(50);
            waitCount++;
            if (waitCount > 200) break;
        }

        win.progressBar.value = i + 1;
        win.progressText.text = (i + 1) + " / " + targetCount;
        win.update();
    }

    // ========= 恢复时间指示器 =========
    comp.time = originalTime;

    win.close();
}



function moveImageSequenceFolders() {
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var sourceFolder = new Folder(toolboxFolder.fsName + "/提升画质");
    if (!sourceFolder.exists) {
        alert("源文件夹不存在：" + sourceFolder.fsName);
        return;
    }
    if (app.project.file == null) {
        alert("当前工程尚未保存，请先保存工程。");
        return;
    }
    var projectFolder = app.project.file.parent;
    // 获取当前活动合成
    if (!(app.project.activeItem && app.project.activeItem instanceof CompItem)) {
        alert("请先选择一个合成！");
        return;
    }
    var comp = app.project.activeItem;
    // 选择的图层，用于放置在其上方
    var selectedLayers = comp.selectedLayers;
    var targetLayer = selectedLayers.length > 0 ? selectedLayers[0] : null;
    // 项目面板中目标文件夹
    var toolboxFolderName = "工具箱大师提升画质";
   // var toolboxFolder = null;
    for (var i = 1; i <= app.project.rootFolder.numItems; i++) {
        var item = app.project.rootFolder.item(i);
        if (item instanceof FolderItem && item.name === toolboxFolderName) {
            toolboxFolder = item;
            break;
        }
    }
    if (!toolboxFolder) {
        toolboxFolder = app.project.items.addFolder(toolboxFolderName);
    }
    var subFolders = sourceFolder.getFiles(function(f){ return f instanceof Folder; });
    for (var i = 0; i < subFolders.length; i++) {
        var folder = subFolders[i];
        var files = folder.getFiles(function(f){ 
            return f instanceof File && /\.(png|jpg|jpeg|tif|tiff|exr)$/i.test(f.name); 
        });
        if (files.length > 0) {
            var destFolder = new Folder(projectFolder.fsName + "/" + folder.name);
            if (!destFolder.exists) destFolder.create();
            for (var j = 0; j < files.length; j++) {
                var srcFile = files[j];
                var destFile = new File(destFolder.fsName + "/" + srcFile.name);
                if (destFile.exists) {
                    destFile = new File(destFolder.fsName + "/" + srcFile.name.replace(/(\.[^\.]+)$/, "_" + new Date().getTime() + "$1"));
                }
                var success = srcFile.copy(destFile);
                if (success) srcFile.remove();
            }
            folder.remove();
            $.writeln("移动完成：" + folder.name + " -> " + destFolder.fsName);
            // ---------------- 自动导入 PNG 序列前检查 ----------------
            var movedFiles = destFolder.getFiles(/\.(png)$/i).sort(function(a,b){
                return a.name.localeCompare(b.name, undefined, {numeric:true});
            });
            if (movedFiles.length > 0) {
                // 获取最后一帧
                var lastFrame = movedFiles[movedFiles.length - 1];
                var fileSize = lastFrame.length; // 字节数
                // ≤1MB 删除
                if (fileSize <= 1 * 1024 * 1024) {
                    $.writeln("最后一帧小于等于1MB，删除：" + lastFrame.name);
                    lastFrame.remove();
                    movedFiles.pop();
                } else {
                    $.writeln("最后一帧大于1MB，保留：" + lastFrame.name);
                }
                // 再导入序列
                if (movedFiles.length > 0) {
                    var firstFile = movedFiles[0];
                    var importOpts = new ImportOptions(firstFile);
                    importOpts.sequence = true;
                    importOpts.importAs = ImportAsType.FOOTAGE;
                    var importedFootage = app.project.importFile(importOpts);
                    importedFootage.parentFolder = toolboxFolder;
                    $.writeln("已导入序列：" + importedFootage.name);
                    var newLayer = comp.layers.add(importedFootage);
                    if (targetLayer) {
                        newLayer.moveBefore(targetLayer);
                    }
                }
            }
        }
    }

    // ---------------- 执行适合画面 ----------------
    app.executeCommand(2156);
    duiqi();
    // ---------------- 删除含 done.txt 的文件夹 ----------------
    var remainingFolders = sourceFolder.getFiles(function(f){ return f instanceof Folder; });
    for (var i = 0; i < remainingFolders.length; i++) {
        var f = remainingFolders[i];
        var doneFile = new File(f.fsName + "/done.txt");
        if (doneFile.exists) {
            deleteFolder(f);
            $.writeln("已删除文件夹：" + f.fsName);
        }
    }
    alert("处理完成！");
}

// 递归删除文件夹
function deleteFolder(folder) {
    var files = folder.getFiles();
    for (var i = 0; i < files.length; i++) {
        var f = files[i];
        if (f instanceof File) {
            f.remove();
        } else if (f instanceof Folder) {
            deleteFolder(f);
        }
    }
    folder.remove();
}

function duiqi() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先选中一个合成");
        return;
    }
    if (comp.selectedLayers.length < 1) {
        alert("请至少选择一个图层");
        return;
    }
    var selLayers = comp.selectedLayers;
    for (var i = 0; i < selLayers.length; i++) {
        var layer = selLayers[i];
        var layerIndex = layer.index;
        // 如果不是最底层（有下面图层）
        if (layerIndex < comp.numLayers) { 
            var belowLayer = comp.layer(layerIndex + 1);
            // 计算持续时间
            var duration = layer.outPoint - layer.inPoint;
            // 对齐入点
            layer.startTime = belowLayer.inPoint;
            // 保持持续时间
            layer.outPoint = layer.startTime + duration;
        }
    }
}


