function OUT2() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    if (comp.selectedLayers.length !== 1) return;
    var selectedLayer = comp.selectedLayers[0];
    var belowLayer = comp.layer(selectedLayer.index + 1);
    if (!belowLayer) return;
    var duration = belowLayer.outPoint - belowLayer.inPoint;
    var timeRemap = selectedLayer.property("ADBE Time Remapping");
    if (timeRemap.numKeys < 2) return;
    // 1. 记录第二关键帧信息
    var secondValue = timeRemap.keyValue(2);
    // 2. 调整出点
    selectedLayer.outPoint = selectedLayer.inPoint + duration;
    // 3. AE会自动插入一个新的最后关键帧 → 删除
    timeRemap.removeKey(timeRemap.numKeys);
    // 4. 计算新第二关键帧时间（出点前一帧）
    var newSecondKeyTime = selectedLayer.outPoint - (1 / comp.frameRate);
    // 5. 插入新的关键帧
    timeRemap.addKey(newSecondKeyTime);
    timeRemap.setValueAtTime(newSecondKeyTime, secondValue);
}



//合并帧2
MergeKeyButton.onClick = function() {
    app.beginUndoGroup("合并时间重映射关键帧");
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length < 1) {
            alert("没有选中任何图层。");
            return;
        }
        
        for (var j = 0; j < selectedLayers.length; j++) {
            var layer = selectedLayers[j];
            var timeRemapProperty = layer.property("ADBE Time Remapping");
            if (!timeRemapProperty || timeRemapProperty.numKeys < 2) {
                continue;
            }
            
            var keyframes = [];
            for (var i = 1; i <= timeRemapProperty.numKeys; i++) {
                var keyTime = timeRemapProperty.keyTime(i);
                if (layer.inPoint <= keyTime && keyTime <= layer.outPoint) {
                    keyframes.push(i);
                }
            }
            
            if (keyframes.length < 1) {
                continue;
            }
            
            var firstKeyframeTime = Math.max(timeRemapProperty.keyTime(keyframes[0]), layer.inPoint);
            var frameCounter = 0;

            for (var i = 0; i < keyframes.length; i++) {
                var keyIndex = keyframes[i];
                var keyframeValue = timeRemapProperty.keyValue(keyIndex);
                timeRemapProperty.removeKey(keyIndex);
                timeRemapProperty.setValueAtTime(firstKeyframeTime + (frameCounter / comp.frameRate), keyframeValue);
                frameCounter++;
            }
            layer.outPoint = firstKeyframeTime + (frameCounter / comp.frameRate);
        }
    }
    app.endUndoGroup();
};

