          function Keybtn() {
    function scanKeys(prop, result) {
        if (!prop) return;
        try {
            // 当前属性有关键帧
            if (prop.numKeys && prop.numKeys > 0) {
                for (var k = 1; k <= prop.numKeys; k++) {
                    var t = prop.keyTime(k);
                    if (t < result.first) result.first = t;
                    if (t > result.last) result.last = t;
                }
            }
            // 递归扫描所有子属性
            if (prop.numProperties && prop.numProperties > 0) {
                for (var i = 1; i <= prop.numProperties; i++) {
                    scanKeys(prop.property(i), result);
                }
            }
        } catch (err) {}
    }
    // 检查合成
    if (!(app.project.activeItem instanceof CompItem)) {
        return;
    }
    var comp = app.project.activeItem;
    var layers = comp.selectedLayers;
    if (layers.length === 0) {
        return;
    }
    var frameDuration = comp.frameDuration;
    // 遍历图层
    for (var l = 0; l < layers.length; l++) {
        var layer = layers[l];
        var result = {
            first: Infinity,
            last: -Infinity
        };
        // 从图层根属性开始递归扫描
        for (var i = 1; i <= layer.numProperties; i++) {
            scanKeys(layer.property(i), result);
        }
        try {
            var marker = layer.property("Marker");
            if (marker && marker.numKeys > 0) {
                for (var m = 1; m <= marker.numKeys; m++) {
                    var mt = marker.keyTime(m);
                    if (mt < result.first) result.first = mt;
                    if (mt > result.last) result.last = mt;
                }
            }
        } catch (err) {}
        // 设置图层时间
        if (result.first !== Infinity && result.last !== -Infinity) {
            layer.inPoint = result.first;
            // 多加1帧
            layer.outPoint = result.last + frameDuration;
        }
    }
}
   
    
