runRIFEButton.onClick = function () {
        // 补帧：先判断是否有选中的图层，没有则直接退出不执行
    if (!app.project.activeItem || app.project.activeItem.selectedLayers.length === 0) {
        alert("请先选中需要补帧的图层，再点击补帧按钮！");
        return; // 终止函数，不执行补帧
    }
    PrecomposeWithCurrentFrameRate();
    Export_RIFE();
};

function Export_RIFE() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    var layers = comp.selectedLayers;
    if (layers.length === 0) return;

    // ===== 保存原状态 =====
    $.global.__originComp__ = comp;
    $.global.__originLayerIndex__ = [];

    for (var i = 0; i < layers.length; i++) {
        $.global.__originLayerIndex__.push(layers[i].index);
    }

    // ===== 计算时间范围 =====
    var minIn = layers[0].inPoint;
    var maxOut = layers[0].outPoint;

    for (var i = 1; i < layers.length; i++) {
        var l = layers[i];
        if (l.inPoint < minIn) minIn = l.inPoint;
        if (l.outPoint > maxOut) maxOut = l.outPoint;
    }

    // ===== 创建临时合成 =====
    var newComp = app.project.items.addComp(
        "Temp_Comp",
        1920,
        1080,
        comp.pixelAspect,
        comp.duration,
        comp.frameRate
    );

    // ===== 排序 =====
    var indices = [];
    for (var i = 0; i < layers.length; i++) {
        indices.push(layers[i].index);
    }
    indices.sort(function (a, b) { return a - b; });

    // ===== 复制图层 =====
    for (var i = 0; i < indices.length; i++) {
        var src = comp.layer(indices[i]);
        var dst = newComp.layers.add(src.source);

        dst.startTime = src.startTime;
        dst.inPoint = src.inPoint;
        dst.outPoint = src.outPoint;

        try {
            var sp = src.property("Transform");
            var dp = dst.property("Transform");

            var props = ["Position", "Scale", "Rotation", "Opacity", "Anchor Point"];

            for (var p = 0; p < props.length; p++) {
                var s = sp.property(props[p]);
                var d = dp.property(props[p]);

                if (s && d) {
                    if (s.numKeys > 0) {
                        for (var k = 1; k <= s.numKeys; k++) {
                            d.setValueAtTime(s.keyTime(k), s.keyValue(k));
                        }
                    } else {
                        d.setValue(s.value);
                    }
                }
            }
        } catch (e) {}
    }

    // ===== 修剪 =====
    newComp.workAreaStart = minIn;
    newComp.workAreaDuration = maxOut - minIn;

    for (var i = 1; i <= newComp.numLayers; i++) {
        newComp.layer(i).startTime -= minIn;
    }

    newComp.duration = maxOut - minIn;
    newComp.workAreaStart = 0;

    // ===== 打开新合成 =====
    newComp.openInViewer();

    // ===== 外部函数 =====
    syncWorkAreaToComp();
    app.executeCommand(2156);
    Delete_the_render();
    mp4_frame_fill();

    // ===== 延迟删除 + 返回原合成 =====
    $.global.__deleteTempComp__ = function () {
        try {
            newComp.remove();
        } catch (e) {}

        // ===== 返回原合成 =====
        var origin = $.global.__originComp__;
        if (origin) {
            origin.openInViewer();

            // 恢复选择
            var idxs = $.global.__originLayerIndex__ || [];
            for (var i = 1; i <= origin.numLayers; i++) {
                origin.layer(i).selected = false;
            }
            for (var j = 0; j < idxs.length; j++) {
                try {
                    origin.layer(idxs[j]).selected = true;
                  //  openPrecompAndSelectAll();
                 //   origin.layer(idxs[j]).selected = true;
                   runRIFEA();
                } catch (e) {}
            }
        }
    };
    app.scheduleTask("__deleteTempComp__()", 500, false);
}
    
