function syncWorkAreaToComp() {
    try {
        if (!(app.project && app.project.activeItem && (app.project.activeItem instanceof CompItem))) {
            alert("请先打开一个合成！");
            return;
        }
        var comp = app.project.activeItem;
        app.beginUndoGroup("同步工作区到合成时间");
        // 设置工作区开始和持续时间
        comp.workAreaStart = comp.displayStartTime; // 工作区起点 = 合成开始时间
        comp.workAreaDuration = comp.duration;      // 工作区持续时间 = 合成总时长
        app.endUndoGroup();
    } catch (e) {
        alert("操作失败: " + e.toString());
    }
}

function mp4_frame_fill() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先打开一个合成");
        return;
    }
    if (comp.selectedLayers.length !== 1) {
        alert("请选择一个图层");
        return;
    }
    var layer = comp.selectedLayers[0];
    // 输出目录
    if(!toolboxFolder){
        alert("请先设置工具箱大师中转站路径")
        return;
    }
    var outFolder = new Folder(
        toolboxFolder.fsName + "/补帧"
    );

    if (!outFolder.exists) {
        if (!outFolder.create()) {
            alert("无法创建输出文件夹：" + outFolder.fsName);
            return;
        }
    }
    // 清理 Solo
    for (var i = 1; i <= comp.numLayers; i++) {
        comp.layer(i).solo = false;
    }
    layer.solo = true;
    // 添加渲染队列
    var rqItem = app.project.renderQueue.items.add(comp);
    rqItem.timeSpanStart = layer.inPoint;
    rqItem.timeSpanDuration = layer.outPoint - layer.inPoint;
    var om = rqItem.outputModule(1);
    try {
        om.applyTemplate("Lossless");
    } catch (e) {
        alert("找不到 Lossless 输出模板");
        return;
    }
    // 时间戳
    var now = new Date();
    var timeStr =
        now.getFullYear() +
        ("0" + (now.getMonth() + 1)).slice(-2) +
        ("0" + now.getDate()).slice(-2) + "_" +
        ("0" + now.getHours()).slice(-2) +
        ("0" + now.getMinutes()).slice(-2) +
        ("0" + now.getSeconds()).slice(-2);
    var name = layer.name.replace(/\.[^\.]+$/, "");
    var outputFile = new File(
        outFolder.fsName +
        "/" +
        name +
        "_" +
        timeStr +
        ".mp4"
    );
    om.file = outputFile;
    // 开始渲染
    app.project.renderQueue.render();
    // 清理 Render Queue（安全版）
    var rq = app.project.renderQueue;
    for (var r = rq.numItems; r >= 1; r--) {
        try {
            rq.item(r).remove();
        } catch (e) {}
    }
    // 恢复状态
    layer.solo = false;
    // 返回合成（优化顺序）
    comp.openInViewer();
}

