//删除视频
function deleteVideosInFolder() {
    // 获取脚本所在目录
    if(!toolboxFolder){
        alert(
            "请先设置工具箱大师中转站路径"
        );
        return;
    }
    var targetPath = toolboxFolder.fsName + "/补帧";
    var targetFolder = new Folder(targetPath);

    if (!targetFolder.exists) {
        alert("目录不存在: " + targetPath);
        return;
    }

    // 常见视频扩展名
    var videoExtensions = ["mp4","mov","avi","mkv","flv","wmv","mpeg","mpg"];

    // 获取文件夹下的所有文件
    var files = targetFolder.getFiles();
    for (var i = 0; i < files.length; i++) {
        var file = files[i];

        // 只处理文件，忽略子文件夹
        if (file instanceof File) {
            var name = file.name;
            var dotIndex = name.lastIndexOf(".");
            if (dotIndex > 0) {
                var ext = name.substring(dotIndex + 1).toLowerCase();

                // 判断扩展名是否在 videoExtensions 中
                var isVideo = false;
                for (var j = 0; j < videoExtensions.length; j++) {
                    if (ext === videoExtensions[j]) {
                        isVideo = true;
                        break;
                    }
                }

                if (isVideo) {
                    try {
                        file.remove(); // 删除文件
                        $.writeln("已删除视频文件: " + file.name);
                    } catch (e) {
                        $.writeln("删除失败: " + file.name);
                    }
                }
            }
        }
    }
}

