function All_attributes(){
    app.beginUndoGroup("Reset Layers & Clear Error Expressions");
    removeTextAnimators();
    size();
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        // ✅ 记录选中图层索引
        var selectedIndex = [];
        for (var s = 0; s < selectedLayers.length; s++) {
            selectedIndex.push(selectedLayers[s].index);
        }
        if (selectedLayers.length > 0) {
            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                // ---------- 重置变换属性 ----------
                if (layer instanceof TextLayer || layer instanceof ShapeLayer) {
                    centerAnchorPoint(layer);
                } else {
                    resetProperty(layer.property("Anchor Point"), [layer.width / 2, layer.height / 2]);
                }
                resetProperty(layer.property("Position"), [comp.width / 2, comp.height / 2]);
                resetProperty(layer.property("Scale"), [100, 100]);
                resetProperty(layer.property("Rotation"), 0);
                resetProperty(layer.property("Opacity"), 100);
                // ---------- 移除效果 ----------
                var effects = layer.effect;
                if (effects) {
                    while (effects.numProperties > 0) {
                        effects.property(1).remove();
                    }
                }

                // ---------- 移除蒙版 ----------
                var masks = layer.property("Masks");
                if (masks) {
                    while (masks.numProperties > 0) {
                        masks.property(1).remove();
                    }
                }

                // ---------- 清除错误表达式 ----------
                clearErrorExpressions(layer);
            }
        }

        // ✅ 重新选中图层（关键）
        for (var r = 0; r < selectedIndex.length; r++) {
            comp.layer(selectedIndex[r]).selected = true;
        }
    }

    // ---------- 函数定义 ----------
    function resetProperty(property, defaultValue) {
        if (property) {
            if (property.canSetExpression && property.expression !== "") {
                property.expression = "";
            }
            while (property.numKeys > 0) {
                property.removeKey(property.numKeys);
            }
            if (property.isTimeVarying) {
                property.setValue(property.valueAtTime(property.time, false));
            } else {
                property.setValue(defaultValue);
            }
        }
    }

    function centerAnchorPoint(layer) {
        var bounds = layer.sourceRectAtTime(layer.time, false);
        var anchorX = bounds.left + (bounds.width / 2);
        var anchorY = bounds.top + (bounds.height / 2);
        var anchorPoint = layer.property("Anchor Point").value;

        var newAnchorPoint = [anchorX, anchorY];
        var newPosition = [
            layer.property("Position").value[0] + (newAnchorPoint[0] - anchorPoint[0]),
            layer.property("Position").value[1] + (newAnchorPoint[1] - anchorPoint[1])
        ];

        layer.property("Anchor Point").setValue(newAnchorPoint);
        layer.property("Position").setValue(newPosition);
    }

    function clearErrorExpressions(propertyGroup) {
        for (var j = 1; j <= propertyGroup.numProperties; j++) {
            var prop = propertyGroup.property(j);

            if (prop.propertyType === PropertyType.PROPERTY) {
                if (prop.canSetExpression && prop.expression !== "" && prop.expressionError !== "") {
                    prop.expression = "";
                }
            } else if (
                prop.propertyType === PropertyType.NAMED_GROUP ||
                prop.propertyType === PropertyType.INDEXED_GROUP
            ) {
                clearErrorExpressions(prop);
            }
        }
    }
    app.endUndoGroup();
};
function selectLayerStyles() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    var layers = comp.selectedLayers;
    if (layers.length === 0) return;
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        var ls = layer.property("ADBE Layer Styles");
        if (ls) {
            ls.selected = true; // 选中整个 Layer Styles 组
        }
    app.executeCommand(21)
    }
}
function removeTextAnimators() {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;
    var layers = comp.selectedLayers;
    if (layers.length === 0) {
        return;
    }
    var totalRemoved = 0;
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        // 只处理文本图层
        if (!(layer instanceof TextLayer)) continue;
        var textProps = layer.property("ADBE Text Properties");
        if (!textProps) continue;
        var animators = textProps.property("ADBE Text Animators");
        if (!animators || animators.numProperties === 0) continue;
        // 倒序删除 Animator
        for (var j = animators.numProperties; j >= 1; j--) {
            try {
                animators.property(j).remove();
                totalRemoved++;
            } catch (e) {}
        }
    }
}

