/* ---------- 预设文件夹 ---------- */

var scriptFile = new File($.fileName);
var scriptFolder = scriptFile.parent;
var selectedFolder = new Folder(scriptFolder.fsName + "/FFX/工具箱大师预设库");
if (!selectedFolder.exists){
    selectedFolder.create();
}
var allPresets = [];

/* ---------- 选择文件夹 ---------- */
btnSelectFolder.onClick = function (){
    var file = File.openDialog("请选择一个动画预设 (.ffx)", "*.ffx");
    if (file){
        selectedFolder = file.parent;
        loadPresetsFromFolder(selectedFolder);
    }
};


/* ---------- 加载预设 ---------- */

function loadPresetsFromFolder(folder){
    if(!folder) return;

    presetList.removeAll();
    allPresets = [];

    var files = folder.getFiles("*.ffx");

    for (var i=0;i<files.length;i++){

        var name = decodeURIComponent(files[i].name);

        allPresets.push(name);
        presetList.add("item",name);

    }

}


/* ---------- 搜索 ---------- */

nameInput.onChanging = function(){

    var searchText = nameInput.text.toLowerCase();

    presetList.removeAll();

    for (var i=0;i<allPresets.length;i++){

        var name = allPresets[i];

        if(name.toLowerCase().indexOf(searchText) !== -1){
            presetList.add("item",name);
        }

    }

};


/* ---------- 选择预设 ---------- */

presetList.onChange = function(){

    if(presetList.selection){

        nameInput.text = presetList.selection.text;

        applyAnimationPreset();

    }

    $.sleep(50);
    presetList.selection = null;

};


/* ---------- 保存预设 ---------- */

btnSavePreset.onClick = function(){

    var comp = app.project.activeItem;

    if(!(comp && comp instanceof CompItem)){
        alert("请先选择一个合成！");
        return;
    }

    var layers = comp.selectedLayers;

    if(layers.length === 0){
        alert("请先选择一个图层！");
        return;
    }

    app.beginUndoGroup("保存动画预设");

    app.executeCommand(3075);

    app.endUndoGroup();

    alert("预设已保存!");

    loadPresetsFromFolder(selectedFolder);

};


/* ---------- 应用预设 ---------- */

function applyAnimationPreset(){

    var comp = app.project.activeItem;

    if(!(comp && comp instanceof CompItem)){
        return;
    }

    var layers = comp.selectedLayers;

    if(layers.length === 0){
        return;
    }

    var preset = presetList.selection;

    if(!preset || !selectedFolder){
        return;
    }

    var presetFile = new File(selectedFolder.fsName + "/" + preset.text);

    if(!presetFile.exists){
        alert("预设文件未找到！");
        return;
    }

    app.beginUndoGroup("应用动画预设");

    for(var i=0;i<layers.length;i++){
        layers[i].applyPreset(presetFile);
    }

    app.endUndoGroup();

}


/* ---------- 默认加载 ---------- */

if(selectedFolder.exists){
    loadPresetsFromFolder(selectedFolder);
}


