// =================== 导入音频到合成 ===================
function importWavToComp(filename) {
    var file = new File(sfxFolder.fsName + "/" + filename);
    if (!file.exists) return;
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    app.beginUndoGroup("导入音频");

    var sfxFolderName = "SFX";
    var sfxFolderItem = null;
    for (var i = 1; i <= app.project.rootFolder.numItems; i++) {
        var item = app.project.rootFolder.item(i);
        if (item instanceof FolderItem && item.name === sfxFolderName) {
            sfxFolderItem = item;
            break;
        }
    }
    if (!sfxFolderItem) {
        sfxFolderItem = app.project.items.addFolder(sfxFolderName);
    }

    var importedItem = null;
    for (var j = 1; j <= sfxFolderItem.numItems; j++) {
        var existingItem = sfxFolderItem.item(j);
        if (existingItem instanceof FootageItem && existingItem.file) {
            if (existingItem.file.fsName === file.fsName) {
                importedItem = existingItem;
                break;
            }
        }
    }

    if (!importedItem) {
        importedItem = app.project.importFile(new ImportOptions(file));
        importedItem.parentFolder = sfxFolderItem;
    }

    var audioLayer = comp.layers.add(importedItem);
    audioLayer.moveToEnd();
    audioLayer.startTime = comp.time;
deselectProjectItems();
    app.endUndoGroup();
}

// =================== 预览音频 ===================
function previewWavByName(filename) {
    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) {
        alert("请先选中一个合成！");
        return;
    }
    var file = new File(sfxFolder.fsName + "/" + filename);
    if (!file.exists) return;

    app.beginUndoGroup("预听音频");

    var importedItem = app.project.importFile(new ImportOptions(file));
    if (importedItem instanceof FootageItem) {
        importedItem.openInViewer();
        var duration = importedItem.duration;
        app.executeCommand(10314); // 播放
        $.sleep(duration * 950);    // 注意：这里 sleep 时间单位是毫秒， 只是粗略估算，可根据需要调整
        app.executeCommand(10315); // 停止
        importedItem.remove();      // 删除素材
    }
    comp.openInViewer();

    app.endUndoGroup();
}

// =================== 手动过滤文件 ===================
function getFilteredFiles(keyword) {
    var result = [];
    var lowerKeyword = keyword.toLowerCase();
    for (var i = 0; i < files.length; i++) {
        var fname = decodeURI(files[i].name).toLowerCase();
        if (fname.indexOf(lowerKeyword) !== -1) {
            result.push(files[i]);
        }
    }
    return result;
}

// =================== 刷新页面按钮 ===================
function refreshPage() {
    if (buttonsGroup) {
        contentGroup.remove(buttonsGroup);
    }

    buttonsGroup = contentGroup.add("group");
    buttonsGroup.orientation = "column";
    buttonsGroup.alignChildren = ["fill","top"];
    buttonsGroup.spacing = 5;

    var filteredFiles = getFilteredFiles(searchBox.text);
    var start = currentPage * pageSize;
    var end = Math.min(start + pageSize, filteredFiles.length);

    for (var i = 0; i < pageSize; i++) {
        var file = filteredFiles[start + i];
        var group = buttonsGroup.add("group");
        group.orientation = "row";
        group.alignChildren = ["fill","top"];
        group.spacing = 5;
        group.margins = 1;

        if (file) {
            var name = decodeURI(file.name);
            var previewBtn = group.add("button", [0,0,120,25], name);
            previewBtn.onClick = (function(f){ return function(){ previewWavByName(f.name); } })(file);

            var importBtn = group.add("button", [0,0,40,25], "导入");
            importBtn.onClick = (function(f){ return function(){ importWavToComp(f.name); } })(file);
        } else {
            group.add("statictext", [0,0,120,25], "");
            group.add("statictext", [0,0,40,25], "");
        }
    }

    tab10.layout.layout(true);
}

// =================== 翻页按钮事件 ===================
prevBtn.onClick = function() {
    if (currentPage > 0) {
        currentPage--;
        refreshPage();
    }
};
nextBtn.onClick = function() {
    var filteredFiles = getFilteredFiles(searchBox.text);
    if ((currentPage + 1) * pageSize < filteredFiles.length) {
        currentPage++;
        refreshPage();
    }
};

// =================== 初始化 ===================
if (sfxFolder.exists) {
    files = sfxFolder.getFiles("*.wav");
    refreshPage();
}

