function Rain() {

    var comp = app.project.activeItem;
    if (!(comp && comp instanceof CompItem)) return;

    app.executeCommand(19);
    app.executeCommand(20);

    // ===== 先查找项目里是否已有“雨水”合成 =====
    var rainComp = null;

    for (var i = 1; i <= app.project.numItems; i++) {
        var item = app.project.item(i);
        if (item instanceof CompItem && item.name === "雨水") {
            rainComp = item;
            break;
        }
    }

    // ===== 如果没有 → 才导入 =====
    if (!rainComp) {

        var scriptFile = new File($.fileName);
        var scriptFolder = scriptFile.parent;
        var templateFile = new File(scriptFolder.fsName + "/FFX/模板/雨水镜头.aep");

        if (!templateFile.exists) {
            return;
        }

        var beforeCount = app.project.numItems;

        var importOptions = new ImportOptions(templateFile);
        importOptions.importAs = ImportAsType.PROJECT;
        app.project.importFile(importOptions);

        // ===== 再次查找导入的“雨水” =====
        for (var i = beforeCount + 1; i <= app.project.numItems; i++) {
            var item = app.project.item(i);
            if (item instanceof CompItem && item.name === "雨水") {
                rainComp = item;
                break;
            }
        }
    }

    if (!rainComp) {
        return;
    }

    // ===== 获取选中图层 =====
    var selected = comp.selectedLayers;
    var targetLayer = selected.length > 0 ? selected[0] : null;

    // ===== 加入时间线 =====
    var newLayer = comp.layers.add(rainComp);

    // ===== 放到指定位置 =====
    if (targetLayer) {
        newLayer.moveBefore(targetLayer);
    } else {
        newLayer.moveToBeginning();
    }
    app.beginUndoGroup("雨水镜头");
    // ===== 执行你的后续处理 =====
    Color_level();
    Matte_And_Glass();

    app.endUndoGroup();
}


function Color_level() {
    var comp = app.project.activeItem;
    if (!(comp && comp.selectedLayers.length > 0)) return;
    var layers = comp.selectedLayers;
    for (var i = 0; i < layers.length; i++) {
        var layer = layers[i];
        try {
            // ===== Levels =====
            var levels = layer.property("ADBE Effect Parade").addProperty("ADBE Easy Levels");
            if (levels) {
                // 尝试安全获取属性（防止编号变化）
                var prop = levels.property(4); // 输入白色通常是第4个
                if (prop) {
                    prop.setValue(0.05);
                }
            }
        } catch (e) {}
        try {
            // ===== UnMult =====
            layer.property("ADBE Effect Parade").addProperty("UnMult");
        } catch (e) {}
    }
}

function Matte_And_Glass() {
    var comp = app.project.activeItem;
    if (!(comp && comp.selectedLayers.length > 0)) return;
    var layers = comp.selectedLayers;
    for (var i = 0; i < layers.length; i++) {
        var matteLayer = layers[i];
        try {
            var targetIndex = matteLayer.index + 1;
            if (targetIndex > comp.numLayers) continue;
            var targetLayer = comp.layer(targetIndex);
            // ===== Alpha Matte =====
            targetLayer.trackMatteType = TrackMatteType.ALPHA;
            var fx = targetLayer.property("ADBE Effect Parade");
            // ===== CC Glass =====
            var glass = null;
            for (var j = 1; j <= fx.numProperties; j++) {
                if (fx.property(j).matchName === "CC Glass") {
                    glass = fx.property(j);
                    break;
                }
            }
            if (!glass) {
                glass = fx.addProperty("CC Glass");
            }
            if (glass) {
                var p2 = glass.property("CC Glass-0002"); // Bump Map
                var p4 = glass.property("CC Glass-0004"); // Height
                var p5 = glass.property("CC Glass-0005");
                var p6 = glass.property("CC Glass-0006");
                var p12 = glass.property("CC Glass-0012"); // Light Height
                if (p2) p2.setValue(matteLayer.index);
                if (p4) p4.setValue(11.7);
                if (p5) p5.setValue(75);
                if (p6) p6.setValue(355);
                if (p12) p12.setValue(100);
            }
            // ===== Exposure2（防重复版本）=====
            var hasExposure = false;
            for (var k = 1; k <= fx.numProperties; k++) {
                if (fx.property(k).matchName === "ADBE Exposure2") {
                    hasExposure = true;
                    var expFx = fx.property(k);
                    var exp = expFx.property("ADBE Exposure2-0003");
                    if (exp) exp.setValue(1.5);
                    break;
                }
            }
            if (!hasExposure) {
                var exposure = fx.addProperty("ADBE Exposure2");
                if (exposure) {
                    var exp2 = exposure.property("ADBE Exposure2-0003");
                    if (exp2) exp2.setValue(1);
                }
            }
        } catch (e) {}
    }
}

