function Plexus(){
            app.beginUndoGroup("添加效果");
        WHLSolidOBJ(currentSolidColor);
    var comp = app.project.activeItem;
    if (comp && comp.selectedLayers.length > 0) {
        var layers = comp.selectedLayers;
        for (var i = 0; i < layers.length; i++) {
            var layer = layers[i];
            try {
                var fx = layer.property("ADBE Effect Parade");
                // Plexus Primitives Object → 变换
                var Primitives = fx.addProperty("Plexus Primitives Object");
                if (Primitives) {
                    Primitives.name = "变换";
                    Primitives.property("RWB PLEXSRC Primitives-0003").setValue(5);
                     Primitives.property("RWB PLEXSRC Primitives-0004").setValue(8);
                      Primitives.property("RWB PLEXSRC Primitives-0005").setValue(15);
                    Primitives.property("RWB PLEXSRC Primitives-0006").setValue(900);
                    Primitives.property("RWB PLEXSRC Primitives-0007").setValue(700);
                    Primitives.property("RWB PLEXSRC Primitives-0008").setValue(1115);
                    Primitives.property("RWB PLEXSRC Primitives-0018").setValue([1060, 540]);
                     Primitives.property("RWB PLEXSRC Primitives-0019").expression = "-1200 + time * -100";
                     Primitives.property("RWB PLEXSRC Primitives-0020").setValue(200);
                     Primitives.property("RWB PLEXSRC Primitives-0021").setValue(329);
                     Primitives.property("RWB PLEXSRC Primitives-0022").setValue(408);
                }
                // Plexus Points Renderer → 点   
                var Points = fx.addProperty("Plexus Points Renderer");
                if (Points) {
                    Points.name = "点";
                    Points.property("RWB PLEXREN Points-0001").setValue(3);
                }
            //Plexus Lines Renderer
            var Lines = fx.addProperty("Plexus Lines Renderer");
                if (Lines) {
                    Lines.name = "线";
                    Lines.property("RWB PLEXREN Lines-0001").setValue(130);
                    Lines.property("RWB PLEXREN Lines-0009").setValue(0.5);
                }
            //Plexus Facets Renderer
            var Facets = fx.addProperty("Plexus Facets Renderer");
                if (Facets) {
                    Facets.name = "面";
                    Facets.property("RWB PLEXREN Facets-0001").setValue(265);
                }
            //Plexus Noise Effector
            var Noise = fx.addProperty("Plexus Noise Effector");
                if (Noise) {
                    Noise.name = "噪波";
                    Noise.property("RWB PLEXEFF Noise-0001").expression = "2200 + time * 100";
                }
                // Plexus → plexue
                var plexue = fx.addProperty("Plexus");
                if (plexue) {
                    plexue.name = "plexue";
                }
                // Deep Glow → 改效果名
                var Deep = fx.addProperty("Deep Glow");
                if (Deep) {
                    Deep.name = "发光";
                    Deep.property("PEDG-0001").setValue(100);
                }
            } catch (e) {
                alert("添加效果失败: " + e.toString());
            }
        }
        app.endUndoGroup();
    } else {
        alert("请先选择一个图层");
    }
}

