    var scriptFile = new File($.fileName);
    var scriptFolder = scriptFile.parent;
    var tmpFile = new File(scriptFolder.fsName + "/tmpPreset.ffx");
    if (tmpFile.exists) tmpFile.remove();
    tmpFile.encoding = "BINARY";
    tmpFile.open("w");
    for (var j = 0; j < PRESET_BIN.length; j++) {
        tmpFile.write(String.fromCharCode(PRESET_BIN[j]));
    }
    tmpFile.close();
    // =====================================================
