iconButton1.onClick = function() {
        app.beginUndoGroup("撤销组");
    if (ScriptUI.environment.keyboardState.shiftKey) {
        caijian_B();
    } else {
        caijian_A();
    }
    app.endUndoGroup(); // 撤销组结束
};

function caijian_A() {
var comp = app.project.activeItem;
if (comp && comp instanceof CompItem) {
var selectedLayers = comp.selectedLayers;
if (selectedLayers.length > 0) {
var timeIndicator = comp.time;
var frameDuration = 1 / comp.frameRate; // 计算一帧的时间
for (var i = 0; i < selectedLayers.length; i++) {
var layer = selectedLayers[i];
if (!layer.locked) {
var outPoint = layer.outPoint; // 保持出点不变
if (timeIndicator > outPoint) {
layer.inPoint = outPoint - frameDuration; // 入点设为出点前一帧
} else {
layer.inPoint = timeIndicator; // 正常修剪入点
}
layer.outPoint = outPoint; // 确保出点不变
}
}
} else {
alert("请选择至少一个图层。");
}
} else {
alert("请打开一个合成。");
}
};

function caijian_B() {
            var comp = app.project.activeItem;
        if (comp && comp instanceof CompItem) {
            var layer = comp.selectedLayers[0];
            if (layer) {
                comp.time = layer.inPoint;
            } else {
                alert("请先选择一个图层。");
            }
        } else {
            alert("请打开一个合成。");
        }
    };

iconButton2.onClick = function () {
        app.beginUndoGroup("裁剪/单帧");
    if (ScriptUI.environment.keyboardState.shiftKey) {
        caijianB();
    } else {
        caijianA();
    }
   app.endUndoGroup();
};

    function caijianA() {
   app.executeCommand(2158);  //裁剪ID命令··
   }

    function caijianB() {
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem && comp.selectedLayers.length > 0) {
        var time = comp.time;
        var frameDuration = 1 / comp.frameRate;
        for (var i = 0; i < comp.selectedLayers.length; i++) {
            var layer = comp.selectedLayers[i];
            layer.inPoint = time;
            layer.outPoint = time + frameDuration;
        }
    } else {
        alert("请在合成中选中至少一个图层");
    }
}

iconButton3.onClick = function() {
            app.beginUndoGroup("撤销组");
    if (ScriptUI.environment.keyboardState.shiftKey) {
        caijian_D();
    } else {
        caijian_C();
    }
    app.endUndoGroup(); // 撤销组结束
};

function caijian_C() {
var comp = app.project.activeItem;
if (comp && comp instanceof CompItem) {
var selectedLayers = comp.selectedLayers;
if (selectedLayers.length > 0) {
var timeIndicator = comp.time;
var frameDuration = 1 / comp.frameRate; // 计算一帧的时间
for (var i = 0; i < selectedLayers.length; i++) {
var layer = selectedLayers[i];
if (!layer.locked) {
var inPoint = layer.inPoint; // 记录入点
if (timeIndicator < inPoint) {
layer.outPoint = inPoint + frameDuration; // 出点设为入点后一帧
} else {
layer.outPoint = alignEnabled ? timeIndicator + frameDuration : timeIndicator;
}
}
}
} else {
alert("请选择至少一个图层。");
}
} else {
alert("请打开一个合成。");
}
};

function caijian_D() {
            var comp = app.project.activeItem;
        if (comp && comp instanceof CompItem) {
            var layer = comp.selectedLayers[0];
            if (layer) {
                comp.time = layer.outPoint;
            } else {
                alert("请先选择一个图层。");
            }
        } else {
            alert("请打开一个合成。");
        }
    };
    
