Button6.onClick = function() {
    offsetLayersToTimeIndicator();
};
function offsetLayersToTimeIndicator() {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        alert("请确保您选择了一个合成，并且选择了图层。");
        return;
    }

    // 获取时间指示器的位置
    var timeIndicator = comp.time;

    // 获取选中的图层
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length < 1) {
        alert("请选择一些图层，然后重试");
        return;
    }

    // 找到最靠前的入点
    var earliestInPoint = selectedLayers[0].inPoint;
    var earliestLayer = selectedLayers[0];
    for (var i = 1; i < selectedLayers.length; i++) {
        if (selectedLayers[i].inPoint < earliestInPoint) {
            earliestInPoint = selectedLayers[i].inPoint;
            earliestLayer = selectedLayers[i];
        }
    }

    // 开始执行偏移
    app.beginUndoGroup("图层偏移到时间指示器");

    // 先偏移最靠前的图层
    var earliestOffsetAmount = timeIndicator - earliestLayer.inPoint;
    earliestLayer.startTime += earliestOffsetAmount;

    // 然后偏移其他图层
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        if (layer !== earliestLayer) {
            var currentInPoint = layer.inPoint;

            // 计算与最靠前图层的相对位置
            var offsetAmount = timeIndicator - earliestInPoint;

            // 偏移图层
            layer.startTime += offsetAmount;
        }
    }

    app.endUndoGroup();
}

//图层偏移出点
Button7.onClick = function() {
    offsetLayersToTimeOutdicator();
};

function offsetLayersToTimeOutdicator() {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
        alert("请确保您选择了一个合成，并且选择了图层。");
        return;
    }

    // 获取时间指示器的位置
    var timeOutdicator = comp.time;

    // 获取选中的图层
    var selectedLayers = comp.selectedLayers;
    if (selectedLayers.length < 1) {
        alert("请选择一些图层，然后重试");
        return;
    }

    // 找到最靠后的出点
    var LatestOutPoint = selectedLayers[0].outPoint;
    var LatestLayer = selectedLayers[0];
    for (var i = 1; i < selectedLayers.length; i++) {  
        if (selectedLayers[i].outPoint > LatestOutPoint) {
            LatestOutPoint = selectedLayers[i].outPoint;
            LatestLayer = selectedLayers[i];
        }
    }

    // 开始执行偏移
    app.beginUndoGroup("图层偏移到时间指示器");

    // 先偏移最靠后的图层
    var LatestOffsetAmount = timeOutdicator - LatestLayer.outPoint;
    LatestLayer.startTime += LatestOffsetAmount;

    // 然后偏移其他图层
    for (var i = 0; i < selectedLayers.length; i++) {
        var layer = selectedLayers[i];
        if (layer !== LatestLayer) {
            var currentOutPoint = layer.outPoint;

            // 计算与最靠前图层的相对位置
            var offsetAmount = timeOutdicator - LatestOutPoint;

            // 偏移图层
            layer.startTime += offsetAmount;
        }
    }

    app.endUndoGroup();
}

// 为“下移图层”按钮添加点击事件
Button9.onClick = function() {
Move_down();
}
function Move_down() { 
    var comp = app.project.activeItem;
    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;
        if (selectedLayers.length > 0) {
            // 按照图层索引从大到小排序
            selectedLayers.sort(function(a, b) {
                return b.index - a.index;
            });
            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                var currentIndex = layer.index;
                if (currentIndex < comp.layers.length) {
                    var nextLayer = comp.layer(currentIndex + 1);
                    layer.moveAfter(nextLayer);
                }
            }
        } else {
            alert("请先选择一个或多个图层");
        }
    } else {
        alert("当前没有合成打开");
    }
}

// 为“上移图层”按钮添加点击事件
Button8.onClick = function() {
    var comp = app.project.activeItem;

    if (comp && comp instanceof CompItem) {
        var selectedLayers = comp.selectedLayers;

        if (selectedLayers.length > 0) {
            app.beginUndoGroup("Move Layers Up");

            // 按照图层索引从小到大排序
            selectedLayers.sort(function(a, b) {
                return a.index - b.index;
            });

            for (var i = 0; i < selectedLayers.length; i++) {
                var layer = selectedLayers[i];
                var currentIndex = layer.index;

                if (currentIndex > 1) {
                    var previousLayer = comp.layer(currentIndex - 1);
                    layer.moveBefore(previousLayer);
                }
            }

            app.endUndoGroup();
        } else {
            alert("请先选择一个或多个图层");
        }
    } else {
        alert("当前没有合成打开");
    }
}

